/* 令和8年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r08.committeeSessions.push(...[{"id":"r08-20260119-6","meetingId":"r08-m01","date":"2026年1月19日","dateIso":"2026-01-19","committee":"区民委員会","time":"午後 １時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"しながわシティラン２０２６の開催に向けた進捗","agenda":"しながわシティラン２０２６の開催に向けた進捗","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"認知度も上がるといいと思いますが、それを踏まえまして、まず状況をもう少しお聞きしたいと思うのですが、エントリーで１０ｋｍのほうで、今回も区内と区外の方がいらっしゃると思うのですが、どういった内訳となっていますでしょうか。もう一点。","respondent":"守屋スポーツ推進課長","answer":"ただ、車いすチャレンジにつきましては、安全性というところもありますので、まず今年は１２人でやらせていただいて、その状況によっては、定員のところはまた考えていく必要があるかと思っているところです。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"細かい内訳、ありがとうあります。もう一点、今回、ウェーブスタートということで、道路規制の時間も、こちらの資料にあるとおりかと思うのですが、ウェーブスタートというのは、グループを区切って、やはりタイムの早い方からスタートされるのでしょうか。","respondent":"守屋スポーツ推進課長","answer":"１点目のウェーブスタートの関係なのですけれども、一応１,０００人と１,５００人の２グループに分けてスタートする予定です。委員おっしゃるとおり、早い方を前のグループ、遅い方を後ろにするという形になっております。","id":"exchange-002"},{"speaker":"こしば委員","kind":"質問","question":"私は前回大会は、どうしても所用があって伺えなかったのですけれども、その後、旧東海道の鮫洲辺りで飲食店を営んでいる方からお話を聞きまして、大変活気があったという話で、地域のほうでも応援させていただいたという話を聞いて、よかったとは思うのですけれども、話をする中で、一つ懸念点がありました。それがトイレの問題でした。","respondent":"守屋スポーツ推進課長","answer":"トイレのところで、基本的に今、設定しておりますのは、スタート地点である大井競馬場と、当然、区民公園でレースするほうには、そちらのほうに施設のトイレですとか、大井競馬場のほうには仮設トイレも設置しまして、対応します。","id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"区商連であったりだとか、町会・自治会、例えば大井第一地域センターだとか、コースの近くにある地域センターのほうにもぜひ呼びかけていただいて、多分、協力していただける方もいらっしゃると思いますので、ぜひその辺、広げていって、参加者の方があまり苦に思わず、安心してレースに臨めるような環境をつくっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"意見","question":"４の大会当日のイベント内容のところで、（２）の大井ホッケー場での吹奏楽と和太鼓の演奏があるということなのですが、私はこの吹奏楽は、公立の中学校の吹奏楽部の方々が演奏していただけるのかなと思っているのですが、もし決定しているようだったら、お聞かせください。","respondent":"守屋スポーツ推進課長","answer":"今、詳細は詰めているところなのですけれども、現状の予定といたしましては、八潮太鼓之会という八潮地区を中心に活動されている太鼓の会と、東海中学校の吹奏楽部のほうに出演をという形で調整を進めているところです。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"大井競馬場にステージがあって、吹奏楽と和太鼓は大井ホッケー場で、少し距離があるではないですか。大井競馬場と大井ホッケー場の動線、お客様を含めて、どういう動線の状態で。来てもらわないと駄目ではないですか。そこの詳細を教えていただきたいと思います。","respondent":"守屋スポーツ推進課長","answer":"大井ホッケー場と大井競馬場の違いというか、どういう考えかというところですが、まず一つは、大井競馬場のほうは、ステージイベントということで、様々なイベント、協賛ブース等を実施しておりますし、走っていない方とかご家族の方とかも。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ぜひそこら辺の集客含めて、これから周知していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"せらく委員","kind":"質問・要望","question":"昨年１０ｋｍを走りまして、１時間ちょっとで走り切ることができたのですけれども、大井競馬場でやっているステージのイベントが、走り切って着替えて一息ついたら、人も少なくなってきたな、盛り上がりがもう少し前にピークがあったのではないかなという空気が感じられまして、その辺り、イベントの実行委員、検討委員会の方とも共有していただいて、走り切った人が再度。","respondent":"守屋スポーツ推進課長","answer":"委員おっしゃるとおり、トップランナーでゴールした方と、結構最後でゴールした方で時間の差がありますし、ステージイベントというのは時間帯が決まっているところの中で進めていくのですけれども、どのタイムでゴールしてもというか。","id":"exchange-008"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"そもそも価値観の多様化だとか、人口の流動性だとか書かれていますけれども、なぜ現役世代の方々が地域のコミュニティに入ってこないのかというのが、様々理由はありますけれども、結局、意識の問題なのかなというのはすごく感じていまして、先般、地域センター所長とも話をしたら、町会・自治会というのは、何で集まるのかというと、やはりいざ地域の中で、例えば大災害が起きた、大地震が起きたときに。","respondent":"平原地域活動課長","answer":"実際に、では何を期待していますかというと、やはり今お話があったように、防災、あるいは日常的な防犯、こういったところがほかよりも多い項目であったのですけれども、ご存じのとおり、町会・自治会は防災についても防犯についてもかなり中心的な取組としてやっているのですが。","id":"exchange-009","title":"町会・自治会支援"},{"speaker":"こしば委員","kind":"質問","question":"だからこそ、なぜこの取組が必要なのかというところ、行事によっては、餅つき大会だとか、例大祭でお菓子を配ったりとかするのですけれども、そういうときはたくさん、自分の町会に住んでいないような方もいらっしゃることもあって、それはそれでいいのですけれども、ふだんの防災訓練にはなかなか足を運んでくれない、そういったことがありますので。","respondent":"平原地域活動課長","answer":"続きまして、地域間格差がないようにというようなお話でございましたけれども、伴走型支援に当たりましては、年度当初、私を中心に全１３地域を回らせていただいて、制度のご紹介。","id":"exchange-010"},{"speaker":"こしば委員","kind":"質問・要望","question":"地域間格差のところの話だと、必ず年度初めに、課長はじめ説明に各地域センターに上がっているという話、理解いたしました。マンションとの関係構築支援というのが、新しくプログラムが伴走支援の中でなされている中で、令和７年度に関係構築支援があったということなのですけれども、具体的にどういう内容だったのか教えてもらっていいですか。","respondent":"平原地域活動課長","answer":"これにつきましては、当委員会で年度当初にご説明申し上げまして、現物もお配りさせていただいたところですけれども、マンションができても、なかなかどのようにアプローチしていいか分からない、アプローチしたとしても、どういうふうに話を持っていっていいか分からない。","id":"exchange-011"},{"speaker":"こしば委員","kind":"意見","question":"実際、起こってからだと遅いのですけれども、逆に起こったことで大きく気づきを与えられることというのは多分、多々あると思いますので、そういった事例があったということを、品川区にどのくらいの集合住宅があるのか分かりませんけれども、こういったことで町会の活動に参加するようになったのだという、そういった事例を、お作りになっていると思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問","question":"回覧板自体が、あれがいやが応にもお隣の方と顔を合わせる機会にも昔はなっていたかと思いますけれども、今はそういったものもない中で、こういう防災・防犯に関心があるし、役に立つならやりたいという方がもしいらっしゃったとしても、入り口が分かりづらいといった面もあるかと思いまして、中には、そんな機会があるなら参加したいな、自分が知っていることや経験を役立てて。","respondent":"平原地域活動課長","answer":"マンションというのは非常に強い建物が多いので、例えば災害には強いですよという形になったとしても、大災害のときにそれが果たして継続性としてはいつまでなのか、そういったときに、では町会の人たちは一体、何をやっているのか、そういったことが見えてくると。","id":"exchange-013"},{"speaker":"おぎの委員","kind":"意見","question":"防災というのが前面に出てきていますが、私はそれでもいいと思います。本当に防災に強いまちというのは、人のつながりだと思いますので、この辺からどんどんいろいろな関係性を構築していったらいいと考えていますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/565411?Template=document&Id=7297#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":18345,"voices":45}},{"id":"r08-20260119-7","meetingId":"r08-m01","date":"2026年1月19日","dateIso":"2026-01-19","committee":"厚生委員会","time":"午後 １時００分～午後 ４時１６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","topics":[{"id":"topic-01","title":"令和７年陳情第５７号、誰一人とりこぼさない品川区のために、真のニーズ分析から、優先的に対応すべき事業を踏まえた障害福祉計画を策定するよう、区に求める陳情","agenda":"令和７年陳情第５７号、誰一人とりこぼさない品川区のために、真のニーズ分析から、優先的に対応すべき事業を踏まえた障害福祉計画を策定するよう、区に求める陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほどもニーズを反映させていくということでのご説明だったと思うのですけれども、そのニーズの分析というのをどうやるのかというところがここで問われているのだと思うのですが、この陳情の下から５行目ぐらいなのですけれども、行政機関が対応すべきニーズであるかは、求められている要望の性質、当事者の家族環境、区内の施設設置状況、福祉サービスの状況など、様々な要素を踏まえて。","respondent":"佐藤障害者施策推進課長","answer":"そういった部分については、既存のサービスですとか施設、そういったところで対応できるもの、それから、さらなる支援が必要なもの、そういったところを踏まえて、個別の相談支援等も踏まえて、支援を充足する必要があると考えているところです。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは毎回、この調査の結果の報告のときに、そこのところは、それをどう見るかというところの評価、分析というのが区として必要なのではないかというのは意見としても申し上げてきたところなのですけれども、そういうところで、一つ一つアンケートで答えられた中身について、区としてどう評価をして、分析をして、計画に反映させていくのかというのが求められるのではないかと思うのですが。","respondent":"佐藤障害者施策推進課長","answer":"それをもって、その内容がどういった状況から来ているものであるとか、先ほど申し上げたようなところで、例えば、属性ごとにこういった課題があるのではないかとか、そういったところの分析、そこについては、策定委員会等の検討の際も含めて、事務局としましても。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことで出していくことになっていくと思いますので、そういう形では、新たにニーズの分析というのは必要になってくるのかと思っているのですけれども、そこら辺はどう考えられているかということと、私は、世田谷区のような形で所要量を出して。","respondent":"佐藤障害者施策推進課長","answer":"今回、次期の計画のところで必要量のお示しというところではさせていただきたいと考えておりますが、整備の計画、方針をどこまで具体的にできるかというのは、現在の時点ではそこにつきましても検討させていただきたいです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それともう一つ、ここで言われているのが、「次に」というところで、２ページの、災害時に利用者の安全が確保されていない障害者施設等の公共施設があって、特に障害者施設は老朽化した既存不適格なものが多く、耐震や耐火性能のない昇降機、スロープや、待機スペースのない避難経路など、大変危険な状況に置かれていますということで書かれているのですけれども、品川区の施設の状況というのが。","respondent":"佐藤障害者施策推進課長","answer":"こちらの陳情に、心身障害者福祉会館の改築等についても記載いただいておりますけれども、ここについても、陳情に書いてあるとおりになりますが、全体的な施設の老朽化等も踏まえまして。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"確認","question":"建築基準法とかが年代によって変わってきますので、前のときは合法的だったものが、今は既存不適格ということになっている。それでも、区としては安全対策はきちんと取っているということでの認識だということで確認させていただいていいでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"先ほど申し上げたように、安全性ですとか、利用者の使用に当たっての部分について対応が必要なものについては対応しておりますし、それから、別の形で改築や改修等に入ったときに対応しているものもあると認識しておりますので、繰り返しになりますけれども。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"基本的なことから確認させていただきたいのですが、陳情者の方がおっしゃっている陳情の理由のところに、全区民アンケートのところの記述があって、その前段階で、先ほど課長からご説明のあった基礎調査、ヒアリングだったり、アンケートだったり、パブリックコメントというのもあるということがあるのですが、この障害福祉計画の改定において、ＡＩ云々と書いてありますけれども。","respondent":"佐藤障害者施策推進課長","answer":"アンケート調査の数ですけれども、今回、次期の障害福祉計画の策定に向けまして、９月の下旬頃からアンケート調査の発送等を行って実施しています。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"確認","question":"先ほどお伺いすればよかったのですけれども、障害者団体のヒアリングも行われているということでしたが、これは今回の改定に当たっては全部終わったのかということと、どれぐらいの団体にヒアリングを行って、各種、様々な障害種別があると思うのですけれども、どのようなというか、幾つの団体と行われたのかということと、あと、こちらの今回陳情を出されているところも行われたのかどうか。","respondent":"佐藤障害者施策推進課長","answer":"団体ヒアリングへのご質問です。こちらにつきましては、予定していた団体については、昨年中、１０月までに終了している状況です。対象は、今、正確な数字が手元に、十二、三だったかと思いますが、確認させていただければと思います。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"意見","question":"ありがとうございました。当然、障害福祉計画の改定ということで、当たり前の話ですけれども、当事者、利用者の方、手帳の所持者の方と、代表的な団体、十二、三というお話がありましたが、そこからお話を聞いて、６,０００名のうち、前回は４０％というお話がありましたが、聞くべきところには聞いているという感触は私も受けました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"障害者団体への調査については、この方からもヒアリングは受けたということで、しかも、前のときはコンサルの方しかいらっしゃらなかったのに、このたびはきちんと職員の方も来てくださって、直接聞いてくれたということで、だから、そういう意味では一歩ずつ進んでいるのかなというのはあるのですけれども、団体については、主には障害者７団体と言われますけれども、ここの団体も入っておりませんし。","respondent":"佐藤障害者施策推進課長","answer":"例えば、放課後等デイサービスの事業所の充実のために事業者への支援策を実施するですとか、そういったところについては、状況も踏まえて検討して実施していますので、そういった対応があります。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"一方で、取り組みやすい福祉施策については、それを進めるなとは言いにくいですけれども、やはりそこにたくさん実績を出すという力があるのであれば、より困難な立場の方たちへのサービスの提供というほうを計画の中で優先順位を高めるべきではないかというのがこの陳情の趣旨だと思いますので、それはほかのサービスはやってはいけないということではなくて、優先順位の高いものをきちんと分析して出して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"意見","question":"陳情審査なのですけれども、ただ、これも障害者施設でも、例えば、旗の台の心身障害者支援施設も、あのエレベーター、戸開走行ついていないと思います。既存不適格はここにも関係しているので、それを意見として申し上げております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"様々な質疑がありましたので、私のほうでは１つだけ。この陳情の中の一番最後のところで、品川区は２３区最低の障害福祉のまちだと書かれておりますけれども、区としての受け止めと、今後どのように障害者福祉をしていきたいかという思いというか、意気込みがありましたら、お話を聞かせていただきたい。","respondent":"佐藤障害者施策推進課長","answer":"障害福祉計画、今期の部分につきましても、基本方針で、地域で安心して暮らすことができる、自分らしく生き生きと暮らすことができる、すべての人が共に支え合い暮らすことができるというようなところを方針として、障害者施策の展開、充実を図っているところですので。","id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"確認","question":"今ご答弁があったように、さらなる充実をしっかりと図っていくというようなところで確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"えのした副委員長","kind":"意見","question":"本日結論を出すで、不採択です。これから策定にかかるわけですけれども、そういったニーズを反映して策定するというご答弁もありましたし、区民の方に寄り添った障害福祉計画の策定をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出すで、不採択です。質疑もさせていただきましたが、基礎調査というところでは、これはそれほど異論はないのでしょうけれども、障害者団体、そして、サービスの利用者、当事者の方からの意見は一定程度というか、ほぼ聞いていらっしゃるということは確認ができました。先ほども申し上げましたが、この方が、陳情の趣旨は、優先的に対応すべき事業を実施計画に上げると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これまでの計画のときに、品川区は見込み量しか出さなかったというのでずっと来たわけですけれども、そこに必要量を出していただきたいということでずっとご意見を申し上げてきましたが、そういう方向で検討するということで、必要量をしっかり出すには、ニーズの分析をして、そこに反映をさせていくということなしには必要量は出すことはできないのかと思いますので、ニーズを分析した上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"吉田委員","kind":"意見","question":"私としては、本当にこの内容というのはもっともであり、私の理解の問題かもしれないですけれども、自立支援協議会とか、こういう計画の推進のために障害者団体の方たちが参加しておられるところでも、似たようなご意見は、もう少しきちんと必要量を把握してほしいというご意見も出てきていますし、分析の仕方についても、非常に皆さん穏やかな言い方ではありますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いいたします。質疑の中で、基礎調査を区はしっかりやっていただいているというのは恐らく共通認識としてあったのではないかと思います。世田谷区等の事例もありますけれども、こういったところで、さらにもう一歩、品川区の障害者福祉、前へ進めていけるのではないかと思いまして、私は趣旨採択ということでお願いできればと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"田中委員長","kind":"質問・要望","question":"可否が同数です。その上で、今現在、品川区においてその事業が行われているのかどうか、先ほどの質疑を通じて伺ってまいりました。よって、令和７年陳情第５７号、誰一人とりこぼさない品川区のために、真のニーズ分析から、優先的に対応すべき事業を踏まえた障害福祉計画を策定するよう、区に求める陳情につきましては、不採択すべきものと決定いたします。以上で、請願・陳情審査を終了いたします。","respondent":"佐藤障害者施策推進課長","answer":"本件は、児童福祉法に基づき、区内の指定障害児通所支援事業所に対して実施した監査におきまして、不正請求等が確認されたことから、運営法人に対し行政処分を行い、今後、運営法人に対し、不正に受給した給付費の返還を命じることを報告するものです。１、事業所の概要です。","id":"exchange-019"}]},{"id":"topic-02","title":"指定障害児通所支援事業者の行政処分","agenda":"指定障害児通所支援事業者の行政処分","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"監査を実施したということは、これは品川区が監査をしたということなのでしょうか。そもそもチェックする機関というのは、品川区の権限なのか、東京都の権限なのか、そこら辺のところも具体的に教えていただきたいのと、その監査というのは、品川区が行ったのであれば、聞き取りだったりとか、行為を確認ということで書いてあるのですけれども、誰が行ったのかということを教えてください。","respondent":"佐藤障害者施策推進課長","answer":"事業者への指導検査ですとか、運営指導と言っておりますけれども、こちらについては、おおむね３年に１回、各事業所を回るようにというところで東京都からもございまして、それに対応できるような形で順次見回っていたところです。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"それなので、すごく人員体制も、本当に看護師も非常勤含めると４人、それから、理学療法士も非常勤ですけれども２名、保育士もいたり、児童指導員の方が非常勤も入れて３名だったりとかという形で、トータルすると１３名みたいな、ホームページでは書かれていたのですけれども、かなり手厚い職員体制でされていたと思うのですが、そういう中での職員確保の状況というのは区としてはどう捉えているのか。","respondent":"寺嶋福祉部長、佐藤障害者施策推進課長","answer":"ただし、所管課長が申し上げたかったのは、それが東京都の基準、それから、施設数、職員数等々で、やはり３年に１回ぐらいの検査が現実的だろうということと、きちんとやっていれば、３年に１回きちんと定期的にチェックをして。こちらの事業所の登録者数等々に関しては、持ち合わせてございません。定員としては５名ということで、ほかの放課後等デイサービスと同様に実施されているところかと認識しております。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"放課後等デイサービスがかなりすごく増えてきていますし、それでもまだまだ足りないということなので、区が誘致をして、さらに要望に応えられるようにということで努力をしていただいているところだと思うのですけれども、そういう点では、放課後等デイサービスの質的なものも含めて、実態をしっかりと把握をしていただいて、よりよいサービスにつながっていくようによろしくお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"例えばということで言うと、預かっている間、テレビを見せているだけとか、そのような放課後等デイサービス、もちろんいいところもたくさんあるけれども、そういうところもあるというご意見は伺っていて、その辺の点検というか、監査というか、はどうなっているのかというのは気にはなっていたのですけれども、その当時から、こういう形での３年に１回現場を見に行くとか。","respondent":"佐藤障害者施策推進課長","answer":"利用者の方からそういったケアの内容といいますか、支援の内容、療育の内容についてご意見、それから、事業者へ改善を申し入れてほしいといったようなお声をいただくこともあります。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"結構、そういうご意見は伺っていて、一方で、利用者にしてみたら、指摘をすることによって預ける先がなくなってしまうというような、それも困るというような感覚もあり、先ほどの陳情につながるけれども、でも、療育を求めて放課後等デイサービスに通わせるわけだから、そこはそういうふさわしい事業が行われているかどうかというのは、区として何かきちんと確認する手だてが。","respondent":"佐藤障害者施策推進課長","answer":"個別の申出に対して、そういった指摘をすると、利用者の方が不利益というか、受けるのではないかというお話もありましたけれども、当然、匿名等での部分についても対応しておりますし、きちんとお名前等をおっしゃっていただいた方につきましても。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、やはりそこで区のチェックとかがすごく重要になってくると思いますので、その辺について、今後はきちんと見極めた形での運営、きちんとしたところには補助するけれども、そうでないところはきちんと厳しい目でチェックしていくということを、区としての権限に限りがあるかもしれませんけれども、その視点でぜひ運営を促していっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"確認","question":"いろいろありがとうございました。２点目は、これは機能訓練担当職員の勤務実態がないというところ、これについてどのように改善をするのかというところ。そういう人的リソースについても、この事業者がしっかりそこは手当てできるのかというところについて確認をさせてください。","respondent":"佐藤障害者施策推進課長","answer":"ほか２つに関しましても、人員を満たすというようなところで加算をつけていたというところで、実際にはいなかったというところにはなりますけれども、こちらについても、放課後等デイサービスそのものの、事業の実施に対して、例えば、５人いなければいけないところを３人で。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。内部の方でしか知り得ないような情報で、多分、そういったところでの情報なのかと思うのですけれども、こういったことが起きるということで、先ほど監査というお話がありましたが、事業所のところが、慢性的に例えば人員不足になっているとか、そういったところについては大丈夫だということで品川区で確認をしたということでいいのか、最後に聞かせてください。","respondent":"佐藤障害者施策推進課長","answer":"委員おっしゃるとおり、事業運営に関しましても、基準となる職員体制は確保されております。加算等につきましては、適正に対応されるというところで確認をしています。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"確認","question":"１つ、まず、言葉の定義といいますか、確認なのですけれども、実地調査というのは、主に３年に１回程度行う、事業所に適正に行われているかという検査で、監査というのは、何か不正がある疑いがあったりして、本格的に区がしっかり不正の有無について調べる、そういった位置づけでよろしいのでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"そこの内容が不正であったりというようなところで、処分を含めて、さらに確認等が必要というところで、監査を実施したというようなところがあります。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"確認","question":"これはすみません、私の意見というか、実態をお話しさせていただきました。それで、質問のほうに入るのですけれども、このミントなのですけれども、２０１９年、平成３１年開設ということで、ちょうど今７年たった頃ぐらいだと思いますが、実際、直近で実地調査、令和７年５月に内部のリークがあって実地検査を行ったのですけれども、これは通算でいえば何回目の実地検査になるのでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"ミントへの指導等に関しては、こちら、回数の履歴に関してまでは手元にございませんが、前回、令和４年６月に運営指導については実施しております。","id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"確認","question":"分かりました。開設して１回目の検査が令和４年にあって、２回目が令和７年ということで確認できました。答えは明白かもしれないですけれども、そういったことについては何か事業者側からの回答というか、弁明はあったのでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"不正ですので、加算を意図的に請求するというところで、実態のない書類上の体制等でもって受給したというところで、その辺りは給付費を多く取るというところでの意図的に行われたものと認識しています。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ほかにも何か事業所があるみたいな記載もありますけれども、どれぐらいの規模の会社なのかというのがもし分かれば教えていただきたいです。","respondent":"佐藤障害者施策推進課長","answer":"こちらの運営法人としては、放課後等デイサービスはこちらの区内のミント１か所のみを実施しています。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"確認","question":"いつどのタイミングで、どういう形式で、一括なのか分割なのかとか含めて、そういったことが、支払いというのは特にまだ決まっていないのかどうかということの確認と、要は、先ほどの何で不正したのかという理由を私が、弁明があったのかを聞いたことにつながるのですけれども、やはり当然、売上げを上げたかった、たくさん報酬を得たかったというところで、さらに一歩進めば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひしっかり厳しく、こういったことがあったので、伴走していただければと思いますし、区がこういった障害者福祉含め、高齢者の介護のほうも実地検査をしっかりしていただいているというのは私も身もって認識しておりますので、なかなか結構皆さん大変な思いをして、調査する側もされる側も結構大変な感じでやっておりますので、ぜひ余裕を持ってお伺いできるような、そういったマンパワーの増強も含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-03","title":"介護保険事業計画改定に伴う日常生活圏域ニーズ調査","agenda":"介護保険事業計画改定に伴う日常生活圏域ニーズ調査","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これも私もずっと全部、自分だったらどうかという思いでやってみたのですけれども、これをまとめたからといって、本当に品川区の介護の課題、それから深刻な実態、そのようなものはなかなか見えてこないのではないかと思うのですが、そこら辺のところはもっと区独自のものというのが、９項目から入れられるということであれば。","respondent":"菅野高齢者福祉課長","answer":"最後に、自由記述欄がこのニーズ調査にはないというところのお話だったのですが、先ほども申し上げました、在宅サービス利用者へ毎年モニタリングアンケートということを実施していますが、その中で自由記述という部分がございまして。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう方に対しても、家族だったりとか、それから、要支援でサービスを使っている方も含まれるわけですから、そこのところの方々にも、ぜひ自由記述欄というのは作っていただいて、要望だったりとか実態というのが見える形にぜひとも、これは本当に自由記述欄を設ければ済むことだけなので、そういうことというのは可能ではないかと思いますので、ぜひ自由記述欄は作っていただきたいと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回、このアンケートの設問の内容の中で、もしかしたら先ほど少し話題になったモニタリングアンケートのほうで実施しているのかもしれませんけれども、高齢者の交通の足といいますか、そういったことについて特に設問がなかったのですが、こういったふだんの買物とか通院もそうだし、まさに地域活動にアクセスするための交通についてもあったほうがよかったかなと思ったりするのですけれども、その点。","respondent":"菅野高齢者福祉課長","answer":"今回のニーズ調査の中にはその設問項目は含まれておりませんが、在宅介護支援センター等のケアマネジャー等も通じながら、どういった実態なのかというところは常時把握していきたいと思います。","id":"exchange-036"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"もしかしたら最短でこの委員会での発表というタイミングになってしまったのかもしれないですけれども、できれば事前にこういう、ここにも一応、３ページ目のところに赤いはんこで「案」と書いてあるので、ぜひここはやはり様々な意見が出て、活発な厚生委員会ですので、ここで意見を拾っていただいて、さらにブラッシュアップして調査を実施していただければいいと思いました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-04","title":"生活扶助基準改定に関する最高裁判決への対応","agenda":"生活扶助基準改定に関する最高裁判決への対応","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"それで、今ご説明のあった、令和元年９月以前のデータを読み起こして加工する手順というものが必要になると。リプレースをしたがゆえにということですけれども、これも２月の計算ツールのリリースの前にその作業というのはできるのですかというところが、まずそこを伺いたいと思います。リリースがないと、データの加工というのはできないのか、まずはそこをお伺いしたいと思います。","respondent":"豊嶋生活福祉課長","answer":"今のご質問ですが、できるかできないかという話であればできますが、それは今やれることとすると、人が全ての記録を全て読み起こして、データを加工しなければいけません。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"理解できました。１点だけ教えてください。原告というのは、品川区で抽出するのでしょうかというところ、その辺りが理解できないので、そこだけ教えてください。","respondent":"豊嶋生活福祉課長","answer":"何で原告のほうが金額が高いのかというのも、国から実は明確な説明があまりなかったもので、我々も、分厚い資料を読み起こせば出てくるのかもしれませんが、結局は最終的に計算ツールに当てはめて。","id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今、令和元年９月以前のデータの読み起こしという、システムそのものをつくっていくというところでは、そういうかかるお金というのがありますよね。それというのも国のほうから出るということになるのか、その点を１つ伺いたいと思います。ぜひ声を上げていっていただきたいと思うのですけれども、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、本当に生活保護の方々がそういう形で２０１３年から、言ってみれば違法な引下げによって本当に大変な状況を強いられてきたわけですから、本来であれば守るべきところが守られない、そのようなところはぜひ認識をしておいていただきたいということでお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"ご説明ありがとうございました。そういった方が全部、「地域で一人暮らしをしたい」とか、グループホームは全然変わっていないのですけれども、この３年間でなぜそのようになったのかというところ、どうしてこういう変化が起きたのかというところをまず教えていただきたいのが１点と、これ、対象者はどのような障害のある方なのでしょうか。そこを教えてください。","respondent":"佐藤障害者施策推進課長","answer":"数字の変化については、こちら、事実、はっきり確認できているところではございませんけれども、こちらの分析というか、状況としましては、１つは、施設以外の様々なサービス、在宅で受けられるサービスですとか、グループホーム等、そういったものも含めまして。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問","question":"コロナなども経て、いろいろこのニーズも変わったのかというところもあるのですが、やはり聞くところによると、そういうなかなか難しいニーズだと私も団体の方から視覚障害の方から伺ったりして、極端に言うと、私、町会の役員もやっていますけれども、町会の方たちなど、生まれ育ってずっと同じ地域にいて、みんな顔見知りだし、利害関係のない人たちで、裏表も全部分かっている人たちで。","respondent":"佐藤障害者施策推進課長","answer":"既存のグループホームですとか、新たに造るところの中で、視覚障害の方も十分に対応できるようなところで図っていけるのか。そこに特化したものが造れるのかといったところについては、検討してまいりたいです。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"一般の方の高齢者の方の特別養護老人ホームの入居でさえ、今なかなか難しい。ごめんなさい、所管が変わってしまうのですけれども、高齢者部門で、例えば、そういう視覚障害の方がそもそも特別養護老人ホームとかに申し込むのかどうかというところ。それとも、そもそも申し込まないのかというところ、そこだけ教えていただければと思います。把握していなければ把握していないで結構です。","respondent":"菅野高齢者福祉課長","answer":"ただ、要介護３以上というところで審査に通った後、施設で調整して、入所ということになる可能性もあることはあるのかとは捉えております。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはりそういった方は、恐らくその後の生活の困難さを考えると、そもそも申し込まない方が多いのかと。そういう方のお話も聞いたことがありますけれども、というところもある中で、そういった小さなニーズにもしっかり耳を傾けていただいて、高齢でお独り暮らしになってしまって、その後余生をどうやって過ごすのかというところで、そういった方にもしっかり目を向けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"これ、伺ってもお答えは難しいと思いつつ、でも、少し伺ってみたくなってしまうのですけれども、施設入所に関わる障害者福祉サービスの現状についてということで、それぞれ施設名と、それから数と、それから定員数が書いてあるのですが、区切って何年何月時点で言うしかないと思うのですけれども、定員数に対してどれぐらい利用されているかというようなデータというのは、基本。","respondent":"松山障害者支援課長","answer":"共同生活援助、グループホームにつきましては、それぞれその方々のニーズと合致すればということになりますが、種別が、知的障害の方向け、精神障害の方向けだったりするので、なかなか１か所ずつ定員に対してどうかというのが難しいところではありますが。","id":"exchange-046"},{"speaker":"吉田委員","kind":"確認","question":"今、報告をいただいたことに対してまた質問になってしまうので、ここからだんだんずれていってしまうかもしれないのですけれども、空いているというか、そういうことであれば、随時空いていますという広報はされているということでしょうか。少し確認だけさせてください。","respondent":"松山障害者支援課長","answer":"ご利用を促すために、相談支援事業所経由で、ぜひご利用くださいという形でご案内をしております。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"ということは、定期的に相談支援事業所に行きますよね。そういうときに要望とかを聞いて、しかるべき方には、こういうのが空いていますというような感じの情報提供ということでいいのでしょうか。","respondent":"松山障害者支援課長","answer":"ご本人の生活状況ですとかニーズは既に相談支援専門員はつかんでおり、この先の将来、どうしたいかというご希望もいただいておりますので、そういった方に合わせて、ぜひご利用くださいというご案内は随時しております。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"課題と取組みについてのところでの（２）番のところなのですけれども、地域生活移行の取組み開始から９人が地域生活移行が実現しましたということで書かれているのですが、自立支援協議会とかも傍聴させていただいているのですけれども、地域移行の分科会というのですか、そういうチームもできて、様々、意向調査とかも行いながら、すごく努力された結果、本当になかなかこれ。","respondent":"松山障害者支援課長","answer":"３点目、地域移行等意向確認担当者というのは、国が定めておりまして、全ての入所施設で選任された職員を置くということが令和８年度から義務づけられるということです。かがやき園と、かもめ園につきましても、来年度から選任される予定です。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今、施設入所の方が、品川区の定数としては１３０人の定数ということなのですけれども、実際に他の自治体、結構遠いところまで入られている方がたくさんいらっしゃると思うのですが、トータルで何人いるかというのが分かったら、教えていただきたいと思います。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"実績のほうについて、私のほうでお答えいたしますが、施設入所支援、資料の右上、（２）実績のところです。（２）の実績の短期入所の医療型、福祉型というのは、総合支援法の福祉サービスを使われた場合のものですので、区独自の医療ショートステイとはこちらは違うものになっております。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"一応伺ってみたいのですけれども、うち、近所だからどうしても気になってしまうのですが、東京都の児童相談所がありますよね。例えば、こういうところにどのように反映されるのだろうか、とても気になるし、障害者のグループホームを求めている方にとっても、あそこがどうなるのだろうかというのは気になるところで、これは今現在の入所施設のご報告なので、そうですけれども、いずれそこが検討されるのかと。","respondent":"佐藤障害者施策推進課長","answer":"という状況はありますので、当然、そこが今後どのようになるかというのについては、こちらとしても情報含めてございませんので、ここが空いて区が使えるとなったときに、ほかに入っている障害者施設との連携も含めて、適切な対応ができるというところはあるかもしれませんが。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問・要望","question":"必要性もあるのではないかと思います。ですので、なかなかきっちりしたご報告は、区だけで決められることではないので、難しいのは分かりますけれども、その辺についての情報提供とか、そういうのは一番必要とされている方たちと共有しながら、ぜひ適切な情報提供を今後していただけるように、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-06","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"すみません。この行政視察の報告書なのですけれども、せっかくこういう形で作ったものなので、これだけ税金も使いながら視察に行って、そういう形で報告書も作ったというところでは、これ、ホームページに公開するというところで、ぜひ意見も言っていただきたいと思いまして、そういう意見が出たということを言っていただけたらと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/145423?Template=document&Id=7295#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":53964,"voices":145}},{"id":"r08-20260119-8","meetingId":"r08-m01","date":"2026年1月19日","dateIso":"2026-01-19","committee":"建設委員会","time":"午後 １時００分～午後 ６時１７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を105件抜き出しています。","topics":[{"id":"topic-01","title":"請願・陳情審査および報告事項","agenda":"請願・陳情審査および報告事項","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"しかし、従来ルートでも、今、１時間当たり９０回の離発着が実際に行われているという実績も確認されているのです。このために区民生活を犠牲にするような航空政策については、この請願にあるように国に再検討を、求めるべきだと思うのです。この言葉を使われるのは初めてでよろしかったかの確認と、「市街地上空を通過しないルート」とは、つまり、何を求めたのかを改めて伺いたいと思います。","respondent":"高梨都市計画課長","answer":"今の答弁の中にも含まれておりましたけれども、市街地上空を飛ばないルートとして、国が今いろいろと固定化回避検討会の中で検討を進めているところでありますけれども、品川区民の負担が軽減されるような、品川区の上空を飛ばない、市街地の上空を飛ばない海上ルートを。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですか、分かりました。もう少しこの要請文について伺うのですが、第７回固定化回避検討会を受けて、海上ルートの実現に向けた今後の方向性が示されたというふうに、そういうふうに認識を示しているのです。その上で、「その検討を加速し」と要望しているのですけれども、国のどういう点を区は評価したのか、改めて伺いたいと思います。よろしくお願いします。","respondent":"高梨都市計画課長","answer":"私から先ほど説明させていただいた国が公表した資料７、今後の方向性についてというペーパーの中で、海上ルートの実現可能性を追求するというようなことが記載されてあります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"国に時期を切った検討を求めるべきなのではないかと思うのですけれども、いかがでしょうかというのが１つ。では、今の滑走路の使い方を前提にした上で、ＲＮＰ─ＡＲ技術を組み合わせたとして、私は、品川を含め、市街地を飛ばないルートは、正直なところ、にわかには実現できるとは思えないのですけれども、区の認識はいかがでしょうか。これ、実現できるのでしょうか、伺いたいと思います。","respondent":"高梨都市計画課長","answer":"今回、第６回固定化回避検討会から約１年が経過し、海外事例等でＲＮＰ─ＡＲ方式の適用事例等が示されたところです。国の資料としては、実現の可能性をこれから追求していくというような形で結ばれているところで、一定の時間はかかるのかなといったところがあります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"区が品川区を含む市街地を飛ばない海上ルートを求めたということは、それは非常に重要なことだと思っているのです。そこはそうなのですが、やはり私としては、もう一歩踏み込んで要望しないと、とも思います。今の検討の加速化をしてほしいと品川区が要望していますけれども、結論が出るまでは、新ルートを凍結するということも、ぜひ品川区として求めていただきたいのですが、いかがでしょうか。","respondent":"高梨都市計画課長","answer":"約１年たって、第７回では、海上ルートの実現を目標に、様々、海外事例等々の研究、検討を国のほうで進められているといったようなことで、前進といいますか、国の検討の進捗はしっかりあるのかなと感じているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"提案","question":"それがこの間、今日も出されていますが、様々な請願、陳情運動なども含めた住民の声も届いて、品川区としても、要望を重ねてきたなと思ってはいるのです。そういうことなので、ぜひ先ほどの提案についても今必要な要望ではないかと思うので、ぜひ検討していただきたいと思います。私は、少なくとも、品川区が求めたような海上ルート、市街地を飛ばない海上ルートは、議会としても要望すべきだと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"先に述べますと、私はこの請願に賛成です。ぜひ各委員の意見も伺いたいと思います。これまで６年間にわたって区民が羽田新ルートによって苦しめられているわけですから、ぜひそれを受け止めていただいて、まずは各委員の意見も表明していただきたいなと私も求めておきたいと思います。課長から説明があって、今のやり取りも伺いましたけれども、森澤区長の要望書について質疑をさせていただきたいと思います。","respondent":"高梨都市計画課長","answer":"この資料の中での海上ルート、３番目の質問にも関係してまいりますけれども、そこで言う海上ルートに従来ルートは含んでいないものであるというような認識をしています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは、いずれにしても、いわゆる海上ルートの検討について、森澤区長としては、固定化回避検討会に検討を求めているということでいいのかどうかを伺いたいと思います。私は以前から、この検討会はうさんくさいなと思っているというのが正直なところなのですけれども、森澤区長としては、この固定化回避検討会に検討を求めるものなのか、そこをどう考えているのか併せて伺いたいと思います。","respondent":"高梨都市計画課長","answer":"最初の確認の部分ですけれども、国は、現在の滑走路の使い方を前提として固定化回避検討会で検討しています。区としては、国の検討の中では、海上ルートの中に従来ルートは含まれていないと考えているところです。２番目の部分です。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"だんだん分かってきた。なぜならば、やはりＡ・Ｃ滑走路、従来ルートで増便が大前提ですから、やはりこうした検討会に期待を寄せるというのではなく、ここは国土交通大臣に対して、さっきの質問と同じですけれども、市街地上空を通過しない従来ルートに戻すよう、ここをきっぱりと示していくことが、今、必要な局面ではないかと思うのですけれども、改めていかがでしょうか。","respondent":"高梨都市計画課長","answer":"区としては、固定化回避検討会での検討結果をしっかりと早く示していただきたいといったところで要望してまいりたいと考えているところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言。国の検討を否定的に捉えるのではなくというお話がありました。実現の可能性を追求するということで、確かに追求するのだったら追求してくれと思いますけれども、一方で、６年間の区民の苦しみも国としては正面から受け止めるべきだと、区も引き続き、それを国に伝えていただきたいと要望したいと思います。最後に、各委員の皆さんに、ぜひまずはご意見を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"せお副委員長","kind":"質問・要望","question":"継続でお願いいたします。羽田新ルートについては、私が建設委員になって、初めて私個人の意見を述べますので、まず少し理由をお伝えします。区議会としては、私が議員になる前の平成３１年ですか、決議も出しておりますし、議会としても、同じ、そういった思いがあるところをまず前提としていただきたいというところです。最近ですと、先ほどご説明がありましたけれども、区からも何回か要望書を出している。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"松永委員","kind":"質問・要望","question":"我が会派としては、継続でお願いいたします。先ほど説明にもありましたとおり、品川区といたしましても、区民負担の軽減のルートを求めて要望書を出されている段階であり、また、固定化回避検討会でも議論を活発に進めていただきたいという思いから、今回のこちらの陳情に対しては、継続でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"意見","question":"継続でお願いします。固定化回避検討会で議論が継続中とのことです。第７回の検討会についても開催され、一定の進捗が示されたこともあります。あくまで固定化を回避する前提の検討会という認識でありますし、また、引き続き検討状況を見ていきたいというところもあるので、継続でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択をすべきだと思います。区は区でそれなりに頑張っている。なおかつ、品川区も発言を強めているという中ですから、私は、新たな決議が必要だと思います。即刻中止を求める陳情とありますけれども、私は、住民の苦境を取り除くためには、このルートは即刻中止をすべきだと思います。品川区議会の意思を示さなくてどうするのかと私は思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"区が要望を出しているからということですけれども、森澤区長としては、「海上ルート」という言葉を使っているわけですから、区議会としても新たに「海上ルート」という言葉をしっかり使った決議なり要望なりをすべきであって、審査を継続とする理由ではないと思います。なので、ここに期待をすることができないと思いますので、改めて採択すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"せお副委員長","kind":"意見","question":"継続でお願いいたします。私が先ほど言ったのは、国が検討途中だからです。ごめんなさい、私の言葉が足らずで、検討途中ですので、それを見守っていくという意味で継続とします。理由は、先ほどと同じです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択なのですが、陳情にありますように、従来の海上ルートに戻すこと、首都圏一極集中を避けるべきと国に求めるべきだと思いますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"結論を出すということと、採択でお願いいたします。先ほど、検討途中なので見守りたいという思いが示されましたけれども、森澤区長であっても、検討途中の固定化回避検討会に対して、アンケートの結果を背景に区としての要望を出しているわけです。区議会としても、むしろ結論が出る前の検討途中の今だからこそ声を上げるべきだと私は思いました。決議を出したのは、実際に飛ぶ前です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択です。今、この３４号の陳情をはじめとする区民の世論と運動を受けて、本陳情の最後にある都心ルート撤回に匹敵するような市街地上空を通過しない海上ルートを要請するに至ったと私たちは考えております。情勢としては陳情の趣旨にそって動いているなと思いますので、採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すということと、採択でお願いいたします。当時の森澤区長の、固定化回避を国に要請ということと、直近の要請では、市街地上空を通過しない海上ルートというところで、どう違うのかは質疑をしてみないと分からない部分もあるので、そこはそこで述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは本日結論を出すで、採択なのですが、タイトルが固定化回避検討状況を区民に説明するよう求める陳情ということです。飛ぶ前は１３か所に分かれて区内で説明会をやりました。これは説明してほしいという内容なので、なぜ継続にするのかということが分からない。説明することすら議会としては求めないのかということになってくると思うのです。私は、これは、当然、採択すべきなのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"結論を出すということと、採択でお願いいたします。今、説明がありましたけれども、この陳情は、検討会での検討内容を教室型説明会を開いて説明してほしいという内容です。継続とした理由が、検討中だとか、検討会で議論が起きているからという理由でしたが、なぜその理由が説明会の開催すら拒む理由になるのか。各会派はこうした区民の声にしっかり向き合っていただきたいなと述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"結論を出すということと、採択でお願いいたします。これも住民説明会の開催を求める請願なのです。なぜ説明会の開催を求める請願に対して継続とするのか、その理由が示されていないと思います。考えが異なることは、私はいけないことだと思っていません。ただ、理由を示して議論を深めるということが議会の役割だと私は思いますので、ぜひ委員の方のお考え、ご意見を伺いたいと求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"この請願も住民説明会の開催を求めるものなのです。ここまで来ると、なぜ説明会の開催をかたくなに拒むのかと私は思わざるを得ない。少なくとも検討しているものについて、中身を説明するということは当然、国土交通省に説明責任があると思うし、区民がそれを求めるのは当然だし、議会もそれを採択してこそ、議会の役割が発揮されると私は思いますと述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択なのですけれども、区議会として、やはり僅かばかりの増便のために区民生活を多大に犠牲にするような航空政策は国に再検討を求めるべきだと思いますし、それが新ルートに現在でも苦しむ区民を救うことにつながると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すということと、採択でお願いいたします。こちらの請願は、今日、議論、審議したものです。品川区議会として計画撤回を国と交渉してほしいという請願です。継続と主張された方からは、一切の理由が示されませんでした。違う、冒頭述べていた部分もありますね、失礼いたしました。いずれにしても、結論を出すべきだと思うし、採択すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-02","title":"令和７年陳情第５８号（品川浦南地区再開発）","agenda":"令和７年陳情第５８号（品川浦南地区再開発）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"陳情に国交省通達という言葉が出てくるのですけれども、それについて、内容について改めて教えていただきたいと思います。そして、品川浦周辺地区再開発に関する陳情ということで、改めて、地権者数といいますか、周辺の北地区、西地区、南地区、あと、北品川三丁目北地区、それぞれの土地所有者、借地権者、区分所有者数、もしくはマンション棟数など、こちらを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"最後、北品川三丁目北地区ですが、土地所有者数は１７名、借地権者数が１名、権利者数としては合計１８名、区分所有のマンションといたしましては３棟あると確認しています。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"かなりの人数がお住まいの地域です。かつて私たちも質問したように、１３の開発関連企業がここに集結しているということで、すさまじいところなのです。今回、国が要綱改正で、この地域の大部分を開発補助交付対象外としたのですけれども、そうであるならば、この陳情項目にありますように、区も、国の制度変更を受けて、この再開発計画を一度白紙に戻すべきだと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"まちづくりにつきましては、地域住民の方が主体的に検討してございまして、範囲といたしましても、地域住民の話合いの中で決められているものと認識しています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"確認","question":"同じく２ページ目です。これは再開発計画が決定して本組合が立ち上がった後に、再開発の事業費から、それまで立て替えた分が回収されるという仕組みになっていると思うのですけれども、これはそういうことで間違いがないかということを確認したいのと、また、仮に本組合認可まで進まないで開発が中止になった場合は、その立て替えた資金はどうなるのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の資金立て替えのお話ですが、こちらは、委員ご指摘のとおり、事業のものとして本組合に継続されるのが通常の流れとしてあります。こちらは、仮に事業が未実施となった場合、その負担について権利者が負うものではないと区としては認識しています。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"私がこれを伺ったのは、行政がまず再開発というまちづくりの計画を決めますよ、こういうテンポでやっていきますよと、それを住民に押しつけている、これが区のまちづくりではないのですかと言われたらどうするのですかというか、言われても仕方ないと思うのですけれども、そこら辺についてどう説明するのか。私には、地域住民が主役のまちづくりとは思えないのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の未実施の場合の立替金の負担ですけれども、こちらは事業に参画している事業協力者が負担するものと区としては考えているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"先に進みます。まちづくりに関する意見交換会が行われましたけれども、改めて目的について伺いたいのです、目的はなんでしょうか。国の要綱改定を受けて、区としても、品川浦周辺の再開発を推進するまちづくりビジョンは白紙にすべきなのではないですかと、昨年、共産党としても議会で質問したのですけれども、その質問に対して、まずは地域住民と意見交換を行っていくと答弁がありました。お願いします。","respondent":"大石まちづくり立体化担当課長","answer":"ただ一方で、これで終了というわけではございませんので、都度お話を聞くことも考えてありますし、しっかりと地域住民の意見には、個別で問合せがあった際はしっかりと対応していく、そういった考えでこれからも進めていきたいと考えているところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。それが既に実際に立ち上がっているのに、意見交換会の冒頭の説明では、一切そういう再開発という説明がなかったように聞いているのですが、これ、なぜ隠したのでしょうか、伺いたいと思います。再開発を前提にして、それを推進するというようなことはやるべきではないと思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"こちらはなぜかといいますと、準備組合に加入されていない方も多くいらっしゃいましたので、準備組合が考えているものとはまた別に、区で考えている地域の課題や魅力等を地域の皆様に分かっていただく、あくまで区が考えているものをしっかりお示しした上で。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"再開発にこだわることなくということでした。それは絶対あってはならない。その結果、再開発に賛同しないという方が多ければ、現状計画は当然白紙にすべきだと思いますけれども、どれだけ地域住民のまちづくりの声を把握できているのですか。把握するためには、もっと踏み込んだ、この陳情にあるような、アンケート調査などもすべきなのではないかと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"今後も様々な意見を聴取できるよう、陳情にありますとおり、アンケートも含めて、手法について検討してまいりたいと、このように考えているところです。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"アンケートを含めてということです。ここにも書いていますように、再開発の要望は非常に難しいことが多いです。どちらが大切なのかと。陳情者もまちづくりをしたら、そこに住む地域住民の方々の暮らしがどうなってしまうのかと分からない。本当にそういった思いは一番大切にしなくてはいけないと思うので、そこら辺、ぜひ汲み取っていただきたいと最後に意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"この準備組合というのは地域住民が選んだ人ではないですからね、ただ、有志の方々が集まっているだけですから。様々な意見がある。その理由を２つ目に伺いたいと思います。ここは違うのだと言うのであれば、総合実施計画をつくるに当たって、なぜ準備組合のヒアリングだけなのか、なぜ参加していない、反対している住民の声は聞かなくて総合実施計画をつくったのか、この２点を伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の総合実施計画に反対している人のヒアリングをしなかったのかですけれども、総合実施計画に記載しているものにつきましては、先ほども申したとおり、地域主体で構成されております再開発準備組合のほうからの現在のスケジュールについて記載したものです。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"お答えください。改めて、反対の声を受け止めると言いながら、なぜ白紙に戻さないのか、なぜ進める立場になるのか伺いたいと思います。３点目。まちづくりマスタープラン上は拠点と示されていると思いますので、なぜそうしたタワーマンションやオフィスや、そうしたまちにしていくのか、品川区の住宅施策は一体何を目指しているのかと思うのですけれども、その点も伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の、なぜ反対の声を聞かないのかですけれども、総合実施計画を策定するに当たりまして、その従前から地域の方から、まちづくりの予定が分からないだとか、反対をされる方から様々な意見を受けているところもあります。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"それを地域の皆様が決定したというのは事実と反すると、地域の中の進めたいと思う人たちが勝手に進めたものではないかと、そう言い換えるべきだと思いますが、いかがでしょうか。いずれにしても、品川区は白紙にする考えはないということですけれども、なぜ森澤区長はその声に向き合おうとしないのか伺いたいと思います。なぜここで言えないのですか。言うべきではないですか。いや、何かあるのですよね。","respondent":"大石まちづくり立体化担当課長","answer":"国際性だとか、羽田空港だとか、リニア新幹線の乗降を踏まえて品川へのアクセスを考えて、多様な人材が集まれるような拠点としてしっかりと支えていくというところがマスタープランにも明記されてありますので、そういったところを上位計画としながら。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"何棟のタワーマンションが建つのですか。億ションを造ることが品川区の住宅施策として目指しているところなのですか。行政がやるべき住宅施策は、やはり住宅に困窮している方々への対応です。こういうのは本当にけしからんと私は思いますけれども、最後、なぜ億ションを造ることをまちづくりとして進めていくのか、そのようなマスタープランなら、とっとと変えるべきだと思いますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"このような総合的なまちづくりとして、１つのまちづくりの手法として再開発事業がありまして、私たちの所管といたしましては再開発事業を所管していますので、このような形で答弁していますが、区として、住宅政策の中でも、防災性の向上だとか。","id":"exchange-037"},{"speaker":"ゆきた委員","kind":"確認","question":"１点だけ確認させていただければと思います。陳情項目の２番で、計画検討支援も公金の無駄になりますので直ちに中止してくださいとありますが、この総合実施計画上の計画検討支援に予算を計上されているのかどうかお聞きできればと思います。","respondent":"大石まちづくり立体化担当課長","answer":"総合実施計画に記載しております「計画検討支援」という、こちらの言葉ですが、予算計上して何か具体的に準備組合を支援しているというものではございません。","id":"exchange-038"},{"speaker":"せお副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。私が区に１点要望したいのは、どちらの意見も、いろいろな意見がある。本当にどんどん進めていただきたいという方も私の周りにもいますけれども、そういう方と、白紙に戻してほしいという方と、あとは、その間の意見もあると思うのです。そういう流れがつくれればと思いますので、ぜひお手伝いをお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"松永委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。先ほどのご説明とか議論を踏まえまして、再開発につきましては住民同士で話し合うものであると考えております。皆さんのご意見についても、先ほど、アンケートも含めてという言葉もありました。そうしたことも踏まえて、この度につきましては不採択にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"ゆきた委員","kind":"確認","question":"本日結論を出すで、不採択でお願いします。陳情項目１番については、事業範囲は地域主体で検討されるものであること、２番についても、計画検討支援については直接的な予算は計上されていないことも確認できました。３番についても、来年度もワークショップ以外で住民の意見を聞く機会を、アンケートも１つの手法として含めて検討していくという姿勢を確認できましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張しますけれども、やはり住民合意がなく、住民の居住権を侵害し、公共性にも乏しいものだと思うのです。さらに、開発企業の利益のための超高層再開発だと思います。これは中止をすべきだと思います。少なくとも区は、一部の住民や開発企業の声を聞くだけではなく、住民の意向を余すことなく把握する努力をしていただきたいと思いますので、こちらは採択すべきかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"理由としては、品川浦南地区再開発は白紙に戻すべきだと思うからです。先ほど、億ション、タワーマンションを造ること、が品川区の住宅政策なのかと、これが品川区の住宅施策なのかと伺いました。なぜそれが億ションを造ることになるのか。品川区がどういうまちを目指していくのか。こうした今までどおりの再開発推進の姿勢は改めるべきだと重ねて求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-03","title":"東京における都市計画道路の整備方針（案）","agenda":"東京における都市計画道路の整備方針（案）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"都市計画道路の再検討ということです。冒頭、意見を述べします。今回、未着手の道路がということなのですけれども、着手中であっても、特定整備路線、補助２９号線や放射２号線については、やはり検証した上で廃止をすべき路線だと思います。実際の来場者は何人ぐらいいたのかを伺いたいと思いますし、もしご意見などを出されたのであれば、どのような意見が出されたのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"都市計画課にご用があってお立ち寄りになられた方から、パネルの内容についてご質問があって、担当職員が対応させていただいたといったところです。特段、計画内容の説明をさせていただいて、お客様のほうから計画内容についてのご意見はなかったと聞いているところです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"１名ということです。それと、続けてなのですが、品川区内でいうと、今回の検討の対象になった路線は何本あるのか伺いたいと思います。今回の検証に当たって、廃止候補路線として上げた路線は幾つあったのか、東京都との協議になるとは思うのですけれども、区として、これは廃止候補路線として上げるべきなのではというふうに考えた路線は幾つぐらいあったのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"それと、廃止候補路線として挙げたのはといったところですが、先ほど説明させていただいた補助１６１号線、それと、今回、廃止候補路線にはなりませんでしたが、補助１４９号線を廃止候補路線として協議対象として上げさせていただき、結果としては。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。しかも、そこに住む住民の方の生活もあります。２本を協議対象として挙げて、１本が廃止路線になったということでした。廃止路線については賛成なのですけれども、ぜひ今後の検討に向けて、様々そういった住民の声も聞きながら、時代に合わせて廃止をしていくということも進めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"いずれにしても、品川区が一般財源を使って補正予算を組んで、東京都への意見、要望を検討する経費を計上して都に提出したという説明が以前ありましたけれども、区が都に要望して、この整備方針に反映したものは何か、反映しなかったものは何か、道路の路線の名前と、その理由をご説明していただきたいと思います。それと、都に要望したものですけれども、これは文章なのですか。","respondent":"高梨都市計画課長","answer":"今回、案としてお示ししたのが、東京における都市計画道路の整備方針（案）となってございまして、概要版の７ページを見ていただきますと、優先整備路線の選定のところに、優先整備路線の計画としては第５次事業化計画とお示しをさせていただいているところです。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"ありがとうございました。つまり、一番気になっているのは、引き続き優先整備路線となった１６２号線と１６３号線なのですけれども、これは引き続きなので、引き続きという要望になるのか、特に言わなければそうなるのか、その辺は私もよく分からない部分ではあるのですけれども、補助１６２号線と補助１６３号線について、こうしてほしいと伝えた理由、狙いを伺います。","respondent":"高梨都市計画課長","answer":"ただ、向こう１５年間で優先的に整備をしていく路線からは外れたといったところで、これまでいろいろと道路課を中心に検討をしてまいりましたけれども、先ほど説明の中でも申し述べたとおり、それが接続する補助２９号線の事業進捗の状況であるとか。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"現庁舎の跡地活用に、なぜ補助１６３号線の認可が必要になるのか伺います。前回でも述べましたが、私は、いよいよ広大な再開発のエリアを西大井にまで広げていくということでやめるべきだと前回批判いたしましたが、こうした西大井周辺の再開発、一丁目、三丁目、四丁目、五丁目、二葉一丁目も二丁目も含めて、連動する動きではないかと見ているのですが、違うでしょうか、ご説明ください。","respondent":"高梨都市計画課長","answer":"具体的に申しますと、補助１６２号線で今回優先整備路線に位置づけさせていただいたところは、いわゆる今、品川駅南地区のまちづくりで検討をしている区間以外の部分も含まれてありますし、逆に言いますと。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"補助１６３号線は、区独自の現庁舎の跡地ですから、区の判断１つで可能となってくる。いずれにしても、補助１６２号線、補助１６３号線、補助２０５号線、いずれも再開発を前提にした計画であることは今の質疑でも明らかなので、これらをやめるべきだと思います。最後に伺いますが、都市計画道路の推進ですけれども、再開発に向けた整備は、この計画にどのように位置づいているのか。","respondent":"高梨都市計画課長","answer":"今回ご紹介いただきました部分には、「都市の再開発」と記載がされているところではありますけれども、特段それをこの計画の中で隠しているとか、そういったことはございませんで、優先整備路線の選定の中でも、持続可能な地域へのまちづくりへの貢献ということで。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"意見だけ一言述べて終わりたいと思います。明らかにこの計画は、具体的には、さらなる再開発として、補助１６２号線の品川浦、補助１６３号線の現庁舎跡地およびしながわ中央公園、中小企業センター。そして補助２０５号線、原踏切では、西大井駅周辺の再開発等、将来的な動きを見通して進むものだと思います。これ以上の住民を追い出す再開発の中止を改めて求めて質疑を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"ゆきた委員","kind":"質問","question":"前回の８月の委員会でリメイク路線と紹介されたところがリーディング路線であると考えます。リーディング路線の選定で紹介されている補助１６３号線の支線から品川区街路６について、１３１ページと、先ほど説明がありました１７ページのところに記載されていますが、ここについてお聞きしたいと思います。","respondent":"中道都市開発課長","answer":"ＡＩカメラによる調査は、今、分析中でして、そうした結果につきましては、まちづくり・公共交通推進特別委員会のほうで、４月に報告予定となっています。","id":"exchange-052"},{"speaker":"ゆきた委員","kind":"質問","question":"令和７年度末には整備方針が策定され公表されることになれば、位置づけとしては、リーディング路線として方向性が示され重要な段階になると考えますが、その後の具体化について、さらに区として関与の在り方が大きな意味を持つものになると認識しています。そこで、方針決定後を見据えて、区としてどのように検討やスケジュールを想定しているかお聞きしたいと思います。","respondent":"高梨都市計画課長","answer":"本整備方針が、案がとれて、正式な整備方針として公表された際には、こちらの概要版１５ページの下段にも記載していますけれども、このリーディング路線は、周辺への交通影響等を確認した上で、令和２２年度までに工事着手を目標とする路線というふうに位置づけられます。","id":"exchange-053"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私も直接、大井町駅周辺のまちづくりについての要望は受けているところですが、区民の声の収集といったところでは、８月の委員会のときにも触れさせていただきましたが、より一層多くの意見、声を集約して、さらに進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、１点、述べ忘れたので申しあげます。住環境を壊しますし、補助２９号線自体がまだ事業化も５０％以下だということですので、今回、この計画が１５年の年間になったと、ただ、中間で見直しもするということでしたので、ぜひ品川区においては、補助３１号線も廃止をということで、廃止路線で、東京都に対して協議をしていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"せお副委員長","kind":"質問・要望","question":"すみません、１点だけお伺いしたいです。やはり安全のために道路空間の確保も引き続きしていただきたいなという思いがありまして、やはり安全性を確保しなければいけない、特に子どもたちへの道路空間の整備は進めてほしいなと思っています。","respondent":"高梨都市計画課長","answer":"委員がおっしゃられたとおり、道路に対しては、安全性の確保は最優先に取り組むべき課題であると認識しています。本計画の中でも、こちらは都市計画道路の整備方針という形にはなっています。","id":"exchange-056"},{"speaker":"せお副委員長","kind":"質問・要望","question":"ゾーン３０とか、あと、スクールゾーンとかが今もあるのは理解しているのですけれども、本当に何か起こってからでは遅いと思っているし、本当に東京の道路は狭いなと思っているで、ぜひそこも一歩踏み込んでいただきたいと思います。パリのようにしろとは言いませんけれども、一歩踏み込んだ子どもたちのための道路空間の形成は、これからも引き続き取り組んでいただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"}]},{"id":"topic-04","title":"令和８年２月都営住宅入居者募集","agenda":"令和８年２月都営住宅入居者募集","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"これまで様々議論をしたけれども、東京都は都営住宅をつくる考えはない、品川区は、東京都に都営住宅の増設を求める考えがないということで、やはりこうした姿勢は改めるべきだと改めて述べたいと思います。この１３４人、１８５人、２２８人の一人一人を伺うと、本当に切実な思いなのだろうと私は受け止めております。こうした住宅施策は、いよいよ転換すべきだと思いますけれども、いかがでしょうか。","respondent":"川原住宅課長","answer":"もう１つ、２点目の再開発に対しての住宅政策も先ほど申し上げたとおり、都、区、都のマスタープラン、あとは区の全体のそういった住宅施策に係る計画に基づいて検討していきたいと考えています。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"これだけの数字を見せつけられながら、なぜニーズは高いと認めないのか。これは率直に申込みが高いことを認めているのだから、都営住宅のニーズが高いということを認めることが、そんなに難しいことなのですか。だから、それを認めるべきだと質問したのです。改めて、都営住宅のニーズが高いことを認めるのか、なぜ認めないのか伺いたいと思います。こうした区の姿勢は根本から改めるべきだと思います。","respondent":"川原住宅課長","answer":"特に、民間賃貸住宅では、セーフティネットの専用住宅であるとか、居住サポート住宅の家賃低廉化もしっかりと実施をして、住戸の確保は引き続き民間賃貸住宅のほうでも重視して行っていきたいと考えています。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"一言、意見だけ。都営住宅のニーズが高いことをなぜ認めないのかと質問しましたが、ニーズが高いと認めることはありませんでした。区民の苦しい暮らしの実態が区には届いていないのだと思います。こうした森澤区長の住宅施策は根本から転換すべきだと述べて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"今の質疑に関連して、１点だけお伺いしたいのですが、住宅に困窮した方の住宅施策については、住宅マスタープランが含まれている区のマスタープラン、まちづくりマスタープラン、これに基づいて検討していく必要があるということでしたけれども、現状、区のマスタープランで、区営住宅については、どのような位置づけになっているのかだけ教えていただければと思います。","respondent":"川原住宅課長","answer":"管理も含めてです。なかなか老朽化している住宅が多いですので、そういった適切な更新を図って、修繕等もしっかりと行って、住みよい住環境を提供してまいりたいというふうな思いです。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"維持と管理だということでしたけれども、やはり今のどんどん家賃が上がっていって、しかも低廉な住宅は建て替えでどんどんなくなっているという状況ですので、それはやはり今の維持管理というだけの政策は、私も見直しが必要だと思いますので、そちらを改めて求めたいと思います。区営住宅は増設が必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-05","title":"東海旅客鉄道（株）が公表した道路隆起の発生原因と対策","agenda":"東海旅客鉄道（株）が公表した道路隆起の発生原因と対策","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"説明会なのですけれども、今までも住民の方などからも要望が出されておりましたし、共産党としても、教室型説明会、今回は「一斉説明型」という名前なのですけれども、こういったものを求めてまいりました。なかなかそういった説明会を「求めます」という言葉が聞かれなかった中で、先日の一般質問等への答弁の中で、区からも要請があったと。それはいかがか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"こちらは、ＪＲ東海からは、説明資料に沿って地域の皆様へ一斉にご説明の後、質疑の時間も設ける予定であるということ、また、一斉説明型終了後も、並行して行っておりますオープンハウス型の説明会も開催していますので。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"伝えていただくことは結構なのですが、やはり区として、時間、これ、延長を求めてほしい、主体的に区の意思として求める必要があるのではないかと思うのです。その上で、少しこれ、時間が足りないのではないかということで、区の意思として求めていただきたいということはいかがかと。要請する上で、前提として、これ、短過ぎるという認識はないのか、そこを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"何時間ならいいのかという議論になってしまうのですけれども、ＪＲ東海からは、一斉説明型の説明会だけでなく、地域の皆様や時間の制約なく来場できるオープンハウス型も並行してやっていて、受け切れなかった質問はそちらで対応するというところで聞いておりますし。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、経緯についてなのですけれども、経緯と書いていますけれども、１１月２０日に行った道路掘削工事があるのですが、これは、結局何を目的にした掘削工事で、何が分かったとＪＲ東海から伺っているのか伺いたいと思います。１２月１８日です。品川区としては、このメンバーを把握されているのか。このような結果でしたということを聞いているのか、何か見せてもらっているのか、そこら辺を伺います。","respondent":"大石まちづくり立体化担当課長","answer":"１点目の道路掘削調査の目的ですが、こちらは、これまでもご説明してきたとおり、路面下を最大３ｍ程度掘削して、地盤の状況であったり、既に埋められております埋設物の状況を確認するために行ったと聞いているところです。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"掘削工事は３ｍなのです。せいぜい当日にスキャニングして、穴があったかどうか確認したぐらいで、いきなり結論がボーンと出ていて、これでなぜこういう結論に達したのかがさっぱり分からないと思うのです。それが１点です。区が原因と対策の丁寧な説明の実施を求めているわけですけれども、今回の発表は、そういうふうになっていると考えていらっしゃるのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今回、システム改修を行ってアラートシステムが搭載されるというところで、一定、区としての要望が１つ通ったのかなと感じているところです。丁寧な説明ですが、まだこれから説明会が行われます。はその状況を見て、しっかりと対応してまいりたいと考えているところです。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとも区民が知り得ないような、知らないような情報を区独自でつかんでいるのか、改めてここは伺いたいと思います。そして、それは第三者なのですかという指摘もあるのです。対策については、一定、ヒューマンエラーを起こさないような措置を要望したと。これでどの程度抑制できるのかは、分からないところなのですけれども、今回の対策についての区の評価をもう一度伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今回の対策でどの程度抑制されるのかですが、こちらはなかなか答えが申し上げにくいところではありますが、やはり今回示されたもともとの原因が、やはり一定の施工管理の不足ということで、対策が施工管理の強化ですので。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。最後ですけれども、今回、２月１日と２日に説明会を計２回でしょうか、その時期に１回ずつやる。今も言っているのかな。そこについて、ぜひ区として、国に求めていただきたい。品川区内に入っているわけですから、区としてでもいいですし、あるいは、国に開催を求めるということをやっていただきたいと思うのですけれども、いかがでしょうか。そこだけ確認させてください。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の説明会後に再開するのかですが、今聞いているのは、説明会実施後に、いつかというところは聞いてはいないのですけれども、再開の準備を進めていくとは聞いているところです。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"このまま進めるわけにいかないと、私たちはそういうふうに思っています。そこは申し上げておきたいのと、最後にすみません。先ほど、公聴会について、ＪＲ東海の責任において説明すべきものだと、ありました。こういうことも言いますね。国に対してぜひ公聴会の開催を求めていただきたいと思うのです。これは要望といいますか、いかがかということで、これで終わりにしたいと思います。いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"国に開催を求めるというところもありますが、あくまで現時点ではＪＲ東海が、この件につきましては、国から認可を受けて実施している民間事業ですので、あくまでＪＲ東海の責任の下でしっかりと対応を行っていくことが重要と考えているところです。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"１０ｍにわたって区道を隆起させたわけですから、深刻な事故だと思っています。これは区長名か何かで要望したのか、それとも担当者レベルでのやり取りの中なのか、区として、様々、ＪＲ東海に意見を言っているのであれば、どういうものなのか、もう少し詳しく説明してほしいということが１つ目です。１時間が短いとも言えないというのは、本当に駄目だと思うのですけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"説明会以降も、事務所でしっかりと個別で対応するということで、丁寧に説明していくと聞いているところです。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"前後して、先に説明会１時間問題ですけれども、ＪＲ東海がしっかりやるからそれでいいという態度は本当にひどいなと思います。どう考えても１時間などあり得ないではないですか。やはり区民の安全、生活の安全、行政が立つべき立場に立つからこそ、それでも安全が担保されないと判断して担当者レベルで要望しているわけですから、もう少し施工管理の強化、要は足りないと思ったところを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"ただ一方で、今回このような事象が起きている状況がありまして、このまま進めていっても、また同様な事象が起きる可能性は十分考えられます。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"なるほど。僅かな資料の中だけでは読み解けないいろいろな事情が今の説明で少し分かってきたわけですけれども、いずれにしても、区はそれ以上の説明を受けたり要望したりすることは当然やるべきだと思います。基準の中だったけれどもバランスが崩れたという言い方ですから、この基準自体が、安全上、緩いものではなかったのか、そこはＪＲ東海は品川区に何と説明しているのか、そこを伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"泥土圧の各基準値にそもそも問題があったのではですが、こちらの基準値につきましては、詳細な資料が今ないのでお答えできないのですけれども、一般的に用いられている基準値よりも厳しく設定していると、ＪＲ東海からは聞いているところです。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"このアラームのシステムの報告、この基準で安全が担保されている、この報告をＪＲ東海は品川区にすべきだし、担当者であれば一定の知識があるから、それが合理的なのかどうか判断できるし、合理的な判断でＪＲ東海に要望もできるし、また、アラームのシステムも、言わば今回の事故を繰り返さないための最後の砦となるシステムなわけですから。","respondent":"大石まちづくり立体化担当課長","answer":"空気を減らすために気泡材の調整をするといった対応は実施していたところですが、対応が完全ではなく、空気が漏出したと考えているとＪＲ東海からは聞いているところです。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"新事実です。区を責めているのではないです。本来、ＪＲ東海が公表すべき中身の新事実です。今回の僅かな資料の原因と対策、Ａ４、１枚ですから、この説明では、ＪＲ東海の対応が不十分だということは区の説明でも明らかだと思うのです。なので、追加の資料や追加の説明も含めて、新たな原因と対策のＪＲ東海の公表を区はＪＲ東海に求めるべきだと思いますが、いかがでしょうか。いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"安全対策の徹底等を繰り返し求めてきたところです。区といたしましては、ＪＲ東海により今回示された対策が、まずもって責任を持ってしっかりと実施されることが重要と考えております。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"このような事態が起きているわけですから、国に対して事故調査委員会の設置を、今回の事故を受けて行うべきだと、要望すべきだと思いますが、いかがでしょうか。なぜないのかという話はさておき、少なくともこの事象に対して、国に対して事故調査委員会の設置、ＪＲ東海が設置した調査委員会ではなく、国が設置した調査委員会を改めて区は求めるべきだと思いますが、最後にいかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"併せまして、２月上旬に行われます説明会につきましても、ＪＲ東海の責任において、区民に対してしっかりと説明して、１人でも多くの理解を得るということが重要と考えているところです。","id":"exchange-075"}]},{"id":"topic-06","title":"「中小企業向け『ＡＩ電気相談所』設立による再エネ導入・脱炭素経営促進プロジェクト」実証実験","agenda":"「中小企業向け『ＡＩ電気相談所』設立による再エネ導入・脱炭素経営促進プロジェクト」実証実験","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"対象となる中小企業は区内にどれぐらいあるのでしょうかということと、あと、ツール利用企業は、最終的に何社ぐらいを目標にしているのかということ。今度、事業者による説明会をやるという話も最後にありましたけれども、このツールの存在をどういうふうに知らせていくのでしょうか。このツールについて、利用料などは発生するのかも伺います。","respondent":"中西環境課長","answer":"説明会に関しましては、こちらの株式会社タンソーマンＧＸがＳＯＭＰＯホールディングス株式会社とも連携を図っておりまして、ＳＯＭＰＯホールディングス株式会社のほうからも周知をしてもらっているような状況です。","id":"exchange-076"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"中小企業センターと、あと、品川産業支援交流施設ＳＨＩＰに端末を設置する。一方で、事業全体の所管報告は環境課が行っていますが、この体制の中で、診断結果について事業所がより詳しい説明とかアドバイス、助言を求めたい場合は、どこの所管に問い合わせることになるのかをお聞きしたいと思います。","respondent":"中西環境課長","answer":"設置に当たりましては、地域産業振興課とも連携をしながら進めているところです。実際、この省エネ診断を受けた診断結果をもってどうされるかに関しましては、基本的には、環境課ではなくて地域産業振興課の経営相談とか、そういったところに回っていくような形になります。","id":"exchange-077"},{"speaker":"ゆきた委員","kind":"質問","question":"連携しながら、地域産業振興課のほうで対応ということですね。このことに付け加えて、先ほど、対面での診断もお話があったと思うのですけれども、これは伴走型支援ということで認識してもよろしいのでしょうか。","respondent":"中西環境課長","answer":"こちらに関しては、一応、ホームページ等を見ますと「伴走支援」というような表現をうたってありますので、並走しながら、もちろん時間の枠等々あるかと思いますけれども、伴走しながら支援をしてもらえると認識しています。","id":"exchange-078"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。ＱＲを読み取ると、ＡＩの無料相談ができることも私も確認しましたが、現在は、中小企業向けの取組として進められていることも承知していますけれども、今後の実証実験を踏まえながら、将来的に各家庭にも応用できるものなのか、検討の方向性についてお考えがあればお聞きできればと思います。","respondent":"中西環境課長","answer":"そういった形で広げていくといったところを今進めているところですので、まずはそこの部分をやりながら、ただ、この実証実験をやりながら、関係性は事業所等もありますので、家庭向けにできないかといったような相談をしてまいりたいと考えています。","id":"exchange-079"}]},{"id":"topic-07","title":"マイガーデン豊町","agenda":"マイガーデン豊町","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"いいことだなと思うのですけれども、これ、土地を取得したのがいつぐらいで、工事はいつからやっていたのかということと、それと、品川区としては、マイガーデンというのを、今後増やしていく考えを持っているのか伺いたいと思います。","respondent":"大友公園課長","answer":"土地の受領の日ですけれども、こちらの区長決定は令和５年１１月となっています。すみません、少し訂正します。寄附の申出日は、令和６年７月３０日となり、そこから手続を進めたものとなっています。続いて、工事につきましては、令和７年１１月２１日から実施しています。","id":"exchange-080"},{"speaker":"安藤委員","kind":"提案","question":"共産党なのですけれども、補助２９号線など住民も反対する特定整備路線を廃止をして、取得した用地に、福祉施設や公園などを整備する緑と福祉のまちづくりを提案させていただいています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"ゆきた委員","kind":"確認","question":"南大井と西五反田の周辺で選ばれた区画では、過去に途中で利用されなくなるような放置される区画が発生したことがあったのか、確認でお聞きできればと思います。","respondent":"大友公園課長","answer":"マイガーデン南大井・西五反田につきましては、好評で、基本的には１年丸々使っていただいているところではありますけれども、途中で荒れ地となるではないですけれども、利用を取りやめるような方は、いらっしゃったことはあります。","id":"exchange-082"},{"speaker":"ゆきた委員","kind":"確認","question":"仮に途中で利用されない区画が生じた場合には、どのように考えていくのか、こちらについても確認でお聞きいただければと思います。","respondent":"大友公園課長","answer":"利用状況の確認をとりまして、まだ今後継続利用するのかどうなのかというところ、また、積極的に利用してもらいたいという声かけをして利用を促進しています。","id":"exchange-083"},{"speaker":"せお副委員長","kind":"質問・要望","question":"今お話のあったマイガーデン南大井・西五反田なのですけれども、これ、今までは個人利用でしたか。今回、スケジュールは同じということなのですけれども、利用者募集の対象者が、この豊町と一緒なのかというところを確認させていただきたいと思います。だから、屋上と地上につくるものでどう違ってくるのかなということについて、何か違いがあれば教えていただきたいなと思います。","respondent":"大友公園課長","answer":"今、第二庁舎の屋上にプランターのようなものを設置して、子ども青空農園として開放しているところなので、非常に好評は得ているところであります。こちらについては幅広く適用については検討してまいりたいと考えているところです。","id":"exchange-084"},{"speaker":"せお副委員長","kind":"質問・要望","question":"対象者のところ、区内在住者も入っていますけれども、この福祉または教育を目的として活動するという、こういうものもいいなと思っているので、ぜひお勧めしていただきたいなと思います。区有地なのですけれども、今、課題は理解しました。様々区全体の、例えば、公有地活用とか、そういったところを考えながら進めていってほしいなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]},{"id":"topic-08","title":"橋梁長寿命化修繕計画の改定","agenda":"橋梁長寿命化修繕計画の改定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"予防は大事だなと思います。年間で一、二橋程度の補修設計および工事を行うということなのですけれども、この対象橋梁はどのように選定していくのかを伺いたいのと、あと、なぜ年間一から二橋程度になるのかを理由なども教えてください。","respondent":"森道路課長","answer":"そういったものを過年度の財政結果を基にして、そういった判断をし、まだ５年後に法定点検がありますので、そのときにまた確認をし、症状が進行していれば、早期にまた計画を立て直して、実際に補修工事を行っていくというようなサイクルで進めていくところです。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"実際に点検をしながら、この５年間の計画の中で、１年目はここ、２年目はここ、３年目はここ、４年目はここ、５年目はここというふうに具体的にもう決めているというような理解でよろしいのか伺いたいと思います。","respondent":"森道路課長","answer":"ただ、その中で、例えば、予算の配分のことであったりとか、非常にお金がかかるので、もう少し、２か年にしようとかというような検討が出てくるかと思いますので、臨機応変に対応しながらやっていければなと思います。","id":"exchange-087"},{"speaker":"ゆきた委員","kind":"確認","question":"近年、働き方改革とか労働時間規制、点検技術の人手不足とか、さらには、夏季の熱中症対策、気象条件の影響とかで、実際の作業が可能な時間は年々短くなっている状況だと思われます。そこで、前回お話があった債務負担行為のような、同様の対応が必要となる場合が年々多くなっていくと思われますが、安定的な対応ができるのか、ここについて、１点、確認できればと思います。","respondent":"森道路課長","answer":"あちらも働き方改革ということで、ＪＲ東日本から、４月に協定を始めて３月まで実施するというようなものではなくて、１月にもう準備を始めておいて、年度のなるべく早い段階でやっていって、年間の作業スケジュールを平準化していくというようなご提案があったところです。","id":"exchange-088"},{"speaker":"ゆきた委員","kind":"質問","question":"必要に応じて対応していくということで了解いたしました。今後さらにこういった課題は、かなり拡大していくと考えられます。こうした状況を踏まえて、債務負担行為を含めて、今後どの程度そういった対応が必要なものがあるか、想定しているのか、お聞きできればと思います。","respondent":"森道路課長","answer":"その辺は、例えば、年間２０本あれば、５本分は債務負担行為でやっていくというような計画も、今少し進めているところもありますので、今、具体的にこうだという話ではないのですけれども、そういった視点はしっかりと大切にしながらやっていければなと思います。","id":"exchange-089"}]},{"id":"topic-09","title":"立会川幹線雨水放流管事業（東京都下水道局施工）","agenda":"立会川幹線雨水放流管事業（東京都下水道局施工）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ただ、これも令和９年度出水期までに行うということですよね。２つお伺いしたいと思います。１つは、この貯留管の倍増措置で、どの程度、１時間当たり何ミリ程度の雨量に備えられることになるのかということを改めて伺いたい。それまでに、来年度の出水期が迎えてくる。これはなかなか難しそうなのですけれども、区としては、どのような対策をとる考えなのか伺いたいと思います。","respondent":"関根河川下水道課長","answer":"そのために、２月に実施される東京都主催の説明会においても、出席される方には止水板の助成制度についてのご案内を区のほうからも差し上げられればと考えているところです。","id":"exchange-090"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。ぜひよろしくお願いします。すみません、少し基本的なことで申し訳ないのですが、これ、最終的には、立会川幹線がつながるということになると思うのですけれども、そうしたら、この暫定貯留管は貯留しなくなるということになるのか、そこだけお伺いします。","respondent":"関根河川下水道課長","answer":"委員おっしゃるとおり、今は、貯留というのは、あくまで暫定的な措置ですので、この事業が完了した際には、流下ということで、一時的にためるだけではなく、流せる下水道管となる予定です。","id":"exchange-091"}]},{"id":"topic-10","title":"令和７年度地区総合防災訓練等の実施結果","agenda":"令和７年度地区総合防災訓練等の実施結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区内一斉防災訓練、４６避難所、合計１万４６１名のうち、障害がある方は何人か伺いたいと思います。ぜひ視覚・聴覚・精神・知的・身体、様々な障害がある方も、訓練を通じて自分たちの防災知識や行動を変えるきっかけに、また、そうした要配慮者の存在そのものの理解も広がる大事な場になってくると思うので、参加しにくいハードルをぜひ取り除いていただきたいと思いますが、いかがでしょうか。","respondent":"星災害対策担当課長","answer":"車椅子を含めまして、障害者への訓練参加につきましては、こちらの地区防災訓練が行われます前、７月に、関係７団体のお集まりのところで、私が行って参加の説明とお願いをしているところなのですけれども、その中でも。","id":"exchange-092"},{"speaker":"中塚委員","kind":"質問・要望","question":"訓練前に７団体に参加の説明とお願いをして具体的にハードルや要望を聞いているということですけれども、障害７団体からどのような要望が上がっているのか。障壁ですから、下げることを目指すと同時に、取り除く方向に方針をとっていただきたいと思いますが、いかがでしょうか。今後どうやるか考えたいということですけれども、数えればいいだけですから。","respondent":"星災害対策担当課長","answer":"具体的には、地区総合防災訓練のほとんどが、まず、地域の町会・自治会の方たちが集まって、一時集合場所での集合、それからの訓練ということで、避難訓練も継続しているというところもありますので、町会の方たちともお話をして。","id":"exchange-093"}]},{"id":"topic-11","title":"「しながわ防災区民憲章（素案）」に係るパブリックコメントの実施","agenda":"「しながわ防災区民憲章（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"しながわ防災区民憲章（素案）ということですけれども、素案が出たのは今回が初めての委員会になりますので、素案について質疑をさせていただきたいと思います。今回、改めてこれが示されましたので、３点まとめて伺いたいと思います。その上で、２番目ですけれども、ご高齢の方、高齢者、障害がある方、障害者、所得の少ない方、こうした方々にも自助、共助を求めるという立場なのか、ご説明ください。","respondent":"羽鳥防災課長","answer":"そういった意味合いで、やはり自助、共助が重要であるという認識を持っていただきたい。区長も東日本大震災の被災地である宮古に訪れ、その重要性をまた再認識したというような状況です。","id":"exchange-094"},{"speaker":"中塚委員","kind":"質問・要望","question":"自助は自分の身を守る、家族の身を守る、共助が皆さんで協力して助け合う、そのことを高齢者、障害者、低所得者に求めるのかと聞いたら、対象者は限定していないという説明でした。もう１つ、災害は自己責任かということです。つまり、自己責任化ということを認める答弁だと思います。それにならって、こうした自助、共助の強調という素案はやめるべきだと、改めるべきだと思いますが、いかがでしょうか。","respondent":"羽鳥防災課長","answer":"事前防災についても、区といたしまして、しっかり取り組んでまいりたいと考えています。災害後の復旧、復興についても、もちろん取り組み、その中で自助、共助の部分もしっかり取り組んでいただきたいというメッセージです。","id":"exchange-095"},{"speaker":"中塚委員","kind":"質問","question":"国の調査でも６割が生活が苦しいと言うのです。日々の生活に追われている所得の少ない方々、年金暮らしのお年寄りだったり、ひとり親家庭だったり、そうした方々に自分で備蓄しろと言うのですか。自分で何とかしろと言うのですか。そうした方々に自分で何とかせいと言うのですか。手話を日常会話として、言語として利用する障害者に、備える、あいさつする、伝える、行動する、自分たちでやれと言うのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"ゆきた委員","kind":"確認","question":"広報しながわで、防災区民憲章に向けての有識者の話合いが行われたことを確認しました。有識者の意見がどのように扱われたのか。採用されたのか、あるいは、何らかの理由で見送られたのか、その辺の経緯、有識者のアドバイスが素案に具体的にどう反映されたのか、生かされたのかをお聞きしたいと思います。","respondent":"羽鳥防災課長","answer":"２点ご質問をいただきました。区民へのメッセージというところです。","id":"exchange-097"},{"speaker":"ゆきた委員","kind":"確認","question":"今、４つのブロックということでお話しいただいたと思うのですけれども、前文の部分でお聞きしたところです。有識者の意見の中で、私も広報しながわで見せてもらった中では、中身よりもつくり方が重要だと思っているということを確認しました。経緯や過程について、どう価値をつけていくかというところで、どのようにお考えかお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"１,０００件まではいかなかったですけれど、なるべく多くの方、それもいろいろな、多様な方からご意見をいただいたところです。今後、パブリックコメントでもご意見をいただいて、区民の方がつくる防災区民憲章になるように取り組んでまいりたいと思います。","id":"exchange-098"},{"speaker":"ゆきた委員","kind":"質問","question":"品川区がつくった防災区民憲章で、最後の「行動する」の項目で、品川区が言う「私たちの品川は私たちが守る」なのか、関わってきた防災区民憲章で「私たちの品川は私たちが守る」となるのでは、重みも、受け止め方も、力強さもかなり変わってくると思います。この辺についても、最後に何かお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"より多くの方のご意見をです。一定、素案という形でお示しをさせていただきましたので、今後は、パブリックコメントを中心にご意見をお伺いしたいとは思いますけれど、機会を捉えて、そのほか、ご意見を伺えるように取り組んでまいりたいと思います。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問・要望","question":"原因はいろいろあると思うのです。今言ったような意見について、何か区としてご意見があれば、反論する点などがあれば伺いたいです。なぜ憲章になると、この自助、共助、これだけの強調のみになってしまうのか、これ、区が説明するところの条例の内容とも矛盾するということも言えてしまうのではないのかなと思うのですけれども、そこら辺についての整合性について説明をいただきたいと思います。","respondent":"羽鳥防災課長","answer":"現状、世論調査の結果ですけれど、最新の調査ですと、まず、自助、共助の一番主なところ、防災用品の備蓄というところで、重要である、必要であるという回答が８７％近い回答をいただいているのですけれど、一方で。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問・要望","question":"さあ、意見を出してくださいね、でも、説明はあまりしません、主体的にはしませんというのではなくて、やはりしっかり区としても説明会を開いて、内容を理解してもらった上で、初めて意見が出るものですから、そういった意味で大事だな、私たちもやってほしいと言ってきたわけです。伺いたいのですが、このパブリックコメント説明会の目的については、これは今回どこに置いているのか伺いたいと思います。","respondent":"羽鳥防災課長","answer":"２月６日に予定しているワークショップ形式でのパブリックコメントの説明会ですけれど、委員おっしゃるとおり、もう少し早い時期でこれが実施できれば理想的だったかと思いますけれど、なかなかスケジュールの関係でこちらの時期になってしまったというところではあります。","id":"exchange-101"},{"speaker":"中塚委員","kind":"質問","question":"まとめて質問したいと思います。今のやり取りを聞いていても、私は腹立たしく思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"中塚委員","kind":"意見","question":"同じことは言いません。先ほど、自助、共助の理由を国が示しているからという説明です。そして、その説明が、区の世論調査で備蓄が重要と答えるのが８７％だけれども、していると答えているのが６５％、つまり、準備をしていないあなたが悪いと、区はこういう態度をとる。障害がある方が、情報弱者と言われているわけだから、何がどう必要かを区別に沿って伝えてあげなければ伝わらないわけです。諦めるなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"}]},{"id":"topic-12","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"議長報告ということなので、それでいいのですが、今、議会改革検討会も行われていると思います。この報告書、大変いい内容だと思いますので、区議会ホームページの公開についても、ぜひ求めていただきたいと要望したいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"}]},{"id":"topic-13","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"委員長おっしゃるとおり、今日このような時間ですので、手短に申しあげますけれども、今日は初めからボリュームがあったということもあって、事前にいろいろ正副に調整していただいたと、伺っているのですけれども、こういうときは１０時から始めるということも合理的な判断の１つなのかと思いますので、今後、念頭に置いておいていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/378071?Template=document&Id=7293#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":95686,"voices":294}},{"id":"r08-20260119-9","meetingId":"r08-m01","date":"2026年1月19日","dateIso":"2026-01-19","committee":"文教委員会","time":"午後 １時００分～午後 ４時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","topics":[{"id":"topic-01","title":"令和７年陳情第５９号、ＰＴＡ役員不足解消のための別居親参画マッチング制度の導入に関する陳情","agenda":"令和７年陳情第５９号、ＰＴＡ役員不足解消のための別居親参画マッチング制度の導入に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"ご説明いただいた中で、別居している親がＰＴＡに入れない障壁はないというお話でした。ＰＴＡの規約にそうしたものがないということですよね、それを確認するのと、あと、この陳情の中では、公教育の質の向上に資する施策であると書かれているのですが、区の受け止めを伺います。","respondent":"舩木庶務課長","answer":"こういった方々、ＰＴＡに限らず、学校行事であるとか、学校教育全般に様々な形でご協力、ご支援いただいていますけれども、こういった関わり方については、やはり家庭教育という意味では、この教育の第一義的責任は父母が有しているというところで。","id":"exchange-001"},{"speaker":"のだて委員","kind":"意見","question":"今、ご説明を聞いた、ＰＴＡが任意団体であり、区が介入すべきではないというスタンスが貫かれていると感じました。特に別居親を規制しているものもないということでしたので、別居親の方も入れると認識をいたしました。それぞれの自覚に基づいて参加をしていくと、ＰＴＡ活動はそもそもそういうものだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、不採択です。先ほどの説明でも、ＰＴＡに別居親の参加を拒むものはないということでありましたし、ＰＴＡのメンバーについて教育委員会が介入すべきではないと考えますので、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"意見","question":"今のご説明にありましたように、区が介入できない部分のことだということが１つと、もう１つは、もしＰＴＡに参加するのならば、教育委員会がどうとか学校がどうとかよりも、いわゆる別居されている保護者、親の方が話をして、関わろうと思ったらＰＴＡの判断で関われる可能性があるということですので、そういうことも含めて、不採択であります。この別居親云々ではなくて、ＰＴＡ活動全体にということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。先ほどの説明にありましたが、困難であると考えます。引き続き、ＰＴＡや保護者の方々のお声を伺いながら、教育委員会としてＰＴＡ活動への支援をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"令和８年度新入学学校選択の抽選結果","agenda":"令和８年度新入学学校選択の抽選結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、小学校では、選択を希望した子どもたちが前回から増えて、６１７名になっていますけれども、抽選校は減っているということで、これはどういう動きなのか、区がどう考えているのかを伺います。中学校は、希望者数は減って、４９５名という中で、抽選校は９校から１３校に増えているので、特に、これをどう見ているのか伺います。学校選択の希望理由、今、主なものはどのようなものなのか伺います。","respondent":"石井学務課長","answer":"中学校につきまして、申請者数が減ったものの抽選校が増えた、こちらにつきましては、恐らくですけれども、令和８年度から３５人学級が中学校でも開催される影響もありまして、こういった受入れ人数について昨年度より数が減った結果、抽選校が増えたと分析をしております。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、中学校の抽選が増えたのは、分かったのですけれども、小学校は、特定の学校に集中したということで、そういうこともあるとは思うのですが、その状況が区としては、よいと思っているのか、悪いと思っているのか、今後、影響してくるようなことなどがあるのかどうか伺います。その状況を区としてはどのように認識しているのか伺います。","respondent":"石井学務課長","answer":"この結果について、これがよいのか悪いのかと言われますと、様々な側面があると考えています。あくまでも学校選択制は、多様な選択肢を用意するということでこれまで取り組んでおりまして、その中でさらに各校の学校運営における工夫を促していくものと認識をしております。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"区の考えがあれば伺います。そうした面があると思いますけれども、いかがでしょうか。この学校選択制は従来、私たち言っておりますけれども、廃止をすべきだと思います。実際、この間、特に海側では開発によって人口が増えています。でも選択さえできないということになっておりますけれども、学区変更とかにも影響が出てきているので、やはりこの学校選択制の見直しが必要だと思いますが、いかがでしょうか。","respondent":"石井学務課長","answer":"入れなかったときの挫折につきましては、もちろん様々あるとは思いますけれども、基本的には申請をいただいて、それで抽選の結果行けることもありますし、また、それは漏れることもあるということの一方で、もちろん窓口にいらっしゃる方につきましては丁寧にご説明をしますし。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"それは地域にとって、学校の周辺にある、活用できるものなどを利用して授業内容を工夫し、その地域に結びついた教育を行っていくというのは１つあると思うのですけれども、全体としてやはり、公教育ですから、どこでも同様の、同じような一定水準の教育を受けられることが重要だと思います。そうした競争に結局はなっていくので、学校の格差が生まれることがないようにすべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"まつざわ委員","kind":"質問","question":"子どものケアという声もありますけれど、なかなか受けた傷のケアもまた、簡単に言えないと思うので、例えば兄弟枠は、それを優先するのはどうとかあるのですけれど、そこら辺は少し配慮するとか、例えば選択制の考え方を改めて考えていただいて、また昔みたいなブロック制に戻すとか、初めからこっちにすればその枠の中で入れるわけですから、そういった在り方の検討はこれからしてもいいと思うのですけれど。","respondent":"石井学務課長","answer":"委員ご指摘の、近年の学校選択において、兄弟枠であっても入れない現状、これについては、我々も１つの課題として認識をしています。そういった課題も含めた上で、今後の学校選択の在り方などについてもいろいろと考えていかなければならないとは思っております。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つ質問するのですけれど、浜川小学校は、学区内で１６５あって、兄弟が２人待っていて全員待機があと１８ですが、これは、減る要素の４３の戻りはない感じでやっているのですね。１６５で下は全員待機だけれど、もし動かなかったら、この待機の子たちは全く元に戻れない、抽選で、空きはどうすれば出るのですか。","respondent":"石井学務課長","answer":"浜川小学校につきましては、３ページの表にもありますとおり、いわゆる戻りの考慮はない状況です。ですので、この後、抽選の枠につきましては、例えばその中で、ほかの国立、私立に決まった場合ですとか、辞退が生じた場合に空きの枠が出てくるです。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"学区内で１６５のお子さんたちが無抽選で、そのお子さんたちの中から今言った国立や私立に行った子が抜けた場合で、兄弟の方が入れるなどという理解でよろしいのですか。","respondent":"石井学務課長","answer":"委員のご認識で間違いございません。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"今後どうしていくかは、学校改築と学校選択制で子どもがどのように動くのかも含めて、改築についてあまり想定に乗っていないと思うのですけれど、学校選択を導入したときに、学校の数、改築、改編、そういうのを含めてやってきたと思うので、今後そういうことも含めて検討していくべきだと思うのですが、いかがでしょうか。","respondent":"石井学務課長","answer":"そういったことも含めて、課題認識等を持ちながら進めていきたいと考えています。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"確認","question":"そこの、ずっと先の話にも関係すると思うのですけれど、そういうことを、どこをどう改築するかとか、どこはもう改築しないとかという話ではなくて、そういう少し長いスパンで検討していただければ、この前、区の教育ビジョンの中にも大まかなあれは出ていますけれど、少し詰めて検討していただかないと毎年、こういう同じ、こうしたほうがいいというのが出ることになってしまうので、ぜひその辺。","respondent":"石井学務課長","answer":"こういった制度を考えるときに、先ほど委員ご指摘のとおり、学校改築の状況などといったことを幅広に検討する必要があると思います。ですので、教育委員会事務局全体として、きちんと課題に向き合っていきたいと考えております。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのときに、教育委員会としては、ここを改築したいという予算要望をされると思うのですけれど、それを区で何らかの対応を、うまくいったりいかなかったりすると思うのですが、区の教育委員会としての方針があって、そのためにはここは改築していくと強く主張していただいて、やはり、学習する子たちがいい環境で勉強できるように、ぜひ改築の予算は頑張って要求していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-03","title":"学校給食における有機農産物等活用推進事業","agenda":"学校給食における有機農産物等活用推進事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"９月から試行実施をして、課題抽出・フィードバックをしてきたということで、ここではどんな意見が出たのかを伺います。ジャガイモとニンジンを１月から指定品目にしたので、全校で有機農産物等を使っているということだと思うのですけれども、その実施した状況も伺えればと思います。できるところからやっていたと思うのですが、ほかの食材、何校かでやっているものがあれば伺います。","respondent":"石井学務課長","answer":"それを生産者にフィードバックしながら、取り組んできました。ジャガイモ、ニンジンと取り組んできて、例えばそれ以外の野菜の取組なのですけれども、１０月とか１１月につきましては、結構旬の時期としてサツマイモなどが特別栽培で主に実施されていました。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"ジャガイモとニンジンを指定品目にして実際やってみた状況、感想もあったので後でお答えいただければと思います。そのフィードバックは、どういうことを求めて、生産者は、黒い部分をなくしていくなどはできるのですか、その辺の具体的なことが分からなかったので伺います。タマネギ、もやしは今後検討していくということで、タマネギは先ほど少しありましたけれども、現状の課題があれば伺いたいと思います。","respondent":"石井学務課長","answer":"そうすると、その袋を開封するための手間ができてしまうこと、また、袋をたくさん開けるのはそれだけ異物混入のリスクが高まるということ、そういったところから、生産者には大袋での納入についてお伝えはしているのですけれども。","id":"exchange-017"},{"speaker":"まつざわ委員","kind":"意見","question":"少し似てしまうのですけれど、会派でもいろいろ八百屋であったり、栄養士であったりのお話をヒアリングしたときにいろいろな課題が出ました。やはり、物流が難しいとか、手間がかかる、それはもう、ある程度実験した中で解決したと言っていいのか、そこをまず、聞かせてください。","respondent":"石井学務課長","answer":"そういったものをどんどん除外した上で、１月からの本格実施に当たってはジャガイモとニンジン、これをきちんと実施するということで、もちろん全ての野菜が有機野菜で導入できるだけの生産体制が世の中にあれば、それは理想だとは思っていますけれども。","id":"exchange-018"},{"speaker":"まつざわ委員","kind":"質問","question":"分かりました。困難があったのですね。それともう１つ、先ほどありましたけれど、私もこの、著しく困難と判断された日というのは、例外の規定のようなことをつけているのでしょうが、例えばこういうのも、ある程度具体的な基準を設けたほうがいい。そこら辺の困難な基準をある程度明確に示したほうがいいと個人的には思ったのですけれど、どうなのですか。","respondent":"石井学務課長","answer":"確かに、１つ基準を設けるのは大事だと思いますけれども、現行の最低基準としては、もう明らかに入らない、蓋然性が高い場合と各校には伝えています。は各学校様々事情があると思いますので、そのときについては教育委員会にご相談いただきたいというような運用をしております。","id":"exchange-019"},{"speaker":"横山委員","kind":"確認","question":"今後の展開について、学校現場、事務局ともに過度な負担とならないよう課題の整理を行っていく、とあるのですけれども、こちらは大変重要な観点だと思っていまして、その過度な負担は、どういったラインだと、この試行実施をしてみて教育委員会として考えているのか、もしイメージがあれば共有したいと思うので、確認させていただければと思います。","respondent":"石井学務課長","answer":"過度な負担というのは、例えば今ですと、予算として、１食当たり１２円を上乗せしたものを払うというよりは、実際にかかった費用と、あとは市場価格との差額を各校に配分することによって確実に実施できるような体制で給食費の支給を行っています。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから３つ目は、給食がおいしくないという中学生の声から云々とお話があって、理由も含めて始まったと伺っているのですけれど、この有機農産物等を導入したことによって、児童や生徒が給食を食べてどういう反応があったのか、別の言い方をすると、これを推進したことでどのようなメリットがあったのか、現時点でお感じになっているのかです。","respondent":"石井学務課長","answer":"当初予算のプレス発表では１食当たりプラス１２円ということでやっていましたけれども、９月からの実施に当たっては、先ほども申し上げたのですが、実際に有機野菜の購入にかかった費用と、あと慣行品の市場価格の差額分を各学校に払う方式を取っております。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"確認","question":"でも今、課長の説明は、差額内で全て収まっているからほかに影響がないというご答弁なのですけれど、そこは確認させてください。それが、学校等、あるいは児童生徒そして保護者の方にも、導入当時はいろいろあったのですけれど、それが動いてしまったらもう、何でもない、ではなくて、いいことをやっている説明を学校から、教育委員会から学校を通じてということになるのでしょうか、その点について伺います。","respondent":"石井学務課長","answer":"そういう意味では、それだけの努力をした上で導入している事業ですので、それの予算についても引き続きご理解いただけるように努力していきたいと考えています。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"確認","question":"この事業の理解を進めていって、進めるということでお願いします。それで、さっきの差額分の話ですけれど、有機野菜になったから、例えば、何か、そういう声があるという意味ではありません。今、先ほど課長が説明したように、献立に全く影響は出ないように、教育委員会で経費についてはしっかりとやっていただけているということを最後にもう一回確認させてください。","respondent":"石井学務課長","answer":"一方で、全体的な物価高騰、有機野菜とは関係のない物価高騰の部分もありますので、その中で様々現場が苦労してメニューを考えてくださっている、これについては、今回の有機野菜の導入とは関係なく生じていることであると考えております。","id":"exchange-023"}]},{"id":"topic-04","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回３件報告されました。この間様々、事案、重大事態が発生しているわけですけれども、今調査中の件数は何件あって、この進捗状況はどうなっているのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"総計ですけれども、全部足し合わせますと３３件になります。現在、それぞれの調査の進捗状況ですが、区のホームページに、調査終了ですとか調査中ということで掲載をしています。すみません、今すぐに出てこないのですけれども、それぞれ公にしながら調査を進めている段階です。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"調査の進捗状況がホームページに公開されているということですが、今年度分だったら分かりますか。今年度１１事案ありますけれども、その調査状況を伺えればと思います。こうした、重大事態の認知をしている中で、やはり再発防止をしていくことが必要だと思うのですけれども、それは報告書などをつくってどのように生かされているのかを伺います。","respondent":"丸谷教育総合支援センター長","answer":"こうしたものを活用しながら、いじめ防止に努めるということと、現在学校間、再発防止のために区立学校内では共有してもよいか、保護者の承諾を得ながら、区立学校で共有して再発防止に努めるための手続を今進めております。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした取組を進めていくのが必要だと思います。実際、区としては、この重大事態、この間３３件、区内で起こっている中で、根本原因についてはどのように考えているのか伺います。その解決、その取組を行っていくためにも、子どもの意見を聞くというのがやはり重要だと思うのですけれども、その点ではどういう対策を行っているのか、または行っていこうと考えているのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"今後、ますますいじめ問題についてはしっかりと向き合っていかなければならない問題と考えておりますので、引き続き、子どもたちへの学習や指導、それから教員への研修といった充実を図っていきたいと考えております。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間報告があったときに、何年生かでは認知度が改善してきた、ほかは駄目だと報告があったと思うのですけれども、その中でもこの環境改善として学校風土の改善が必要だとご答弁があったのですが、具体的にはどういう風土を変えていくべきだと考えていらっしゃるのか、問題となっている風土、そこを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"数年かかるとは思いますけれども、徐々に学校風土も昨年から取り組んでいて改善傾向で、結果は出てきておりますので、継続した取組を続けていきたいと考えております。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"先生に相談できるということも、やはり教員の多忙化を解消していくことだと思いますので、そこについてもぜひ取り組んでいただきたいと思います。やはり子どもの命を守ることを前提に、様々ないじめの要因を１つずつなくしていくことが必要だと思いますので、その取組を進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-05","title":"「品川区社会的養育推進計画（素案）」に係るパブリックコメントの実施","agenda":"「品川区社会的養育推進計画（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"実際に子どもたちや施設の人たちから話を聞いたということで、子どもへのアンケート、あと、里親、児童養護施設職員へのヒアリングを行ったと、あと、児童福祉審議会でもいろいろ議論がされたと思うのですけれども、どんな意見が出たのか伺います。","respondent":"柴田子ども施策連携担当課長","answer":"今回、策定に当たりまして、子ども、里親、それから児童養護施設の職員に、子どもにはアンケート、それ以外にはヒアリングという形で実施をしております。詳細を本編に記載させていただいているのですけれども、本編でいうと２４ページになります。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこを１点伺います。実際、日頃から意見表明ができる割合が約７１％で、これは区としての受け止め、どのように感じているのか伺います。子どもの権利ノートを配付していろいろ周知啓発をしているということなのですけれども、このノートがどういうものなのか伺いたいと思います。大体３年とか５年という感じだと思うのですけれど、理由があれば伺いたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"近いところですと、区主催でボウリング大会を実施して、里親子に多数参加していただいて、次回もぜひやってほしいという声もいただいておりますので、そういったレクリエーションなどもやりながら、皆さんの意識、つながりを高めていきたいと考えております。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"先に、この４年間の計画で、終わりを合わせるとどういうメリットがあるのでしょうか。何かコメント等があれば伺いたいと思います。里親の、横のつながりを強化していきたいということなので、ぜひやっていただきたいと思うのですが、この里親の登録状況は、他区との例はどうなのでしょうか。それは進めるのがいいとは思うのですが、区の見解を伺います。","respondent":"柴田子ども施策連携担当課長","answer":"同じものは難しいと思うのですけれど、権利ということを知っていただく機会は必要と考えています。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、いろいろヒアリングとかアンケートとかやられて、実際の声を聞いているので、それもしっかりと反映させながら、取組を充実させて進めていただきたいと思います。子どもの権利ノートは、では一般的なバージョンに修正をして、ほかの子どもたちにもぜひ配布するような形でやっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらにいろいろな、個別的ケアが必要な子どもの中に、情緒的な問題とか書いてあるのですけれども、現在どういったお子さんがいるか、具体的にもしイメージが分かれば、共有していただけたら、確認したいと思いました。次に、本編２０ページの潜在的需要割合の推計値ですけれども、こちらの少し確認ですが、令和６年度の６名の数字の内訳は、区の児童相談所の部分ということでよろしいのですか。","respondent":"柴田子ども施策連携担当課長","answer":"したがいまして、児童相談所も、今回この計画をパブリックコメントに上げる前に見ていただいているのですけれども、共通認識であると受け止めております。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"子どもの意見を聞くとき、大人としては意見を聞いているつもりでも、子どもは気持ちをそのときは聞いてもらっているので、意見を聞いてもらっているとは思っていないとか、逆に子どもは気持ちを聞いてほしいのに、大人は気持ちではなくて意見を聞こうとしてしまっている、そういった細かいずれがあって、その話がどういったもので、子どもが伝えたいことが気持ちなのか意見なのか、そういったところが。","respondent":"柴田子ども施策連携担当課長","answer":"ただ、委員のおっしゃるように、子どもにとって、意見を言うことと気持ちを言うことは別という話も理解しておりますので、今後、アンケートを実施するに当たってはそういったところをしっかり押さえていけるように対応していきたいと考えております。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"最後、１２月の児童福祉審議会での意見で、区内の社会資源を最大限活用していただきたいとあります。その辺り、この中には、どういった形で取り組まれているのかをお聞かせください。","respondent":"柴田子ども施策連携担当課長","answer":"品川区内にはない施設、資源といたしましては、ファミリーホームや自立援助ホームがありますが、そちらは需要をしっかりと見据えて、対応を今後していきたいという考えです。","id":"exchange-035"}]},{"id":"topic-06","title":"西大井広場公園内における認可保育園の運営期間延長","agenda":"西大井広場公園内における認可保育園の運営期間延長","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"閉園になる場合は、来年度の募集から停止をすることになるのですか。それで今、報告されているということでいいのか確認と、あと、未就学児の人口増加は、増えると見込んでいるという話でしたけれども、見込みの状況を伺います。","respondent":"佐藤保育事業担当課長","answer":"未就学児の人口増の考え方ですが、今年度品川区こども計画を策定いたしまして、その際に最新の人口推計を基に保育の量の見込みを算出しています。その中におきまして、近隣の就学前人口と、近隣の保育園の定員などを鑑みて、人口増、保育園が必要であると判断したものです。","id":"exchange-036"},{"speaker":"まつざわ委員","kind":"意見","question":"説明があったのですけれど、期間限定という話、そもそもがあって、１０年から５年、５年ということは、２０年の延長です。トータル的に２０年というと、私の感覚だと、もはやこれは期間限定なのか。例えば民間を活用するなり、周りに何かそういったところを率先して造っていくとかを考えていく必要性があると思うのですけれど、まずそこをお聞かせください。","respondent":"佐藤保育事業担当課長","answer":"ただ、更新自体は妨げられているものではございませんので、区といたしましては、近隣の保育需要を見ながら柔軟に対応していくように、その更新を行いながら実施していきたいと現在は考えてあります。","id":"exchange-037"},{"speaker":"まつざわ委員","kind":"質問","question":"内容は分かりました。それと、そもそもが１０年の計画です。そうすると、例えば、１０年だったものが、２０年やると、例えば耐久性であるとか、そういった建物の安全面は大丈夫なのか少し心配でありますので、そこら辺の、建築診断、建物の耐久性などがどうなっているのか教えてください。","respondent":"佐藤保育事業担当課長","answer":"建物についてですが、これは当時、法人において建設をされたものでございまして、当時も１０年の期間限定ではありますけれども、建物自体はしっかりとした鉄骨造で建てられてありますので、耐用年数等を鑑みましても特に安全性に問題はないと認識しております。","id":"exchange-038"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"マイスクールでは、１日授業日に仕出し弁当の無償提供を行うことを新事業としてやっているのですけれども、この１日授業日はどのくらいあるのかを伺います。４６校、この全校配置した状況ですとか、この現状の課題などがあれば伺いたいと思います。体制的な問題として足りているのか伺います。この拠点校３校を豊葉の杜学園と荏原第五中学校、鈴ケ森中学校にした理由があれば伺います。","respondent":"丸谷教育総合支援センター長","answer":"不登校対応の巡回教員の関わり方ですけれども、この３名で全ての不登校になっている生徒に関わっているということではなくて、学校の支援体制について一緒に考えたりですとか、助言を行ったりですとか、５校を巡回しておりますので。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"少し分からなかったのですが、マイスクールに通っているけれども３０日学校を欠席している場合があるのですか。マイスクールに登校した場合は出席にはカウントされないのか、その辺がよく分からなかったので伺います。一人一人の子どもとは関わるとかはしていかないのか、その辺この不登校対応巡回教員の方の仕事、役割はどういうことなのかを伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"巡回教員の役割についてですけれども、どうしても週に１回の支援になっていますので、校内別室を利用している生徒への直接的な支援や、学校が不登校対応をどのように進めているかの助言であったり、他校の取組の共有であったり、困っている担任の先生へのアシストだったり。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどいじめのところでも伺ったのですけれども、今、不登校が増えている根本原因は、区としてどのように考えていらっしゃるのか伺います。この資料の中には、不登校の相談事実、上位３項目が書かれておりますけれども、この上位３項目が全部小・中学校ともに同じで、学校生活にやる気が出ない、不安・抑うつ、生活リズム不調、分かれば、それぞれ理由が何なのか伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"生活リズム不調や、不安・抑うつは家庭環境も一定程度影響をしていると捉えておりまして、家庭内の理解であったり、必要に応じて関係機関と連携を取ったりですとか、そういった家庭支援も併せて進めていくべきと捉えております。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり未然に防ぐ、あるいは、不登校になりかけの早期の段階にしっかりと対策を打っていくことが必要と言われましたので、そこを強めていただきたいと思うのですが、区のお考えを伺います。この中学校の生徒の出現率が高い理由はどう分析されているのか伺います。学年別に見ると、３年生、４年生、９年生が、一昨年度から昨年度が増えている状況になっていますけれども、区の認識を伺います。","respondent":"丸谷教育総合支援センター長","answer":"早期の支援も大切だと考えておりますので、我々教育総合支援センター内でも検討を進めております。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"それは何かもし分析があれば伺いたいと思います。中学校の生徒になると学業もいろいろ出てくるということ、思春期ということもありますけれども、そうするとやはりこの学校の環境の中で、子どもたちは勉強に行っているわけですから、勉強への負担、ストレス、やはりそういうのが出てくるのだろうと思いますので、そうした負担を軽減していくこともやっていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そこで、保護者同士の交流ですとか、あとは高校の先生ですとか、都立、私立に関わらず来ていただいて、将来の展望を持てるような取組も行っております。少しでもその不安の解消につながればという思いで行っておりますけれども、今後も引き続き継続していきたいと考えております。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に、いろいろやはり課題はありますけれども、一つ一つクリアをしていただいて、子どもたちが元気に成長していけるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問","question":"順番があれになってしまうのですけれど、フリースクールですが、今日、厚生委員会で、障害児の通所施設の給付費の不正請求についての話があって、数百万円、１５０万円ぐらいあったのです。それから、校内別室指導支援員は、会計年度職員なのでしょうか、それとも、１日４時間で週５日も来られないとすると２人で分けているとか、そういうやり方なのかということが１つ。その辺り、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"フリースクールとの連携、チェック体制ですけれども、現在は、助成金を出すに当たっては東京都の助成を受けているというのが１つ条件としてありますので、そういったことで１つ、区としては質の担保と考えております。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"確認","question":"フリースクール、今連携、協議会みたいなものをつくって情報交換、お互いにどういうことなのかを理解してやることが大事なのでぜひお願いします。少し確認は、会計年度職員ではないということでしたけれど、お二人で時間を分けている学校とかもやはりあるのですか、月水金は誰とかそういう、逆に言うとそれが可能か、そういう形で埋めている方があるのでしょうかというのが１つ。そこだけお願いします。","respondent":"丸谷教育総合支援センター長","answer":"全体の予算、学校が与えられた予算の枠の中でその校内別室指導支援員を配置しておりますので、日によっては曜日で分けたりですとか、場合によっては２人配置する曜日を設けたりですとか、うまくその辺りは学校で調整をしておりまして、そこで情報の共有ですとか。","id":"exchange-046"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"マイスクール八潮でこの昼食支援があって、半年で４６８食という利用実績があって、やはりこれ、食べ物、食というのは子どもの居場所をこうやってつなぎ止める強力、強烈な、食というのはすごく大事だと、これを見てすごく思うので、例えば八潮以外のほかの３か所、こういったことに昼食支援はどんどん拡大してほしいので、どのような感じか、教えてほしいと思います。","respondent":"丸谷教育総合支援センター長","answer":"五反田と浜川につきましては、現在、半日の受入れとなっておりますので、午前の部と午後の部と分けて、子どもも分けておりますので、現在、昼食提供までは至っていないのですけれども、今後、運営をしていく中で、１日フルで行うような曜日ができる際には。","id":"exchange-047"},{"speaker":"まつざわ委員","kind":"質問","question":"よく小１の壁、中１のギャップがありながらも、このグラフを見ると、令和６年度は令和５年度に比べて、不登校数がそこだけ減っています。これは何か、区がやってきたことがはまったのか、ここの本当に減少した要因というのが一体何なのかを聞きたくて、それをいろいろ分析していくと、これからのカリキュラムがつくれると思っているのですけれど、そこら辺をどう思っているのか教えてください。","respondent":"丸谷教育総合支援センター長","answer":"まさに生活リズム不調については、学校だけではなかなか改善が難しいので家庭の理解や協力が不可欠であると考えております。そういった意味では、学校から啓発資料を出したりですとか、生活リズム、早寝早起きの講演会を開いたりですとか、そういった取組も併せて行っています。","id":"exchange-048"},{"speaker":"横山委員","kind":"質問","question":"聞き逃した部分があるかもしれないのですけれども、仮想空間を活用した学習支援・居場所づくりでの利用実績の見方ですが、１１０アカウントが、東京都のバーチャルラーニングプラットフォーム事業への参加の１１０アカウントで、そのうち５８人の利用の実績があるという意味でいいでしょうか。そこからお願いします。","respondent":"丸谷教育総合支援センター長","answer":"１１０アカウントは東京都から品川区に付与されたアカウント数です。そのうち、現在５８アカウントの申込みがあって、品川区の児童生徒に区から付与している数になってあります。","id":"exchange-049"},{"speaker":"横山委員","kind":"確認","question":"今年は７月と１１月ですか、２回実施されているようで、７月が６９名参加で、保護者全体というより個別相談のような形で案内には書いてあるように読み取れるのですけれども、保護者の方のニーズ、保護者同士でお話するとか、そういったことを案内で、品川区の事業ではない保護者の集いも載っているので、そういったところにほかの保護者の方と交流をされたい方は通っているのか。","respondent":"丸谷教育総合支援センター長","answer":"２回目は、今日説明させていただいたような、様々区で行っている不登校支援の取組について事務局から説明させていただいて、質問をいただくですとか、また、そこは割とフリーな形で、保護者同士も交流できるような空間にはなってございましたが。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"様々な手法があり、様々ほかの自治体も取組があると思うのですけれども、品川区の不登校の状態になっているお子さんや保護者の方のニーズ、お声を聞いていただいて、今後の展開については、ぜひ反映させていただいて進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/176898?Template=document&Id=7291#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":52983,"voices":151}},{"id":"r08-20260119-5","meetingId":"r08-m01","date":"2026年1月19日","dateIso":"2026-01-19","committee":"総務委員会","time":"午後 １時００分～午後 ３時２９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","topics":[{"id":"topic-01","title":"定額減税しきれないと見込まれる方への給付金（不足額給付）の事業実績","agenda":"定額減税しきれないと見込まれる方への給付金（不足額給付）の事業実績","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"その中には、何らかの障害やご事情があって申請自体にハードルを感じたり、経済的に困窮しているにもかかわらず、本当に支援が必要であるにもかかわらず、その支援が受けられていない方というものがいらっしゃるのかなと思うのですが、コールセンターには例えばどのような相談があったのかなどということも教えていただきたいということと、今後。","respondent":"宮澤税務課長","answer":"支援が必要な方への対応ですけれども、今回の給付金につきましては、電話等で、もしくは来庁された方もいらっしゃいまして、そういった方々には職員のほうで説明の上、申請のほうにという形はさせていただいたところです。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"事務経費についてですが、これは全額が国から来るという認識でよろしいでしょうか。それと、事務が結構煩雑だったのではなかったかなと思うのです。事務経費というものはどのぐらい、ここに計上している以外だと思うのです。どのぐらいかかっているのかということと、それの補償というものが、国からどのような補償が来ていて、どのような負担になったのかということを教えてください。","respondent":"宮澤税務課長","answer":"令和７年度についてもほぼ１億円強の事務経費がかかっておりますので、給付額および事務経費につきましては、国から全額入る、負担いただけるというものです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"金額からいうと、当然国から出てくるだろうということは再認識をしていますけれども、結構手間だと思うのです。コールセンターがあってというようになっているのですけれども、コールセンターの費用は全部賄えられたのか、職員の方々がかなり手間取ったような状況なのか、その負担という、負担感というものを踏まえて、それがどのような状況だったのか教えてください。","respondent":"宮澤税務課長","answer":"コールセンターにつきましては、事務委託ということで８回線を設置し、それで令和７年度についてはトータルで２,１２４件のお問合せがあって、コールセンターのほうにつきましては、委託の範囲内で直接に対応ができると。それほど回線が混み合うということはなかったです。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"ですから、もう少し、これ国の政策なので、品川区の執行機関でやらなければいけないということはあるのですけれども、だからあまりにも事務的な負担というものが多くなっているのだとすれば、それは国のほうにも追及というか、報告してもいいのではないかなとも思いますが、そこだけ、国に対してのそのような報告はされないのか、されていなかったのか、あまりひどいときには抗議する予定であるのか。","respondent":"宮澤税務課長","answer":"その中で区として迅速に給付ができるように、適切に事務を進めてきたところですので、特に国への何か報告という、そういったところでの報告の予定はないところです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"ほかの自治体とも共同してもいいと思うのですけれども。その辺を、今後もこの物価高まだ続きますので、こういった施策が出てきたとしても、区のほうでそれだけの負担がかかるというところは、きちんと国にこのような負担がないようにしてほしいというようなことは言ったほうがいいのではないかなと思うのですけれども、いかがでしょうか。","respondent":"宮澤税務課長","answer":"税務課、住民税を賦課徴収しておりますが、繁忙期というものが１月から６月という前半部分で、後半期は通常随時期という業務が一定落ち着く時期に、この定額給付金の事務を当たっているというところで対応してきているです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、そこはぜひ、私たちもですけれども、国のほうに要望しながら、議会としても要望しながら、自治体の手間というのですか、その負担感、そこを軽くするような対策というものを求めていきたいなとも思いますし、区からも、ほかの自治体とも声を合わせて、ぜひ国には言っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"塚本副委員長","kind":"質問","question":"今までの議論の中で、国のほうで、この給付つき税額控除というものを本格的に検討するということが始まっていて、今回のものとかなり似ている制度かというように私は理解しているのですけれども、このようなものを進めていく、検討されていく中で、今言ったような自治体の負担、そもそも自治体が、今回のように、給付や対象者の抽出などというものはやらなければいけないのかというところや。","respondent":"宮澤税務課長","answer":"ただ、今回実施したような形というよりは、税制改正の中で議論されておりますので、何かそういった１つの税の控除の仕組みという形になるのだろうと考えていますが、そこについては国から示されることを待っているという状況です。マイナンバーの活用です。","id":"exchange-007"}]},{"id":"topic-02","title":"広報媒体を活用した情報発信の強化","agenda":"広報媒体を活用した情報発信の強化","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"情報発信の強化ということで、広報しながわとホームページがリニューアルするということで、このホームページのほうは、いろいろほかの自治体のホームページを見たり、民間のホームページを見たりなどする中で、品川区のホームページの目的のものに到達するまでがすごく手間がかかったり、あと見やすさなどがある、そのようなものを感じている区民の声のようなものは聴く場というものはあるのかということ。","respondent":"與那嶺戦略広報課長","answer":"どういったページになっていったらいいかというところを、現状、公開でアンケートを再度取っていくというところまではまだ考えてはいないのですけれども、ただホームページについては、今リニューアルを様々進めていまして、そういった状況のいい部分の確認や、あと。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"今、デジタル強化と広報しながわをこれからの価値向上推進というお話があります。今、何万世帯に行き渡っているのか分かりませんが、できれば教えてください。今、スマホの問題と広報しながわの問題について言わせていただいたのですが、区としての見解をちょっと教えてください。","respondent":"與那嶺戦略広報課長","answer":"我々としても、新聞購読者数の減少分にはまだ届かないのですけれども、例えば駅や、あとコンビニエンスストアなどに広報紙スタンドを設けまして、そこで新聞を取っていない方でも受け取ってもらえたり、あとご希望いただけた方には自宅への個別配送も実施しており。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"広報紙見て、すごく感心させられるのです。例えば救急病院の情報など様々、保育や高齢者、障害者の事業、区でこれからやろうとしていること、このようなボランティア制度がありますなど、そのようなことを思うと、私はやはり広報紙の発行数ではなくて、できれば配布数を増やしていくということを片一方では進めていくべきだと思うのですが、どうでしょうか。","respondent":"與那嶺戦略広報課長","answer":"そのような意味でいくと、いわゆる紙とデジタルは融合させながら周知していくということも大事かなと思っておりまして、特に新聞を取らない世帯というか、世代というところは、比較的若い世代が多いだろうというところでいくのであれば、今の広報紙。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後意見だけですけれども、どこかの施設へ行ってもらって見てくださいというのではなくて、やはり各家庭で郵便ポストに入っているという全戸配付のような仕組みが必要だと思うし、これに予算かかろうとも、区の情報を多くの区民の方に知らせていくという姿勢はやはりなくしてはいけないと思うので、何とか広報紙の発行部数ではなくて、より配布部数を増やす努力を私は今後も続けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"今の議論も踏まえて、広報しながわについての役割というものをどう考えているのでしょうか。細かいところまで、隅々見ている方はいます。ですから、やはりかなり有用だと思うのです。ですから、少なくなるわけです。この減らすという意味でいうと、経費削減という目的もあってこのような状況になっているのか、その辺はどうなのでしょうか。教えてください。","respondent":"與那嶺戦略広報課長","answer":"広報しながわの役割と、あと費用の部分についてご質問いただいたかと思います。広報しながわの役割といいますか、多くの区民の方に見ていただけると、それは我々も十分に認識しておるところです。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"ですから、そのような決め事、それから広報紙の中に区民の皆様からの告知、掲示というものがあります。そのコンテンツ、同じであってほしいなと思うわけです。それをなかなか載せてくれなくて、やはりこれは全体を把握した形で載せるべきなのではないかな。結局それもデジタル化になったときそれが反映することになると思うので、そのようなものは改善は期待してよろしいのでしょうか。いかがでしょうか。","respondent":"與那嶺戦略広報課長","answer":"広報紙の、現状コンテンツの部分なのですけれども、当然これデジタルでも載せますし、そこの内容は同じものができますので、デジタルと紙で差異が生じるということはないというようにご理解いただければよろしいかと考えています。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"情報発信をアップデート、特に区民目線での情報発信をしてほしいということは昨年の私の一般質問でも要望してきたことですし、一般質問以外でも様々お願いをしてきたところで、課題として区民の皆様にどう情報を届けるか、それから関心を持っていただくかということは課題であり、もっともっとよくしていってもらいたいというところでございました。発行回数を２回にして特集記事を含めると。","respondent":"與那嶺戦略広報課長","answer":"ホームページは、区の職員、各部署それぞれが入力しているものなので、今回のプロジェクトを通じて、まず庁内の中にそういった意識をつけていくであるとか、ホームページのつくり手側の部分のスキルアップというところも含めて実施していこうかなと。","id":"exchange-014"},{"speaker":"石田（秀）委員長","kind":"質問","question":"ほかに。いいですか。それはよくなるというのならそれでいいけれども、なぜ発行回数を３回から２回にしたのですか。意味ないではないですか。それだったら、そこを伸ばす方法はどうするつもりでいるわけですか。なぜそのような幼稚園や、保育園や、小学校などにそうやって個別配送を、このような希望があればお配りしますと、もっと情報をなぜ流さないのですか。なぜそのようなことをしないのですか。","respondent":"與那嶺戦略広報課長","answer":"ただ、広報紙全体の、１０万部強というところの規模からすると、まだまだ一部だというところはそのとおりですし、そこの周知が足りていないというところのご指摘については、我々は重く受け止めなければいけないと考えています。","id":"exchange-015"}]},{"id":"topic-03","title":"「ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画」に対するパブリックコメントの結果","agenda":"「ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画」に対するパブリックコメントの結果","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"このコメントの中にも、課長も今説明の中で言ったように、条例の認知度が低いという状況の下で５５人から９６件の意見が寄せられたというところでは、多かったのではないかなと私は思いますけれども、区としてはこの数というものをどのように見ているのかということを伺いたいということと、あと寄せられた意見の中では、要望だったり、提案だったりというものがあるのに対して、区の見解というものが。","respondent":"木村人権・ジェンダー平等推進課長","answer":"この意見に対する見解につきましては、５月の１日の結果公表時期に合わせてご回答すべく、今、各課と調整をしていますが、同時に計画の最終調整をさせていただいておりまして、このご意見の中で、例えばコラムのような形で読みやすくしてほしいといったようなご意見など。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしたら、では５月のところで回答も載せるという方向で進んでいると。ですから、ここへのさらなる周知というものはこの間も私たち求めているところですけれども、改めてパブリックコメント等でも寄せられている意見をもとに、さらなる強化をすべきだと思うのですが、その辺は、今後回答で示されるものかもしれませんけれども、今の時点でぜひ伺いたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"ＳＮＳへの周知の際に、結構それで条例を初めて見たという方もいらっしゃいますので、引き続きそのような形で実施をさせていただければと考えています。周知の方法につきましては、来年度も引き続き、より見ていただけるような形で周知を行ってまいります。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。そういったところでも、やはり区の姿勢が、見えつつあるのかなというところもあると思うので、引き続きこうした姿勢で進めていただきたいなと。このパブリックコメントも本当に区の姿勢を後押しするようなものがたくさん寄せられておりましたので、引き続きジェンダー平等、そして主流化を進める区として頑張っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、そのような形の方は必ずいるはずで、それに対して区の見解というものをどう出されるのかなという、その調整です。これおかしいと思うのです。多分そのようなものを踏まえて計画されているのではないかなと推測しているのですけれども、その辺の考え方、特に意識の変容というものが求められていることだと思うので、どのように検証がされていくのかなというところを教えていただきたいと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"まちで説明をしたときに、このような方はいらっしゃらないというように言われる方がいる反面、やはりうちの講座やグループなどで性的マイノリティーの方々の集まりがあったり、そういった方々の悩みを聞く相談を受けていたりはしますので。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"だから、今の段階は意図して意識を高めるという意味で、このような計画を立てたりということがあるのでしょうけれども、ただ、何でしょうか、権利というか、主張するという方向になることが違うのではないかなと。大本ここから来ているのですよということが分からないと、なぜ唐突的に品川区はやっているのというような形になってしまうので、そこの説明の仕方などはいかがでしょうか。","respondent":"木村人権・ジェンダー平等推進課長","answer":"２個目の質問の、全体の動きの中でどのように周知を進めていくかというところなのですけれども、この計画につきましては、内容が多岐にわたっているというように伝えましたが、区民全員に関係することになると思いますし、全ての事業に関連してくるということで、今回。","id":"exchange-020"},{"speaker":"松本委員","kind":"確認","question":"確認なのですけれども、これ意見応募状況で応募者数５５人という方かと思うのですが、これは意見公募においては区内在住なのか、そうではないのかというところ、統計が取られていたり、あるいはたしか品川区の場合は、特に区内在住者に限らずやっていらっしゃるかと思うのですけれども、今回のこの意見の応募された方で。","respondent":"木村人権・ジェンダー平等推進課長","answer":"こちらにつきましては、基本的に区内在住・在勤・在学の方に向けて募集をしたところではあるのですけれども、その内訳につきましては、特に統計を取っているものではございません。こちらのほうには性別等も書いていないのですけれども、そちらのほうについても伺っておりません。","id":"exchange-021"},{"speaker":"松本委員","kind":"質問・要望","question":"そしてこれがなぜ大事かというと、撤回とか、取り下げてしまうと、それはそれで品川区としての撤回してしまったということが、逆に政治的な何かを伝えることにもつながりかねないので、出す以上は、もうこれはご批判が来ようとも、もちろんこの事実の認識の間違いなどもあれかと思うのですけれども、ご意見をいただくことも、ここは品川区としてはすごく重要だと思っているからこうなのだというところを。","respondent":"木村人権・ジェンダー平等推進課長","answer":"講座等につきましても、どういった内容をやるかというところは、業者の方や先生、あと何よりも今委員会を持っていますので、委員会の様々な有識者の方々とご相談しながら進めているところですので、対応については注意して進めていきたいと考えています。","id":"exchange-022"},{"speaker":"松本委員","kind":"意見","question":"もう本当にすごくこれは難しい問題で、品川区も男女共同推進参画フォーラム、中止というようなことを、２年か３年ぐらい前にあったかと思います。あれもやるべきなのか、やらないべきなのか、どちらを取っても多分いろいろなご意見が来ることになっていると思うので、この部分はしっかりと有識者の方とご検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"これだけ意見を要約されて、皆さんから出していただいて大変だったと思うのですが、私の認識不足だったら言ってください。それに対して、やはりこのようなことをやるなら、区や都が率先して取り組んでいかなければならない事業だと私は思うのですが、国や都に対して、都は実現するための計画はどの程度進んでいるのでしょうか、教えてください。","respondent":"木村人権・ジェンダー平等推進課長","answer":"国や都との並びという話だと思うのですけれども、ちょうど今国のほうでも、第６次男女共同参画の計画について、まだ検討中というか、素案の段階ではあるのですが、策定中というところになっております。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"ということならば、本来国と都と区、全国になるのでしょうけれども、やはり全自治体が国と一緒に一体となって皆さんで検討していかないと、どこかで食い違ってしまうのではないかなというような、そのようなことまでちょっと心配してしまうのです。今様々なことに対して課長が答えられていた。その辺がちょっと心配しているのですが、それについては大丈夫なのですか。教えてください。","respondent":"木村人権・ジェンダー平等推進課長","answer":"条例のときにも行わせていただいたのですけれども、計画を策定した後は、まちの方々へのいろいろなところでの説明をする機会を持たせていただこうと考えていますので、地域の方たちのご意見を伺いながら。","id":"exchange-025"},{"speaker":"塚本副委員長","kind":"質問","question":"別にここに書かれていることがおかしいとか、そのようなことではないのですけれども、この立てつけからいうと、あえて外国人のことについて触れられているというか、計画に盛り込まれているというところの、区としての何か思いや意図というものが特にあるのであれば、お伺いしたいかなと思います。","respondent":"木村人権・ジェンダー平等推進課長","answer":"こちら「ジェンダー平等と性の多様性を尊重し合う社会を実現するための計画」というような名前になっておりますが、男女共同参画のための行動計画や、配偶者暴力、女性活躍推進、困難女性支援等の様々な内容も入っております。","id":"exchange-026"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西本委員","kind":"質問","question":"どのようなお話が、今の段階でいいので、予測も含めて変わっていくものなのでしょうか。これだけ収入が上がっているので、かなり品川区においても要になっている事業の１つではないかなと思っているのですけれども、それとアリーナをつくるということで、アリーナなどの収益というものは全く関係なくなってしまうのですか。その辺をちょっと教えてください。","respondent":"藤村総務課長","answer":"移転について、移転後、例えば小林牧場というものがありますけれども、小林牧場がどういったようになるのかというところもまだ決定していないというところですので、完全移転なのか、少し残していくのかというところも、恐らく今後の検討という形になるのかなと思います。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"本当に申し訳ないですけれども、報道ベースになってしまうと思うのですが、心配はお馬さんたち大丈夫かなという。結局、大井競馬場を開催できなくなるような状況になってしまうと、また大きく変わってくるなと思うのですけれども、今の段階でそれはないという。大井競馬場のレースはあるよと思っていたらいいのか、それもちょっとあやふやな状況になっているのか。そこはどのように考えたらいいですか。","respondent":"藤村総務課長、石田（秀）委員長","answer":"今回、報道発表ベースの話ですけれども、トレーニングセンターの新設という形ですので。今これインバウンド対応で、平和島から羽田空港まで深夜便がすごく多いので、例えば品川駅周辺に泊まっている方。１号交付金につきましては、まず特別区競馬組合にしっかりこういったお話が品川区の議会から出ているということは伝えていって。１つ情報だけ。品川駅周辺とされていて、清正公前の都ホテルまで入っているのだけれども、これ部屋数でいうと日本一なのです。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は常々言っているのですけれども、やはり競馬というところではギャンブルということで、ギャンブル依存症というところが心配です。それが競馬というように絞ると、絞られているかどうかということはあるか、分からないかもしれないのですけれども、その辺もしあれば伺いたいと思います。","respondent":"藤村総務課長","answer":"ギャンブル依存症の方の数というものは手元で把握していないので、区で統計を取っているかというところもお答えしかねるのですけれども、特別区競馬組合のほうでは、ギャンブル依存対策ということで、しっかりお客様に対しての対応というところでも。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですから、ぜひ把握をしていただいて、区としては、そのような方への、そういう方がどのような対応をされているのか、何にもかかっていないというか、治療等にもされていないという場合であれば、それを放置するわけにもいかないですし、それの下で競馬を楽しむということにもなかなか行きづらいのではないかなと私は思いますので、そういったところも把握をしつつ。","respondent":"藤村総務課長","answer":"競馬に限った話というところになってしまいますけれども、競馬の売得金額というものが増えることは、確かに競技人口が増えている側面はある一方で、このギャンブル依存症に対する対策というものもまた充実していく、費用をかけて充実していけるものなのかなと思いますので。","id":"exchange-030"}]},{"id":"topic-05","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回の衆議院の解散ということで、国の予算が決まらないではないですか。それは品川区に至っては、その予算に対して執行するに当たって、何か影響が出るのですか。簡単でいいので教えてください。それからこの選挙、今日は選挙管理委員会事務局長がいないのですけれども、選挙は大丈夫なのですかということを、分かる範囲で、もし分かる人いたら。","respondent":"加島財政課長","answer":"こちらの補正予算案の扱いにつきましては、また後ほど各会派のほうにご説明させていただければと考えております。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"間に合うのですか、これ。日にちがないではないですか。選挙が執行されるのに。何かすごく不安を抱えるので、では徹夜して、印刷関係の会社から何かやらない限り、私はできないように感じるのです。でも何とかできてしまうものなのですか。","respondent":"堀越副区長","answer":"今、選挙管理委員会事務局では、総務省などからも事前準備の通知なども来ていますので、状況を見ながら、情報を取りながら、一生懸命準備しているところです。決まった段階では速やかに執行できるように、準備を進めているです。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"では具体的に言いますと、２月５日が議案説明になっているではないですか。私は無所属なので、無所属に対しての予算案の説明は１月２９日の午後３時からになっています。ほかの会派の方々は、多分２８日からなのですか。ですよね。ということは、本来は議案説明が２月５日だから、公開の起点というものは議案説明ですよね。プレス発表はその前、その後。今回、区長のプレス発表はいつなのですか。","respondent":"藤村総務課長","answer":"今まだ明確に日程のほうは決定がしていないところですけれども、議案説明会の後ということで予定はしております。","id":"exchange-033"},{"speaker":"西本委員","kind":"意見","question":"基本はそうなのだけれども、リークしようが何しようが、ご勝手にどうぞということですね。","respondent":"石田（秀）委員長","answer":"それは、ここに書いてある言葉のとおり言うと、勝手にとは書いていなくて、説明があって、会派ごとの説明があります。これ議長のそのとおりの言葉で言います。会派ごとに説明、重点施策、新規事業を中心に説明、質疑もあります。これ以降、議員より各所管への問合せは可能です。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"情報の取扱いについてはそれぞれの議員の責任においてと、それは理解できます。その責任においてといったときの判断というか、行為というか、行動というものが、ではマスコミにリークしても構わないのですねという話ではないですか。それもオーケーなわけでしょう。それこそマスコミの人たちの努力によって情報をつかんだわけだから、それを公開してもいいですよということなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"では議会のほうに報告をするまではリークはないという理解でいいのですか。ということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"西本委員","kind":"意見","question":"でも決まりは決まりだから、区としてどう考えているというわけではなくて。","respondent":"藤村総務課長","answer":"リーク云々という話というものはちょっとまた違うかなと思うのですけれども、原則論として、区としては議案説明会を１つの起点として考えているというところ、それ以後に外が情報に出ていくというところが、申し上げているところの全てです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"では今山本委員が言ったように、だから仮に、議案説明会が２月５日なわけではないですか。その前に外部に漏れたりなどしていたら、問題だということの認識でいいですか。それさえ認識すれば、去年はプレス発表の前、前というか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"ということは、仮に２月５日より前に漏れたということになれば、議員が誰か漏らしたということになるわけですよね。だから行政側が、そこのところは議長は、責任を持ってやってくださいねという形だと思うのです。ということは分かりました。ただ行政側からは、２月５日前には情報は出ませんよという理解ですか。もちろん情報が出たときに、前に出たら、では議員が何か誰かやったのねという理解でいいですか。","respondent":"藤村総務課長","answer":"原則、区としては、対外的に情報が流れるということは、議案説明会以後という形です。","id":"exchange-039"},{"speaker":"西本委員","kind":"確認","question":"すみません、もう１点。私は、フローレンスとの関わっている事業どれぐらいあるのということを、確認を今入れているのです。だけれども、このようなほかの区のほうで不正を働いているという問題になったときに、どのような対応をするのですか。契約している委託事業などというものを調べるのか、どのような方法で調べるのですか。ほかの区だから関係ないといって調べないのか、どうなるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/624041?Template=document&Id=7299#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":47598,"voices":126}},{"id":"r08-20260120-21","meetingId":"r08-m01","date":"2026年1月20日","dateIso":"2026-01-20","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"西村委員","kind":"質問","question":"今日は、視察にご対応いただき、ありがとうございました。最後に不登校支援のお話を聞かせていただいたのですけれども、マイスクールではできないことをすごくしていただいているという印象がありまして、お伺いできればと思います。","respondent":"柴田子ども施策連携担当課長","answer":"しかしながら、年齢を超えた交流というところも非常に双方にとって学びだったり経験というところになりますので、その辺はまだ区としていろいろな形があるというところで、研究の段階であるかというふうに考えているところです。","id":"exchange-001"},{"speaker":"西村委員","kind":"質問","question":"すごくよく分かります。二十代が通える精神のデイサービスがないというのもいろいろな自治体での課題なのかと思うのですが、この辺りを伺えたらお願いいたします。","respondent":"柴田子ども施策連携担当課長","answer":"保健センターでしたり、児童相談所、子ども家庭支援センター、そうした専門職がいるところにつながりがあるというところではありますが、ニーズというところはやはりあるというのも今日のお話を通じて感じましたので。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"今日見させていただいて、ニーズがすごく多いと痛感いたしました。複雑なご家庭であったり、それ以外でもやはり今の環境は低年齢からの受験戦争であったりとか、学校でもいじめの問題とか、本当に生きづらさを抱えている若者、子どもから大人までですけれども、そういった居場所というのはすごく必要だと思います。最終的にはそういう場になったらいいと思うのですが、そういうのはいかがでしょうか。","respondent":"柴田子ども施策連携担当課長","answer":"それは、そこでの経験、自身が不調だった時期を乗り越えたからこそできるサポートがあるということで、ユースワークの勉強の場にもいらっしゃっていますし、そうしたところでご自身の経験とこれからの展望なんかも話してくれていて。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問・要望","question":"１点です。町会と一緒に餅つき大会に参加したりとか、やはりその中だけでなく町会でも人間関係をどんどん広げていって、また、町会の中での別の場所を見つけていってほしいと思いますので、２件目をつくるときにもぜひまた地元の町会の方ともご協力いただきながら進めていっていただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その辺の連携というのは、どういう状況になっているのかということを伺いたいと思います。そこで、運営委員会が毎月行われていると伺いましたけれども、これは区の職員はどなたが入られているのか。それから、子ども若者協議会というのもあってもいいのではないかというのもご意見としてあったと思うのですけれども、このことに対しての区の考え方についても伺いたいと思います。","respondent":"柴田子ども施策連携担当課長","answer":"ただいま委員からもご案内いただきましたとおり、１０法人でネットワークを形成しております。しかしながら、このそれぞれの団体にはつながっているネットワークがそれぞれにありますので、そこを含めると５０団体は下らないかという認識でおります。","id":"exchange-005"},{"speaker":"つる委員","kind":"確認","question":"何年かぶりに状況を確認させていただいて、そのときよりも少しいろいろと充実しているのかということを感じました。鈴木委員のほうからもあって、区が月１の運営委員会とか、どういう形なのかと今伺ったとおりです。","respondent":"柴田子ども施策連携担当課長","answer":"先ほどの視察でも「おはもふ」という事業のお話があったと思うのですけれども、そういった方々がまずつながっていて、関連企業などにつながるというお話もあるとは聞いているのですけれども、積極的に企業に来てもらって様子を見てつながるということは。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"ですが、その上で初日なのか何日なのか何年なのかというのは一人一人によって違うと思うのですけれども、四角張ってやるとなかなか抵抗感があるかもしれないので、企業などの訪問を自然な形で、触れ合う機会というのですか、事業紹介とまでいくとまた四角四面になってしまうかもしれません。さっきあの場で伺ったような取組を実際にやっていただいているというのはもうあると思います。","respondent":"柴田子ども施策連携担当課長","answer":"中塚代表とも話す機会がありますので、その辺を１つのアイデアとしてありがたくいただければと考えております。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"それと、改めてですが、現在の分母というのでしょうか。今の若者ケアラーの冊子を読んでいたら本当に涙が出るくらいの体験の話が紹介されているのですけれども、１０法人がある中でいろいろなところでキャッチいただいていると思うのですが、潜在的な部分でどれくらいあって、どれだけキャッチできているのかということを、前後してしまうのですが、教えてください。","respondent":"柴田子ども施策連携担当課長","answer":"ただ、現場で話を聞いていると、そういったところに何かしらの形で手が届くように、それが学校であったり家族の支援であったり、様々なところでリーチできるような仕組みというものをそれぞれ工夫しながらやってくれているので。","id":"exchange-008"},{"speaker":"ゆきた副委員長","kind":"質問","question":"本日の視察を通して、子ども、若者が落ち着ける場、逃げ場というか、何もしなくてもよくて行ける場の需要が必要ですし、需要もこれから伸びていくだろうというふうに感じました。約２００名の登録で、平均２０名というところ。その上で、スタッフの人数は２０名とありましたが、どのようにスタッフの求人について周知をしているのか。その辺についてお聞きできればと思います。","respondent":"柴田子ども施策連携担当課長","answer":"ちょうど最近のお話ですけれども、もう少しスタッフの幅を広げたいというお話も運営のほうから聞いておりまして、支援団体から「合同で品川区で子どものためにこういう取組をやっています」という説明会をやりたいというお話もいただいているところなので。","id":"exchange-009"},{"speaker":"ゆきた副委員長","kind":"確認","question":"確認できました。通えない方もいらっしゃるかもしれないのですけれども、約２００名の方が登録しているということで、居場所も今後２箇所目のところを確保していくように探していくとありましたが、スタッフ側の人材についても確保していくというか、登録していくという動きも必要と思われます。人材の確保については、どういうふうにお考えかお聞きできればと思います。","respondent":"柴田子ども施策連携担当課長","answer":"今後適地が見つかればニーズに応じて新たなところもということで検討をしているのですけれど、人に関してもそういった専門分野の方たちのネットワークは強固なものがありますので、そういったところと区がしっかりとつながっておいて。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/603633?Template=document&Id=7301#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":10302,"voices":27}},{"id":"r08-20260120-20","meetingId":"r08-m01","date":"2026年1月20日","dateIso":"2026-01-20","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 ４時４０分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"前回、７月の質疑でＰＦＩ事業ですけれども、区民意見を踏まえた上で策定された施設計画の実現の上で課題があることや、また、導入の必然性も不明確という中で、改めてＰＦＩ事業による施設建設と運営の方針をやめるよう求めたいと思うのです。指定管理者の場合は議決があるのですけれども、今回のＰＦＩ事業の場合、今後の議決があるのかも含めて伺います。","respondent":"吉岡政策推進担当課長","answer":"令和９年の秋頃、ＳＰＣ、事業者との契約締結を考えておりますので、その段で議決をお願いする予定です。当然、維持管理に関しては指定管理者という位置づけになりますので、その段においても議決をいただくために審議に付していただくところです。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"今回の概要のところが、図書館機能を核とする複合施設というタイトルで、幾つかたしか今でもご指摘させていただいたとおり、図書館機能が蔵書数等も含めて、少し他の図書館機能を我々は中心とするという言い方をしてきたのですが、なかなかそこが少し構想として弱いというご指摘もしてきたのですけれども、ここで核とすると出てきたということは、やはりそこについては。","respondent":"吉岡政策推進担当課長","answer":"詳細につきましては、また次月にご説明させていただければと思います。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/838925?Template=document&Id=7303#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":2879,"voices":14}},{"id":"r08-20260121-22","meetingId":"r08-m01","date":"2026年1月21日","dateIso":"2026-01-21","committee":"まちづくり・公共交通推進特別委員会","time":"午後 １時００分～午後 ２時５９分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"花海道については、東京都が同時期に、同箇所の護岸を整備することを計画しているということですけれども、そうすると、この花海道の修景について、東京都が整備してくれることになるのかというか、そのように区としてもお願いしているのか、どのようになっているのか伺いたいと思います。","respondent":"大友公園課長","answer":"こちら、東京都港湾局のほうで計画しているものなのです。護岸の高さが、今後の気象変化等々を踏まえると足りないというところで、護岸の高さを上げる計画をしているとお聞きしています。その具体的な手法は、今現在東京都当局のほうで検討しているとお聞きしています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ここに東京都が手をつけるなら一緒にできればよいと思ったもので、どうするかは東京都次第かもしれないですけれども、ぜひそこは区の要望等も伝えながら、一緒に整備できるといいなと思いました。ちょっと確認させていただきたいと思います。これは橋だけでないのかを伺いたいと思います。このライトアップ構想を策定することで、予算がアップされていくという考えでいいのか伺いたいと思います。","respondent":"関根河川下水道課長","answer":"何点かご質問をいただきました。ライトアップの箇所数です。現時点で区の橋梁、１３の橋に対してライトアップを実施をしております。２点目です。今後のライトアップ構想について橋だけかというご質問です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。現在この維持管理がすごく大変だということも聞いていまして、消えてしまっているところもあると聞いてはいるのですけれども、今どれぐらいあるのでしょうか。都庁に光を当てるプロジェクション・マッピング、そこら辺はすごく批判の声もあったので、そういったものとつながっていくものなのか、ちょっとそこを伺いたいと思います。","respondent":"関根河川下水道課長","answer":"まさしくご指摘のとおり、これから検討してまいります構想の中では、そういったメンテナンスしやすい、例えばライトアップ施設の配置等がひとつ考えられると思いますけれども、そういったメンテナンス性というものも考慮して構想を作ってまいりたいと考えております。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"分かりました。ライトアップは見映えも良いですし、そのにぎわいだったり、そういったところでやっていくというところでは良いと思うのですけれども、無理に進めていくものでもないのではないかと思います。そういったところで進めていっていただければなと。そして、やはり地域や住民の皆さん、近隣住民の皆さんの思いや合意等も当然ながら含めて、進めていっていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"すみません、何点かまとめてお伺いをしたいと思います。これは全てこの勝島地区なのか、目黒川も含めた数なのかということの確認です。橋を渡る通行人の方なのかどうか。船なので、そこの乗り降りだけではなくて、そこから乗った方が、では別のところに移動する際の、その他の桟橋なり船着場との連携ということへの支援というのをどう考えているのかということを、まとめてお伺いしたいと思います。","respondent":"関根河川下水道課長","answer":"そうした協定を締結しておりますので、特定の方に限定したというよりは、広く利用する方向に向けて検討するものと、進めていくものと区としては認識していますし、そのための支援を区としても行ってまいります。","id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"１３か所のうちの２か所がこの地区であり、そのうち、勝島橋はまだ修理中ということではありました。それがまちづくりビジョンの全体の構想にもつながりますので、活性化にもつながりますので、お願いしたいと思います。特に大井競馬場の船着場も含め、区内にも他に何か所もありますので、イベント支援と同時に災害発災時にも活用できるような視点での取組をぜひお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"えのした委員","kind":"提案","question":"以前も目黒川のライトアップについて、様々私のほうもご質問とご提案もさせていただきました。こちらの目的は今、お伺いしましたけれども、効果というかそういった検証というのは、例えば地域の方のお声ですとか、ＳＮＳでかなりこの橋梁が取り上げられているよとか、写真が使われているとか、何かそういった効果のほうが分かれば、教えていただけますでしょうか。","respondent":"関根河川下水道課長","answer":"今後ライトアップの構想を策定していく中で、例えば効果的な広報ですとか、あるいはそういったところも含めて検討をしていきたいとは考えておりますので、その中で、例えば一定そうしたお声を聞いたりですとか集約するなど、そういったことはしてまいりたいと考えています。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"やはり、これだけの予算を使うことですから、まちづくり、活性化、観光も含めて重要だとは思いますが、そういった効果の検証が分かるような取組も要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"非常に良いことなので、これを契機に進めていただきたい。それも護岸をきちんと整えられるのかということがあるではないですか。それから考えると、立会川の高潮護岸を造るというか今より高くしようという話はないわけではないですか。計画としてはその遊歩道化をしようかということになっているわけですから、これも一気に行ければ、すごく良いチャンスのときが来るのだろうなと思っている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"この１番目の「まもる」のルールやマナーの周知徹底を図るというところ。今度４月に新たな法改正がされるということで、この中にも新たな法改正等の広報・啓発と書かれています。この広報・啓発というのはどのようにされていくのか。やはりこのルールを守ってもらう、浸透させていくというところが重要だと考えますが、区としてはどういうことをやってきて、またやっていくのか、伺いたいと思います。","respondent":"山下交通安全担当課長","answer":"ほかの方法といたしましては、先日しながわ中央公園でも行いましたが、スケアードストレート教室ですとか、あと警察と連携してのキャンペーン、またもろもろの交通安全教室を今後も実施していく予定です。２月１日号の広報しながわにも法改正の趣旨について載せる予定です。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"取り組まれてはきているということですけれども、実際町を走っていると、自分は関係ないと思っているのではないかと思うような方も本当に多いので、ぜひ浸透させていただきたいと思っています。１４.４％なので、今、私が申し上げたようなこともきっとあるのだろうなとは思うのですけれども、これの中身をもう少し教えていただきたいのです。区としてはどう考えているのかを伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"自転車空間整備延長で、令和１５年度までに５９.３ｋｍの整備を目指して道路課と連携しながら、なるべく早く進められるように様々取り組んでいければとは思っております。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"何とか危険を回避しながらこちらも運転しているのですけれど、そういったところでは、回避できるものなのか伺いたい。さっきも言ったのですけれども、何かここに来ると何のレーンもないというふうになると、車道を走りますけれども、やはり車側の認識が自転車レーンがあるというのとではまた違ってくるので、そういったところが都道と国道の関係でスムーズにいくのか、そこを伺いたいと思います。","respondent":"山下交通安全担当課長、櫻木地域交通政策課長","answer":"特に大通りですと、補助２６号線などに停まっている車の中には荷待ちというか運転手が乗っていて時間調整をしているだとか、そういった方もいらっしゃいますので、そこにつきましては警察と連携して。逆に言うと国道・都道もこれから進めていく部分もあろうかと思いますので、そこは連携を取りながらしっかりやっていくと考えております。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。ブルーレーンですね。ナビマークだと、先ほども言ったように結構追いやられるので、自転車レーンであると自転車も安心かなと思いますので、そこは要望したいと思います。端を走る皆さんが多いので、目の前にきゅっと入ってくるときもあって、電動キックボードもここを走るものなのかなと感じてはいたのですけれども、そこはルールとして、明確に決まっているのでしょうか。","respondent":"山下交通安全担当課長","answer":"電動キックボード、モペット、こちらは原動機付自転車扱いになりますので、基本的には自転車レーンは走行できないことになりまして、車道の左側端を走るということになっております。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと「とめる」のところで、買物時の短時間駐輪スペースの確保、重点施策ということで黄色で塗られています。進んでいる部分もあると思うのですけれども、この駐輪スペースというのは、駐輪場を確保するということなのでしょうか。これは全区でしょうから、各足りないと言われている大井町や西大井、五反田それぞれの地区で何％みたいな、そういう個別の目標というのはあったりするのか伺いたいと思います。","respondent":"山下交通安全担当課長、櫻木地域交通政策課長","answer":"そのような中で、区としましても駐輪場の整備、また確保に向けて様々な努力をしてきているところでございまして、西大井駅につきましては、委員会等でもご報告していますが。一応区の方針としてはそういう形で支援を進めていきたいです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"駐輪場については様々工夫等もしていただいて、増やしていく方向でやられているということで、そうですね。これは満足度でしたね。そこは商店街とも話はされているのでしょうけれども、区のほうがもう少し積極的に場所の確保や、こういう計画も出して減らしていこうと言っているわけですから、ぜひ区のほうからのアプローチをもっと強めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"藤原委員","kind":"確認","question":"基本中の基本をお伺いしたいと思います。は歩行者の安全といいますか、いろいろな施策が出てくるのですけれども、歩行者はいわゆる交通弱者ですから、歩行者の安全が一番だと考えていてよろしいのですよねという確認です。","respondent":"山下交通安全担当課長","answer":"歩道につきましては歩行者第一ですし、自転車が通行することができる場合であっても、必ず歩行者の安全を確保した上で走行してくださいということでお願いしておりますので、そちらについてもしっかりと啓発をしていきたいと考えています。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"歩道を走るときは必ず押してくださいねとか、例えば商店街等は、よく商店街の中では自転車を押してくださいねとなりますけれども、歩道を自転車でという時も押してくださいとはなっていないわけではないですか。その辺についての広報、自転車でも反則金を払うのですよという広報を、もう出前講座でも良いので徹底していっていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"山下交通安全担当課長","answer":"免許がなくても気軽に使えるというのが自転車です。利用を控えるのではなくて、利用するなら安全に乗るというところで、しっかりそういった年代に応じた安全講習ですとかキャンペーン等ができればと考えていますので、今後とも引き続き実施してまいります。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、最後にもう一つだけ、ちょっと細かいお話を伺いたいのですけれども、車の運転で違反等をしたら、免許の確認をして切符を切られますよね。けれども自転車の場合は、具体的にそういう違反をしたときに、その反則金と私も伺ってお話の中で出てきますけれども、どうどういう形で、切符とか切るのですか。そういう場合は、具体的にその人であるという担保はどのように確認していくのでしょうか。","respondent":"山下交通安全担当課長","answer":"それも現場で持っていない、そういった方への対応について、今後の取締りにつきましては警察のほうから私も情報をいただいていないのですけれども、例えば連絡先を確認した上で後日出頭して、警察署のほうで確認をするですとか、ご自宅まで赴いて。","id":"exchange-018"},{"speaker":"えのした委員","kind":"質問・要望","question":"私も様々要望もさせていただきましたが、ご対応本当にありがとうあります。これはヒヤリ・ハットからそういうところを採集しているのかどうか分かりませんけれども、引き続きそういうところでやっていただけると効果が高いのかなとも実感をしております。ほかに何か具体策などがあればここに出てきているとは思うのですが、意気込みと、今後考えられることがあればお答え願えますでしょうか。","respondent":"山下交通安全担当課長","answer":"武蔵小山駅につきましては、大変申し訳ありません、土地の確保の事情でなかなか区営駐輪場の設置が、難しいところがあります。区内でも一番、撤去活動、指導啓発を積極的に力を入れて行っている地区です。","id":"exchange-019"},{"speaker":"えのした委員","kind":"質問・要望","question":"みずほ銀行前も拝見しておりますし、自転車は減っていると理解はしております。本当に感謝申し上げます。引き続き、もちろん武蔵小山駅近辺だけではないと思いますけれども、よろしくお願いいたします。ただ、あとあそこは歩道というかなんというか、パイロンになってしまうと、なかなかそこも難しい課題だとは思います。今後も引き続き対策を考えていただきたいと思います。これは要望です。","respondent":"大友公園課長","answer":"それでも行かない場合は巡回等を強化していますけれども、即時撤去はなかなか難しく、このような対応を取って、引き続き違法駐輪をなくしていきたいと考えているところです。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"電動キックボードというのは一応、２０ｋｍ／ｈの速度制限がある。自転車は一応速度制限はないみたいですね。そのような状況の中で、今度規制というか交通違反の青切符を切られるようになるのですが、そもそもスピード違反というのが、その取締りの対象となっているのかどうかというのを、最初に確認させていただきたいと思います。","respondent":"山下交通安全担当課長","answer":"それで自転車を取り締まることができるのかどうかという、実質的に難しいのかなと私の今の考え方だと思います。ただ、速度を超過すれば、それは違反になりますので、取締対象とはなりますけれども、その取締りをするかどうかというところは微妙なのかなです。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、なかなか、そういうスピード違反をすると違反になって切符を切られるよというのは、言えない感じになるのですかというのが一つ。あるいは何かしら区として、ナンバープレートを発行する所管でもあるので、そういうところの物理的な制限を行うみたいな、何かできることはあるのかというようなことについて、伺いたいと思います。","respondent":"山下交通安全担当課長","answer":"ただ、一般に販売されている、区に電動キックボードのナンバーを申請してくるような電動キックボードというのは、ちょっと管理が難しいといいますか、速度のリミッターを解除している方も中にはいるかもしれません。","id":"exchange-022"},{"speaker":"松本委員","kind":"意見","question":"これは多分ですが、まず令和２年の東京都の条例ができた段階で一回挙がっているかと思うのですけれども、残念ながら今回の目標だと、こちらの計画のほうの中身を見ていくと、在住区民アンケートなのでこの令和４年しかないということかと思うのですが、結構やはり経時的にこの推移というか、何かが起こったときにどうなっているのかというのを把握していくのはすごく大事なことだと思っていまして。","respondent":"櫻木地域交通政策課長","answer":"その電子申請のアンケートの話は、すみません、把握していないところですが、引き続き加入促進について、東京都の条例で義務化されているということもありますので、その辺りは周知に努めてまいりたいと考えています。","id":"exchange-023"},{"speaker":"松本委員","kind":"質問・要望","question":"なので、ひょっとすると私の確認不足で、実は載っていましたということはあるかもしれないのですけれども、周知を図るときにはぜひ、事故が起きたときに加害側がどのくらい大きな賠償責任を負わないといけないのかというところをできるだけ強調していただいて、だから入らないと大変なことになるという脅しではないけれども、でもこれは本当に入ってもらわないとかなり大変なことになりますので。","respondent":"山下交通安全担当課長","answer":"今後また検討します。","id":"exchange-024"},{"speaker":"松本委員","kind":"質問・要望","question":"最後に、要望です。すみません、令和５年まではあったということで、私のほうの間違いでした。失礼しました。まさにその保険の募集の時とかも含めてですけれども、あと本当に交通安全週間とかいろいろな場面で周知できる機会があると思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"ここがどうなのかということと、同様な視点から逆に言うと三田通りのほう、目黒、上大崎のほうは、ほかにもいっぱいあるのですけれども、例えばここを取ると、三田通りがＣに指定されていますが、自転車というのはやはり連続性があるので、品川区に入るとちゃんと整備されているけれども、目黒区はそうではないといったらまたこの周辺でも混乱するし、その逆もあると思うのですが。","respondent":"櫻木地域交通政策課長、森道路課長","answer":"最初に、付け方の考え方ですが、基本的にこの優先度ＡとかＢ、Ｃというのは、平たく言うとニーズがあるところと、安全性に配慮しなくてはいけないというところで、ニーズがあってかつ安全性にも問題があるので。区境の外にも黄色い線が幾つか引いてあると思うのですけれども、これがその当時の各区のネットワーク路線ということで、ここへつなげるような路線も大変重要だということで、ネットワークに位置づけをさせていただいたです。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"都道ですが、補助２６号線のことはどうなのかということ。商店街との関係性で言うと、やはり冒頭の藤原委員のお話にあったように、歩行者最優先でやるべきですので、こここそしっかり周知をぜひお願いしたい。これは個別の意見として言いますが、その補助２６号線の関係と、安全性の視点のもう一度確認と、商店街の歩行者周知という視点でもう一度お願いします。","respondent":"櫻木地域交通政策課長","answer":"このネットワークを作られたのがコロナ禍にかかるような時期でもございましたので、こちらも次の見直しのタイミングでまた新たな交通状況を踏まえて再検討することになるかと考えています。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"最後にごめんなさい。１件だけ。商店街には特に歩行者天国というか車両通行止めの時間がありまして、そこは特に車を意識せずお買物を楽しむ方がたくさんいらっしゃいますよね。自転車は今の時点では普通に走って良いわけです。ここの優先度を高くするという意味で、指定する以上はその指定する側が安全対策をしっかり講じるべきだと思いますので、そこは徹底していただきたいと思います。","respondent":"山下交通安全担当課長","answer":"モペットが原動機付自転車扱いとなって走行はできないというところで、すみません、答弁を訂正させていただきたいと思います。大変申し訳ありませんでした。","id":"exchange-028"}]},{"id":"topic-02","title":"京浜急行バス株式会社のバス路線における系統廃止","agenda":"京浜急行バス株式会社のバス路線における系統廃止","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"」という声があがっています。このまま乗務員不足で減便減便、廃止廃止と、もしなっていった場合、本当に区民の移動の権利に大きく影響すると思っているので、全体でどれぐらいが廃止、そして減便、そして減便廃止になりそうだとか、そういう部分を調査・把握していただいて、改善に向けて区としても求めていくというようなことをぜひしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"櫻木地域交通政策課長","answer":"全体の減便を把握していくというところにおきましては、この減便とか路線の廃止は非常に各企業の高度な経営情報ですので、なかなか事前に把握するということは難しいところではありますが、区としましては情報をいただいた時点で。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これまでも求めてきた結果として、やはりこういう判断がされると。競合しないわけですから、もう走らせていただきたい。やはり移動の権利を確保していくことで、区としてできることといったら、そうやって改善を求めていっていただいた上で、やはり区として実施する、走らせるという、それはできないのか伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"今後、交通サービス圏域外が一定解消のめどがついたタイミングで、また区全体の観点からどのようなことが品川区の地域交通に必要なのかということを再度改めて整理した上で、今後の取組方針を固めていくようなタイミングが来ようかと考えています。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"交渉はぜひ強い姿勢で進めていっていただきたいのですが、それがかなわないときは、やはり区として考えていくべきではないかと思いますので、コミュニティバス等の検討をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"地元の声としてぜひ前向きに受け止めていただきたい。それとこれは要望ですけれども、その前段の品川・勝島地区の再開発といいますかまちづくりビジョンがありますので、そういった方面を踏まえた新路線というものも考えていただきたい。新たな路線を整備するということも含め、地域の声として前向きに受け止めていただき、またそれが実現されることを強く期待をして発言を終わらせたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"将来この路線の復活みたいなこととかはあるのかどうかということ。需要の回復とか減少とか、需要と言っているのはこの路線に限ってのことなのか。京浜急行バス全体として、品川区内をいろいろ走っている中で、全体としても新型コロナウイルスの流行以来減少していて、収益が会社全体として厳しいのでどこかをリストラしなくてはいけないという話の中で出てきたこの路線廃止なのかというのを教えてください。","respondent":"櫻木地域交通政策課長","answer":"１点目の需要回復の遅れのニュアンスということです。こちらの廃止理由につきましては、京浜急行バスが示しているオフィシャルな公式の理由をそのまま転記させていただいているものですので、私どもの解釈というよりは公式発表です。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"どこかに別の交通手段があって、このコロナウイルスの流行期間で乗り換えてしまったみたいな、そういう分析なのでしょうか。なぜ需要が回復しないでコロナが明けてから減少してしまったのか。いろいろと、経済が回復しているではないですか。どうしてかということがちょっと気になるのですけれども、何か分かっていることがあれば、教えてください。","respondent":"櫻木地域交通政策課長","answer":"ちょっとそこの細かな動向分析については把握しておりませんが、結果として、最初のコロナ前には戻っていないという状況をこのような形で表現されているという認識です。","id":"exchange-034"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。そうするとここに路線がなくなったりすると。そうすると、そこで公共交通をしっかり自治体としてどう維持していくかという話がやはり必要な議論として出てくる、検討されてくるのかな、そういう流れも今後出てくるのかなというか、そのようにしていくべきでもあろうと思うのですけれども、その辺の今後の見通しをお知らせください。","respondent":"櫻木地域交通政策課長","answer":"様々な地域の様々なご要望の状況を踏まえて、どのような品川区の交通政策をつくっていくかを検討していくものと考えております。","id":"exchange-035"},{"speaker":"塚本委員","kind":"意見","question":"多分、大井町から大森までは、一応電車が通っているので、大森に行く人たちは多分最初からバスに乗っていないと思うのです。そういう意味から考えると、今の規定で言うと交通空白地帯になるか、ならないかというのは一定の議論の土台にはなってくるのかなと思うのですが、様々環境も変わってくるので、ぜひ前向きな検討というか、みんなの地域の公共交通ということでの検討というのはお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"それはどういうことかと言うと、昭和３５年からずっとあって、この大井町を通る京浜急行バスはこの一つなのに、既得権益があるのに、これを手放したわけです。５０人ぐらい辞めるのに５人しか入らないと。この路線はなくなるのですから。けれども、それは一つの既得権益ぐらいをくださいよと、コミュニティバスはそこを強く言ってほしいと思っているけれども、どうですか。","respondent":"櫻木地域交通政策課長","answer":"副委員長がおっしゃられた状況も含めて、区としてもいすゞ病院や桜新道というところについては様々強い申入れをして、交渉していますので現時点では言うことは難しいのですが、区としても皆様の思いを強く交渉していく所存です。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/379605?Template=document&Id=7305#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":35952,"voices":87}},{"id":"r08-20260122-10","meetingId":"r08-m01","date":"2026年1月22日","dateIso":"2026-01-22","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579932?Template=document&Id=7307#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":2826,"voices":22}},{"id":"r08-20260217-10","meetingId":"r08-1t","date":"2026年2月17日","dateIso":"2026-02-17","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件抜き出しています。","topics":[{"id":"topic-01","title":"令和８年第１回定例会","agenda":"令和８年第１回定例会","exchanges":[{"speaker":"まつざわ委員長","kind":"提案","question":"この後、議事日程を確認しますが、まず、第４４号議案については、本会議３日目、２月２０日での上程の後、２４日の総務委員会で審査を行います。追加で提案される予定の議案につきましては、明日午後０時４５分から、追加で議会運営委員会を開催し、内容について理事者にご説明いただくことになりますので、ご予定いただきたいと思います。以上で、本件を終了いたします。","respondent":"大澤区議会事務局長","answer":"資料No.１をご覧ください。第１回定例会１日目は２月１８日午後１時開議です。日程第１、会期の決定について、２月１８日から３月２７日までの３８日間といたします。次に、区長より施政方針の説明があり、日程第２、一般質問、代表質問からとなります。","id":"exchange-001"}]},{"id":"topic-02","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"共産党としては、今年も区長の予算編成権を侵さない範囲で、予算修正案を提案したいと考えています。提案の時期なのですが、各会派、議員の皆さんが検討できる時間を取れるようなタイミングで提案させていただきたいと思っています。実際の審議は最終日になるかと思うのですけれども、その際はぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-03","title":"広報会議からの報告事項","agenda":"広報会議からの報告事項","exchanges":[{"speaker":"せお委員","kind":"質問・要望","question":"大きく４つあります。１つ目、特集記事の新設です。２つ目、編集方針の改訂です。令和６年に実施した区議会だよりのアンケートにおいて、複数の回答者様から、区議会だよりの紙が良過ぎるといった、紙質の見直しを求めるご意見がありましたので、こうしたご意見を基に、広報会議で検討を重ねて、フリーペーパーのような、手に取りやすく親しみやすい紙質となるように変更することとなりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"最後のところの、紙質が良過ぎるということに対して、フリーペーパーのような、親しみやすいというお話があったのですけれど、これは、予算的にも抑えられるということなのでしょうか。その辺りを教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"意見","question":"紙質が良過ぎるというのは、恐らく、その裏には予算をかけ過ぎではないのかという区民の意見があると思うので、きちんと、紙質も変わって、予算も下がりますという説明がこれからできればなと。承知いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、議会事務局の職員が１名増ということで、大変いいことだと思うのです。調査係ということでしたけれども、なぜなのかというのと、ほかの係では欠員というか足りていないということはないのか、その辺も併せて伺いたいと思います。","respondent":"大澤区議会事務局長","answer":"新規事業に関しましては、子ども向けのパンフレットは現在もあります。内容的に大きく変更する予定はありませんけれども、より、児童・生徒が手に取りたくなるようなパンフレットに変えていこうという方向性です。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579932?Template=document&Id=7309#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":9290,"voices":43}},{"id":"r08-20260218-10","meetingId":"r08-1t","date":"2026年2月18日","dateIso":"2026-02-18","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579932?Template=document&Id=7311#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":1562,"voices":12}},{"id":"r08-20260220-3","meetingId":"r08-yosan","date":"2026年2月20日","dateIso":"2026-02-20","committee":"予算特別委員会","time":"午前１１時５５分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/361190?Template=document&Id=7377#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":1994,"voices":16}},{"id":"r08-20260224-6","meetingId":"r08-1t","date":"2026年2月24日","dateIso":"2026-02-24","committee":"区民委員会","time":"午前１０時００分～午前１０時５７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"令和８年陳情第９号、インボイス制度による事業者への影響の実態調査を品川区独自で行う陳情","agenda":"令和８年陳情第９号、インボイス制度による事業者への影響の実態調査を品川区独自で行う陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"中小企業庁が国として調査を今、やり直しといいますか、前回ひどい調査だったので、今回仕切り直しの調査になっていると思いますが、どちらが今請け負っていらっしゃるのでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今回の調査については、東京商工リサーチが受託したと報道で把握しております。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"そうしますと、東京商工リサーチは区がリーチできない情報をお持ちで、区内事業者でも、区がつながれないところの声は幅広く拾えている感じなのでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"国の調査ですので、細かい手法については、区で関知していないところです。ただ、国は個人事業主ですとか、法人ですとか、課税情報、免税情報を持ち合わせているので、受託事業者とどのように連携を取っているかというのは、そこについては何とも言えないところです。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"そろそろ公開ということで、９月に２割特例が切れますので、それも踏まえて、それまでに間に合うように公開されるのかなと思うのですが、９月から２割から３割に変わって、事業者は実際、負担が増えてしまうと思うのですけれども、区としては何か今後の方針などというのはあるのでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"それ以外に、国や都が引き続きいろいろな施策を出してきていますので、そちらの利用状況ですとか、それを事業者の方に案内するとか、そういったことは丁寧にやっていきたいと考えています。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"意見","question":"全体の情報を区として取れない以上は、区でできることというのは限りがあるのかなとは思いますが、つながれば、相談に乗ったり、伴走したりはされているという話は聞いていますので、より広くいろいろな事業者につながるように広報していただいて、景況調査等も含めて、また負担が増える時期になるので、何らかの対策等もまた考えていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"こしば委員","kind":"質問","question":"昨年の秋に同じような趣旨の請願の審査がありまして、その際に課長の説明で、１２月に創業支援センターで個人事業主等に向けたインボイスの説明会を行うというところを聞いておりまして、その振り返り、参加者の特性だとか、人数だとか、反応など、分かる範囲で教えていただければと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ＳＨＩＰで行うセミナー全般として、ＡＩですとか、営業に関することというのは割と集客がしやすくて、こういったインボイスですとか、オフィスに関することというのはなかなか集客に苦労するところではあるのですけれども、そういったところで。","id":"exchange-005"},{"speaker":"こしば委員","kind":"質問","question":"その際に、インボイス制度そのものについて、問合せだとか、意見とか、そういったものは出てこなかったという認識でよろしいですか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"インボイス制度そのものに関するご意見だとかお問合せというのは、なかったと聞いております。","id":"exchange-006"},{"speaker":"こしば委員","kind":"質問・要望","question":"結論を出すでお願いします。そういったことも踏まえまして、これまでも私のほうで意見表明のときに話をさせていただいたとおりなのですけれども、基本的な情報は国でも多分、つかむことはなかなか難しいところでもあるかなと思います。そういったことも踏まえまして、今回の陳情に関しては、願意に沿い難く、不採択とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日決めるで、会派としての結論は、不採択です。国の制度ですので、制度自体を区でというのはなかなか難しいと思うのですが、国の調査も、きちんと実態を知るためにやっていると思いますので、今回結果を見て、国も政策として何らかやっていただきたいですし、２割から３割に特例割合が変わってしまうので、区でもできること、何か支援などを考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日結論を出すでお願いしたいと思います。１１月にも同じような請願が出ていたと伺っております。ですので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日結論を出すでお願いしたいと思います。そのため、維新としては、区としてできる支援や実態把握は行うべきという立場から、過去にはこの請願・陳情に賛成してきた経緯があります。今後も必要に応じて改善は求めていくと思いますが、現時点において改めて独自調査を求める今回の陳情については、維新としては不採択と判断いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"本日結論を出すでお願いします。先ほど課長からも説明があったとおり、今、国がまとめているという中で、この結果を分析した後にこういったことをやるというのはいいと思うのですが、現段階では、調査を国がやっているところだから、何も区としてはできないというのはすごく分かります。なので、やはりこれは今、結果を分析してからいろいろ検討していただきたいということで、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"令和７年国勢調査","agenda":"令和７年国勢調査","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"少し様子を伺いたいのですけれども、毎回この国勢調査のときに、調査員の方が訪問をし、手渡しあるいは接触をするというところのご苦労のお話がよく出ますが、今回はどんな状況だったでしょうか。この２点を教えてください。","respondent":"平原地域活動課長","answer":"委員ご指摘のとおり、接触については苦労があるということは毎回聞いているところですけれども、前回の令和２年の国勢調査の時点で、その課題が強く認識されまして、若干緩和がされて、一例ですけれども、２回接触を試みてお留守だったときには投函でよいとか。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"モデル実施なのでしょうか、実証実験されたのでしょうか、全郵送といったところを今後すれば、もっとこうした調査への人手確保といったところも、区としても緩和できるのかなと、今のお話を聞いていて思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"こしば委員","kind":"質問","question":"１人で複数区、３区４区持っている方もいますし、そういう中で、また５年後、国勢調査をするに当たって、今、町会・自治会の役員がどんどん減ってきている中で、このままいくと多分、推薦者の数というのはなかなか確保することが困難になってくると思うのですけれども、今回は公募などというのが６２人おりましたが、この公募などというのは、ある程度枠が決まっているものなのか。","respondent":"平原地域活動課長","answer":"町会・自治会からご推薦いただいているといったところの問題点は、こちらでも把握していますが、やはり地域という点では、町会・自治会からご推薦いただく方が一番地域をお知りになっているということと、個人情報に携わっていくという中では。","id":"exchange-014"},{"speaker":"こしば委員","kind":"質問","question":"町会・自治会でも、高齢化が進んでくることで、実際に歩いて回るわけですから、大変困難なところもあるかもしれないですけれども、その一方で、町会・自治会から、逆に会員以外の方にも、声かけができるのだよとか、そういったものを区から発信していただくことで、町会・自治会の一つの活性化につながるかどうか分かりませんけれども、そのつながりが広がってくることは確かだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"けれども、これから結構高齢者が多い、なかなか成り手という部分でいうと、２０１の町会・自治会も本当に皆さんご苦労している中で、選出していただいてやっていただくというのは、本当にいろいろご苦労もあるかと思いますので、これは感謝申し上げたいと思います。資料にマンション管理人、施設管理者と記載がありますが、タワーマンションの方たちの取扱いを改めてお聞きしたいと思います。","respondent":"平原地域活動課長","answer":"先ほど言いました接触困難で居住確認が困難なときには、接触しないでそのまま投函ということもできますので、そういう軽減措置などを取りながらやっていくという形になりますが、いずれにしましても、まずは管理会社。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"あえて私が今、タワーマンションと申し上げたというのは、先ほど国の調査を試験的にやっているというご説明がありました。タワーマンションの居住者に限定した調査も、国はやっているのです。なので、ぜひ、これは区には求められないことなのだけれども、その調査結果を踏まえて、いろいろ今後も検討していただきたいと思います。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-03","title":"品川ソーシャルイノベーションアクセラレーター デモデイの開催","agenda":"品川ソーシャルイノベーションアクセラレーター デモデイの開催","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"すみません、私もこうしたことが開催されているということは、今回の区民委員会で知ったわけなのですけれども、この事業実施の経緯、背景、こういうものが必要だ、こういうものをやっていこう、スタートアップで必要だという背景を、参考までに伺いたいといったところ、２点目が、３２社応募があって、選定されて２０社といったところで、この２０社の根拠はどうなのかというところと、３点目が。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"そういったところで、情報通信業でスタートアップを目指す方に特化した支援が必要なのではないかといったところで、令和２年度にこのプログラムを実施させていただいたところです。２点目、２０社選定の根拠です。１点目は、きめ細かいメンタリングを用意しております。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"非常に大事だと思います。いかがでしょうか。２０社といったところは、無制限にするというのはなかなか難しいのと、座学でのところも、交流会というところも、小単位で交流をするというのは非常に意見も出しやすいし、といったところを考えると、一定の人数の制限はあるでしょうけれども、こうしたところで企業数は分かりました。その２点を、何か感想なり、現状を教えていただきたいです。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"さっき申し上げた３施設の入居も、ご検討くださいという形でご案内しています。","id":"exchange-019"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"確認ですが、事前申込みということは、定員などがあるのでしょうか。その辺りを伺いたいと思います。","respondent":"守屋スポーツ推進課長","answer":"大変細かくて申し訳ないですが、チラシの２ページ目のところに、事前申込み制のところは青く記載されております。ここに定員数を書かせていただいておりまして、教室形式ですので、人数自体は小規模なものから若干多いものまで、千差万別という形になっております。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/565411?Template=document&Id=7319#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":17798,"voices":65}},{"id":"r08-20260224-7","meetingId":"r08-1t","date":"2026年2月24日","dateIso":"2026-02-24","committee":"厚生委員会","time":"午前１０時００分～午後 ４時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を104件抜き出しています。","topics":[{"id":"topic-01","title":"福祉施設関係条例の改正等（4議案）","agenda":"福祉施設関係条例の改正等（4議案）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"例えば施設２のところの特別養護老人ホームの７７床とショートステイ１１床で８８床ということですけれども、ここの総事業費と補助金などが分かったら教えていただきたいということと、また施設１、施設２、施設３というようなことでありますが、この施設ごとに、もし建設費と補助金が分かったら教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"高齢者施設の５６億円というものは、特別養護老人ホームから、認知症高齢者グループホームから、地域密着型多機能ホーム、全部合わせた、大体施設１と施設２を合わせたものが５６億円ということになるのでしょうか。そのうちの特別養護老人ホームの定員８８名のところでの総事業費などというものはなかなか出るのは難しいのか、その辺のところが分かったらお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"障害福祉関係条例の改正等（3議案）","agenda":"障害福祉関係条例の改正等（3議案）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これは総合支援法と児童福祉法の改定による条ずれの整備ということだと思うのですけれども、この中に総合支援法に就労選択支援が創設されたということも書かれているのですが、この就労選択支援が創設された背景と、具体的にどう変わるのか、このサービスの対象や支援の中身についてお聞かせいただきたいと思います。","respondent":"松山障害者支援課長","answer":"就労継続支援Ｂ型については令和７年の１０月以降から、Ａ型については令和９年の４月以降からと段階的に設定されております。内容についてですが、作業場面を活用したアセスメント、アセスメントシートの作成、多機関連携によるケース会議、事業者調整となっております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"区内でこの就労選択支援の登録事業者というものがあるのかどうなのかということと、厚生労働省の就労選択支援実施マニュアルというものをちょっと見たのですけれども、ここにはその対象としては、就労選択支援の対象は、就労移行支援または就労継続支援を利用する意向の者および利用している者というようなことであったのですが、そして新たに就労継続支援Ｂ型を利用する意向のある場合は。","respondent":"松山障害者支援課長","answer":"国の就労選択支援のマニュアルのとおりに進める予定です。今後の方向性については、地域自立支援協議会就労支援部会で講師を招いて就労選択支援について研修を行いましたので、区内の事業所、ニーズに応じて対応できるところが指定を受けていただければと考えています。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"そして事業者も決まったということなのですけれども、それに伴ういろいろな人員のことなどは今後ということなのでしょうか。その辺についての今後の、段々スキルアップなど、そのようなことは併せて考えておくべきだと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"松山障害者支援課長","answer":"期間としては、１か月間のサービス提供です。就労アセスメントにつきましては、これまでは統一されている手法ではなかったということで、今回国のほうで統一して養成研修を行い、その上で特化したサービスとして切り出したです。今後もニーズに合わせて対応してまいります。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"どこまで言ってしまっていいのか、少し迷うところなのですけれども、この法人、結構人員など大変だというようには、そして割といろいろなことを受託、受託でいいのかな、受託しておられますよね。その辺について、今後ということだと思いますけれども、区としての支援というか、そのようなものも必要だと思うのですが、その辺については具体的にはどのように進められるのか教えていただければと思います。","respondent":"松山障害者支援課長","answer":"事業者支援についてです。就労選択支援は委託ではなく、民間事業者として指定を取っているものです。したがいまして、区としましては、地域自立支援協議会就労支援部会などの課題検討、協議を含めて、その中で対応してまいりたいと考えています。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。お仕事のミスマッチというものは、個別的に、きちんと相談支援も受けているのだけれども、やはり現実としてそのようなミスマッチが起きてしまっているということは伺いますし、この事業者としても新たなスキルが必要になるということなので、それぞれの事業者がやることとはいっても、ぜひ今後、区としても適切な支援は考えていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"非常にこういった制度、いい制度だと思うのですけれども、ちょっと確認なのですが、この就労選択支援を利用される方には自己負担が発生するのか、もし発生するなら費用はどれぐらいなのかということが分かれば教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"費用負担についてのお尋ねです。就労選択支援サービスは総合支援法のサービスですので、利用者負担は１割となっております。","id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認ですけれども、収入があれば１割ということでよろしいですか。","respondent":"松山障害者支援課長","answer":"障害者総合支援法は国の全体のサービスですので、収入に応じてということになります。","id":"exchange-009"}]},{"id":"topic-03","title":"第３１号議案、品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第３１号議案、品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"だから、それに連動して下げないというものが今回のこの条例だと思います。年金の人のほうが非課税になる年金の年額の総収入というものが多いわけですから、そこに若干近づいても、まだ年金の人まではいかないというようなことなので、その人を非課税にして介護保険料を引き下げていくということのほうが平等になるのではないかという気がするのですけれども、その辺の考え方についても伺えたらと思います。","respondent":"菅野高齢者福祉課長","answer":"そうしますと、区では大体８万２,０００人の方が６５歳以上の方なので、８００人ちょっとかなというように、国の推計に当てはめると算出できるわけですけれども、では具体的にどういった方がという人数を出すということになりますと、給与所得と。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それともう一つ、これは今年度に限っての対応ということで、厚生労働省の政令で出されているということなので従わざるを得ないということではあるのですけれども、来年度からは介護保険料が第１０期ということで変わるわけですが、そこに対しての今回の税制改正の影響の反映というものはどのようなことになっていくのかについても伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"初めに聞いたことでご答弁あったのか、ちょっと聞き逃したのかもしれないのですけれども、年金よりも給与所得の方のほうが非課税の額というものが低いではないですか。そのようなことからすると、１０万円上がって１１０万円になるということのほうが、年金の人に近づけるというところで公平性にもなるのかなと思うのですけれども、その点はいかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"そちらにつきましては、税の部分では確かに今回１０万円上がることによって、委員おっしゃるとおりでしたら公平性を保つことになるのかなというところなのですが、今回のこの介護保険料の条例改正につきましては、そういった税の負担の調整とはまた別物で。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"意見","question":"厚生労働省が政令で出しているというようなことなので、区独自にやることはなかなか難しいということは分かるのですけれども、今回本当に手取りを増やすというようなことでの税制改正で、もともと本来であれば非課税になっていていい人や、減額になってもいい、減額になるべき人が減額になってもそれが反映されないという、そのようなことに、今回これ連動させないというような対応をしたわけですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-04","title":"第３２号議案、品川区立高齢者住宅条例の一部を改正する条例","agenda":"第３２号議案、品川区立高齢者住宅条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それ以外の方で、例えば住民税非課税の方というものは、最低額の３万円ということで考えていいのか、それから、実際居住している方の中で減免制度を受けている方の割合というものは、このアツミマンションでどれくらいいるのかということか、または全体でもどれぐらいなのかということでもいいのですけれども、減免制度を受けている方の割合というものもお聞かせいただきたいということと。","respondent":"樫村高齢者地域支援課長","answer":"７万２,０００円から７万８,０００円への増となった根拠といったところですけれども、まずは区のほうで実施しております家賃市場調査、これを昨年、令和７年９月に実施しておりまして、こちらのほうで。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"高齢者住宅が２００人ちょっと分あると思うのですけれども、その中でそれぞれの最高額が決められていますが、最高額を払っている方というものはいらっしゃるのか、最高額の収入というものはどれくらいになるのか、今のところでは最高額の収入が幾らかということはなかったかと思うのですけれども、最高額の収入の方が幾らかということと。","respondent":"樫村高齢者地域支援課長","answer":"２１９戸ありますけれども、皆さん減額の適用になっておりますので、減額をせずに最高額をお支払いしている方というものは現在いらっしゃいません。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、家主として、何というのですか、維持するということもすごくお金がかかることですし、そのような点では必要なところかなと思うのですけれども、今回６,０００円の値上げとなりますが、その居住者の値上げになる方というものはいないということで考えていいのか、その６,０００円というものが、区が負担をするということで考えていいのか、その点を確認させてください。","respondent":"樫村高齢者地域支援課長","answer":"この６,０００円分の値上げにつきましては区が負担をするといったところでございまして、今の居住者に関しては影響を受ける方がいらっしゃらないということになりますが、もし、この減額適用を受けずに居住する方が今後出てくる場合には。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"詳しくはちょっと、この条例の改正とは異なるのであまり言いませんけれども、駐輪場がないとか、管理人を置いているけれども日中いないとか、そういったところでの課題があるというように、私どもの会派の議員が関わっているというところもありまして、今回の改定については特に問題はないと思うのですが、その辺りについて、ぜひ高齢者住宅自体の管理は。","respondent":"樫村高齢者地域支援課長","answer":"かつ、今は違うのですけれども、かつては管理人のほうも一緒に勤めていただいていたといったところでございまして、居住者の方からそういったご要望や、いわゆる苦情のようなものが、今でも家主のほうに行ってしまうということは区としても把握しておりますので。","id":"exchange-017"}]},{"id":"topic-05","title":"第３３号議案、品川区後期高齢者医療に関する条例の一部を改正する条例","agenda":"第３３号議案、品川区後期高齢者医療に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"現状では、掲示板に公示送達をされていると思うのですけれども、その件数というものは年間何件くらいあるのか、そこの中身、還付金とか、過誤納金とか、納入通知、督促ですか、そのようなものごとに何件ぐらいあるのかということが分かったら教えていただきたいと思います。","respondent":"山下国保医療年金課長","answer":"最後にございました、公示をされている期間ですけれども、内容によりましてちょっと異なるところかと思うのですが、数週間から１か月程度というところで把握をしています。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"後期高齢者が気づくという人がまずいないのではないかなという思いがするのですけれども、その辺の効果というものはどう考えているのかということと、それからインターネットに、何というのですか、名前が公開されるわけです。これは世界中の不特定多数の目に触れることになるわけですけれども、プライバシーの侵害ということに対してはどう考えるのか、その点についても伺いたいと思います。","respondent":"山下国保医療年金課長","answer":"実際に何週間、何か月ホームページのほうに登載をしていくかというところについては、今後関係所管等と検討を進めて、実際に運用を開始してまいりたいと考えています。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから督促状なども送られていくと思うのですが、３０件とか、４０件とかあった中での督促状の割合というものはどれくらいなのかということを伺いたいということと、督促状のインターネットに公開という形で公示送達されたことで、次に区としての対応というものがどのように進んでいくということになるのか、そこのところをお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから差押えもないとは言えないけれども、もう本当に複数ということでもないというようなことなので、本当にまれだというようなことなのだと思うのですが、そのようなことでは、何というのですか、以前からのそのような高齢者の命を守るというところでの対応がされているというところは確認できてよかったと思いますし、差押えというものは、何件でもぜひやめていただきたいというようなことは。","respondent":"山下国保医療年金課長","answer":"例えば還付の充当についてご通知差し上げるときに、送達が相手方に届いていないということでは、充当ができますよということをご案内しておりますので、今後は折り返しのご連絡何かしらいただければ充当の手続をご案内することができますし、還付につきましても。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"意見","question":"そのようなものは本人にとってもメリットなので、すごくプラスの部分だと思うのですけれども、督促など、そのようなところで進むことというものは何かあるのか、その点もお聞かせいただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは分かっているのだけれども、だから今までのところでの公示送達の中で、公示送達をすることで督促状を出したことの、その次に何か進むことというものはないのかということだけをちょっと、確認をさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"確認","question":"すみません。もう１回確認なのですけれども、今までの公示送達は、区役所の掲示板にその督促なり、過誤納金なり、還付なりの種類もきちんと載って、返納されてきてしまって、一応住所はあって、名前があって、そういったものを貼っていた。今回のインターネットでの公示というものは、種類も掲示しないし、住所も掲示しない、名前を掲示する、このような認識でいいのでしょうか。","respondent":"山下国保医療年金課長","answer":"分かりづらい説明になりまして申し訳ございませんでした。従前は、送達すべき書類の名称ということで、還付金通知書でしたらそういった形で、今委員からあったように掲示をしていたところです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"先ほども質疑あって、ちょっと聞き漏らしたのかもしれないのですが、効果、見る手段が増えて、だから知る人が増えるということなのでしょうけれども、どうも私には効果があまり、それだったら分かりやすくて、だからちょっとうっかりしていたような人は払いやすくなるよねというようなものにはならないような気がしていて、具体的に、どこかで効果測定などはされると思うのですが。","respondent":"山下国保医療年金課長","answer":"効果測定というものを何をもってするのかということはなかなか難しいところかなと思うのですけれども、やはり昨今の社会のデジタル化というところに追いつく中で、紙で掲示をしているだけですと、本当にこちらに足を運んでいただかないとご覧いただけないという状況が。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"私が全部開けて、私もこれほどいっぱいあると分からなくて、適当に、ではこれとこれ、これ払えばいいのだねと言ったら、今度、すみません、いただき過ぎました、返金いたしますので口座を教えてくださいということがあって、非常にご迷惑をかけた経験があって、ですから、その当事者の方に分かりやすくする必要性はすごい実感しているのですけれども、それが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"答えようがない。やってみなければ分からないということですか。","respondent":"山下国保医療年金課長","answer":"この公示送達の合理化という観点からも、区民の利便性、そして行政側の手続のほうの合理性というところから、双方の点から仕組みとして新たに導入するものですので。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"質問","question":"現時点で年間３０件から４０件ぐらい、区役所の掲示板に公示送達出しているということですけれども、実際、何だろう、直接本人から問合せが来るというものは年間どれぐらいの件数なのでしょうか。","respondent":"山下国保医療年金課長","answer":"いろいろなご照会、お問合せいただく中で手続に進んでまいりますので、その公示送達をもって、何人の方がその状況を把握されたかというところを把握しているものではございません。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そうなると、先ほど説明のときには一定の効果があると受け止めているというお話だったと思うのですけれども、それこそどうやってその効果をはかるかということは非常に難しいかなと思うのですが、その辺はいかがでしょうか。","respondent":"山下国保医療年金課長","answer":"先ほど別の委員のご質問にもご答弁申し上げましたとおり、その効果をはかるというところを数値化のような形で可視化することは大変難しいのかなと思ってありますけれども、紙で掲示をしていたものがインターネットでも閲覧できる。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"意見","question":"反対です。本当に後期高齢者医療のホームページに掲載しても、高齢者が気づくという人がなかなかいないのではないかなと。効果の面でどうかというようなこともありますし、名前を、やはり許可なく誰もが不特定多数の目に触れるというところから、やはりプライバシーの侵害に当たるのではないかというところで、反対ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"意見","question":"私は反対です。やはり効果が期待できないということと、氏名が載ってしまうというリスクをてんびんにかけたときに、やはりこの条例は適さないのではないかなと判断しました。反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]},{"id":"topic-06","title":"第４８号議案、指定管理者の指定","agenda":"第４８号議案、指定管理者の指定","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"委託料については、令和６年度は四億八千何百万円という感じだったと思うのですけれども、約５億円近い額となっていると思うのですが、この委託料というものは同じ程度でいくのか、その点についても、計画が出されているのかと思うのですけれども、伺えたらと思います。","respondent":"松山障害者支援課長","answer":"高い稼働率というお尋ねです。は報告書の選定予備委員会の中で議論されたところについて説明を申し上げます。報告書の５ページをご覧ください。","id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからあと４ページの選定の経過というところで、１のところで、事業者から申請書類や計画書類、それから施設運営計画など、いろいろ実績など出されていると思うのですけれども、本当はそのような資料も出していただけたら、私たちももっと詳しく中身を見ることができるのではないかということで、出していただきたいという要望を出しているところなのですが、そのような計画書などを見る中で。","respondent":"松山障害者支援課長","answer":"ぐるっぽとしての今後の提案についてです。短期入所では夜勤職員を３人配置し、障害の重度化に対応するとともに安全性に配慮する、医療・保健との連携を基に、重症心身障害児者や医療的ケアを必要とする身体障害者に対して受入体制の準備を進めていくです。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"確認","question":"もう一つ、８ページの上から３つ目の、日中一時支援の定員の拡大に伴う送迎対応は個別送迎を行う予定であるということで書かれているのですけれども、これは、何というのですか、ポイント送迎などではなくて、その人一人ひとりに合わせて、ドア・ツー・ドアというか、そこのところでの送迎ということで確認させていただいていいのか、ちょっとその点お願いします。","respondent":"松山障害者支援課長","answer":"日中一時支援の送迎についてです。現在も個別送迎を行っておりまして、日中一時支援の家族懇談会での施設長の例を出した発言から、不安になられた方がいらっしゃいますけれども、現実的には個別送迎を行っているです。その確認をさせていただいたものです。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"なかなか現実、実現しないのですけれども、財務についてのモニタリングというものはいつも、当然のことながら財務についてはしっかりモニタリングしてくださっていると思うのですが、やはりずっと私としてというか、生活者ネットワークとして要望を出しているものが、毎回でなくても、社会保険労務士を入れての労務についてのモニタリングということを、やはり働く人の立場でいうと。","respondent":"松山障害者支援課長","answer":"指定管理制度の中で、労働環境チェックは３年目に実施しております。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"社会保険労務士を入れてのチェックという理解でよろしいでしょうかということが１つと、それから、なぜこれをしつこく言うかというと、やはり送迎などということについては、ご利用者のご要望が多いということは大変承知をしております。指定管理料などのことについても。その点で伺っているのですけれども、その点についていかがでしょうか。","respondent":"松山障害者支援課長","answer":"指定管理制度の中で３年目に行う労働環境チェックは、社会保険労務士が行っております。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、その結果適正な、だから送迎の要望にも十分堪えられるような労働環境であるということを確認した上での、次の指定管理者として継続するという理解でよろしいでしょうか。","respondent":"松山障害者支援課長","answer":"特に送迎ということで特化したものではございませんで、適正な労働環境の下で適切かつ安定的な履行が確保されるよう、指定管理者の従業員の労働関係法令の遵守に関わる評価を実施したというものです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"モニタリングもきちんとされているということで理解をいたしましたが、やはりできる限り利用者のご要望には応えるべきだと思うのですけれども、一方で、それに伴う労働環境というものが苛酷なものになっていってしまうことはよくない、当然皆さんそうお思いだと思いますが、その辺については継続して、事業継続に当たってはきちんと区としても配慮をしていただけるように、これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"やなぎさわ委員","kind":"提案","question":"今回の選定理由のところで、３ページのところですけれども、財務基盤の面から安定的な運営が期待できるということでありまして、今回の総合点数というものが、一括であるといいますか、以前の選定の報告書だと大体提案内容と財務評価のようなもので２つに分かれて点数が出ていたと思うのですが、財務基盤が安定していることで高い評価だと思って、この辺の点数の区分といいますか。","respondent":"松山障害者支援課長","answer":"内訳は福祉部の内訳と一緒ですので、変更はございません。","id":"exchange-039"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"では内訳は一緒であるとして、そのうちの、例えば財務の評価というものはどれぐらい、何点満点中何点などということで、把握しているようであれば教えていただきたいです。","respondent":"松山障害者支援課長","answer":"福祉部で、おっしゃるように分けているものもあるかもしれませんが、総合得点でしか特に評価をしておりませんので、財務が高くほかが低いということではありませんということを申し上げます。","id":"exchange-040"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"できれば、そうですね、そうなのです。そのような意味で、もし今後改善など検討できるようであれば、ご意見をいただきたいのですけれども。","respondent":"松山障害者支援課長","answer":"ご意見としては承ります。統一して表記については考えてまいります。","id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"一応１つ確認ですけれども、報告書を見ていると、例えばカフェレストランも引き継いで売上げが上がって、何か非常に活気が出ているような感じもしますし、定員が増えたり等しているというところで、数字の上では非常に改善されているのかなと思うのですが、利用者の満足度も含めて、やはり前任の法人に比べて。","respondent":"松山障害者支援課長","answer":"あわせて、地域住民を招いたぐるっぽ祭り等々、町会との良好な関係づくりに取り組んでいることが評価されていた。成果指標としては、施設やサービス全体に関する満足度が８割を超えており、総括では優良との評価を受けているというところが結果となります。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私のご近所でもあるので、本当によくお伺いしたり、通りかかったりすると、ここに書いてあるとおり、食堂も企業の皆さんがお昼にさっと、女性が１人でも入りやすいというか、メニューにも工夫されているということはこのとおりだと思いますし、誇張もないなというところです。ここに書いてある町会、私の町会ですけれども、まあこのとおりだなと。とても努力していることも評価しています。","respondent":"松山障害者支援課長","answer":"委員ご指摘の１２月の笠原シェフのみんな食堂の件ですが、福栄会としましても、区としましても、調整時間がなかなか厳しくて、何とかご出演いただいたというような状況ですので、これを契機に、今後区としても、福栄会としても、より積極的にぐるっぽのよさをＰＲして。","id":"exchange-043"}]},{"id":"topic-07","title":"第４９号議案、東京都後期高齢者医療広域連合規約の変更","agenda":"第４９号議案、東京都後期高齢者医療広域連合規約の変更","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"この規約のほうは毎回出てきているもので、軽減のためのということなので賛成なのですけれども、この後期高齢者のところでちょっと伺いたいのですが、２段表の保険料率の最終案というところで、１人当たり平均保険料額というところで、増減で１万６,０４４円ということであるのですけれども、１４.４％の増ということで、この１万６,０４４円というものは。","respondent":"山下国保医療年金課長","answer":"他方で、先ほどご説明申し上げましたように、中段のところにありますが、この保険料の増加抑制のための施策ということで、特別対策の実施、今回規約で変更をお願いしているものと、また基金等の活用ということで、様々対策を講じているところです。","id":"exchange-044"},{"speaker":"鈴木委員","kind":"意見","question":"介護保険料も本当に重い負担になっているわけですけれども、それに加えて、後期高齢は２年に一遍の保険料の改定ということで、そのような形で値上げがされてきて、今までが六・何％のものが１４.４％というと、２倍近いぐらいの割合の負担増なので、本当にこれはちょっとひど過ぎる。でも、今日はそれの賛否がどうのということの場ではないので、ここではそれは申し上げませんが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"賛成なのですけれども、やはり制度の抜本的な見直しを、区から国に対して強く求めていただきたいということは申し添えておきます。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-08","title":"第５１号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第５１号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほど後期高齢者医療保険料も過去最大の値上げということだったのですけれども、この国民健康保険も過去最大の値上げではないかというところをちょっと１点確認させていただきたいと思います。そもそも国民健康保険料については、全国知事会や全国市長会、そして特別区長会、特別区長会は毎年国に対して要望も出していますし、おととし、２０２３年だったか、のときには提言も出したのです。国に対して。","respondent":"山下国保医療年金課長","answer":"１点目にございました１８ページのところですけれども、金額としまして１万４,０００円というところにつきましては、やはりかなり額として大きい上がり幅になっているところがあります。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのように要望して、もう限界だと言っているにもかかわらず、その限界をさらに大きく超えて過去最大の値上げということになったということに対してどう考えているのかということを聞いたので、引き続き要望していきますというように、そのような、何というのですか、本当他人ごとのような感じで聞こえてしまうのですけれども、実際にもう本当に物価高の中で。","respondent":"山下国保医療年金課長","answer":"子どもの国民健康保険料ということでのご質問がございましたけれども、先ほど吹き出しのところでご説明申し上げましたように、令和８年度から開始される子ども・子育て支援金制度につきましては、新たな制度として子どもたちを全社会で支えていくというような分かち合い。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その均等割もすごい額ではないですか。でも本来、この人頭税のような子どもの国民健康保険料というものは、私は無償化すべきだと思うのですけれども、でも特別区長会としても無償化というところまでは求めていなくて、子どもの国民健康保険料の軽減措置の年齢拡大と割合の拡大というようなことしか求めていないではないですか。そうあるべきなのではないかと思うのですけれども、その点はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなことも含めて答弁していただきたいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"提案","question":"２３区であれば、子どもの国民健康保険料無償化ということは十分できると思いますので、２３区からやっていくという、そのようなところもぜひ提案もしていただきたいですし、品川区独自にも、今回一般質問でも取り上げましたけれども、国民健康保険の世帯の中に３,６００人くらいの子どもがいて、それを無償化するには１億５,０００万円あればできるというご答弁もありました。","respondent":"山下国保医療年金課長","answer":"保険料水準の統一というものは、都内において進めていかなければいけないというところがございまして、特別区だけでなく、東京都内というところで進めていく中では、赤字補填のための法定外繰入れというものの解消は、東京都等からも求められているところがございまして。","id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問","question":"だから本当に、これは７億６,０００万円、このときは７億６,０００万円ですけれども、もっと前のときは３０億円ぐらい出していたときもあるので、もう本当にこの法定外繰入れを、そもそも仕組みそのものからどんどん減らしてきて、それが保険料に転嫁され、変えられたというようなことで、これだけ余計に払えない保険料というようなことに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"今課長のご答弁の中にも出てきましたけれども、皆保険の仕組みの維持のためというように今私には聞き取れたのですが、この議論というものはずっとありますよね。現在、この国民健康保険料をなかなか払い切れない方もいらっしゃると思うのですけれども、その辺の数字の把握や品川区の現状など教えていただければと思います。","respondent":"山下国保医療年金課長","answer":"実際にその支払いが難しいというような状況をしっかりと把握をして寄り添った対応ということは、これまでも努めてきているところですし、今回も、いわゆる保険料として値上がるという形のご提案を申し上げている中では。","id":"exchange-053"},{"speaker":"吉田委員","kind":"確認","question":"その方たち、それを全部、何というか、セーフティーネットとして支えるべき制度だと思うのですけれども、その中で、やはり現にもう国民健康保険料が払い切れないというような方のお声は、生活者ネットワークにも届いております。そのようなことについて、区としては、全体としての制度から漏れているような人たちも含めての把握というものはされていないのでしょうか。改めて確認させてください。","respondent":"山下国保医療年金課長","answer":"そういった観点からも、もちろん制度の公平公正な運営からは、保険料というものは、保険制度ですのでお支払いいただく必要があると認識していますけれども、個別の具体な事情についてはしっかりご相談をお聞きしながら、対応に努めているところです。","id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、子ども・子育て支援金なのですが、段階的に上げていくというような話も聞いておりますけれども、要は、今の金額よりも今後上がるのか、そういった予定についてお伺いしたいです。","respondent":"山下国保医療年金課長","answer":"国のほうから、実態上はこども家庭庁のほうから示されるところの子ども・子育て支援金制度の仕組みにつきましては、今委員からございましたように、段階的に進めていくという中で、令和８年度は６,０００万円、令和９年度は８,０００万円、令和１０年度は１兆円というように。","id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"確認","question":"要は、今はある意味６割で、２年後には１０割にいくということだと思うのですが、確認できました。","respondent":"山下国保医療年金課長","answer":"他方で区の場合は、１８歳以上の被保険者の方には、その分、７３円ずつ均等割額に加算されるというようなところで、制度、仕組みとしてはそのような形、１８歳未満の方の部分を１８歳以上の方にご負担いただくような形で認識をしています。","id":"exchange-056"},{"speaker":"やなぎさわ委員","kind":"確認","question":"そうですね。私としては、子どもに国民健康保険料を取るということ自体に対しての受け止めだったのですが、かしこまりました。確認しました。以上です。大丈夫です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"鈴木委員","kind":"質問・要望","question":"反対です。これだけ本当に構造的な問題があって、国民健康保険の負担がもう限界だということで、全国知事会も全国市長会も特別区長会も言っているという、求めているという状況にもかかわらず、過去最大の値上げ額を更新するということは、私は自治体自らが矛盾に対して対策を取らず、逆行するという状況になっていると思います。ということで反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークとしては、これたしか広域化のときにすごい大きな議論になりまして、皆保険の仕組みといいながらどんどん皆保険の仕組みではなくなっているよねというような議論も、そのときから始まっていたと思います。このたびのこの案については、それと矛盾するということで反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"意見","question":"反対でお願いします。もう当然国の制度ですので、区でできることというものは限られているとは思いますけれども、その区にできることというと、それこそまさに子どもの国民健康保険料金の無償化、１.５億円でできるというところもありますし、あとやはり法定外繰入れもしっかり行っていって、これを１００％にしてもうなくすというのではなくて、むしろやはり維持してほしいと思います。反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"}]},{"id":"topic-09","title":"令和８年陳情第３号、「労働」ではなく質の高い「訓練」のサービス提供ができる就労継続Ｂ型事業所を誘致・育成するよう、区に求める陳情","agenda":"令和８年陳情第３号、「労働」ではなく質の高い「訓練」のサービス提供ができる就労継続Ｂ型事業所を誘致・育成するよう、区に求める陳情","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"今のご説明の中に交通費のことはありましたか。ごめんなさい。聞き漏らしていたら申し訳ないのですけれども、やはり私が直接伺う中では、就労継続支援Ｂ型の工賃よりも、もう上回ってしまう。それで、この間、前のときにタクシー券、タクシー券とおっしゃったのですよね。タクシー券は、結構基準厳しいのではないですか。教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"前回の陳情に対することは交通費のことがテーマになっておりましたけれども、交通費と工賃のみを比較するものではないということをご説明申し上げました。工賃は、生産活動の収入から実際に使われたものを引いたものです。","id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"自分の能力という言い方はどうなのでしょうか、自分がやりたい仕事と、それからやっている場所とご自宅の間、どうしても行かなければいけないわけです。それを負担を減らすためには、送迎をつけていただくか、交通費の支給というものがどうしても必要だと思います。そのときに、その１つに、やはり往復の送り迎えか、交通費というものはどうしても必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"交通費については、労働であれば必ず交通費が伴うものと考えておりますけれども、交通費の支給がイコールモチベーションアップにつながるかどうかということは、今後ご意見を伺いながら検討してまいりたいと考えております。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問","question":"すみません。言い方がまずかったと思います。結局保護者がいらっしゃるとして、その保護者の負担になっていくわけです。それはやはり就労継続の活動としても、区としても、絶対通ってほしいと思っていらっしゃるに違いないと思うのですが、そこは意欲をそぐ結果にはならないのか、それでも通うべきだとお思いになるのか、その辺について改めて伺いたいと思います。","respondent":"松山障害者支援課長","answer":"先ほど申しました地域自立支援協議会で就労支援部会がありますので、そちらのほうで事業者から意見を吸い上げて、どのようにモチベーションアップを図っていくかというところについては、今後研究してまいりたいと考えております。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"自立支援協議会の、何というのでしょう、本会、本会というのですか、自立支援協議会のほうには傍聴ができるのですけれども、たしか部会のほうは傍聴ができないのではないかと思うのですが、今までの具体的な、例えばこのようなことをすれば意欲が高まるのではないかとか、事業者が誘致できるのではないかということで、課長の価値観で、これはいい議論だったということで結構なので。","respondent":"松山障害者支援課長","answer":"就労支援部会や区に寄せられるご意見としましては、区内事業所が、作業内容が既定のもので、新たなものを参入してほしいというご意見はいただいておりましたので、今、区内にはない作業メニューを提供できる事業者に、開設相談のときに状況をお話しして。","id":"exchange-064"},{"speaker":"吉田委員","kind":"提案","question":"そのご議論分かりました。新たな事業をなどと思うと思うのですけれども、ぜひその辺、もう少し詳しく教えていただければと思います。それから、共同受注の仕組みというものを私もすごく必要かなと思っていて、私、たしか区のほうの障害者雇用の一般質問をしたときに、共同受注の仕組みというものは有効なのではないかというように提案したと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"Ｋｉｔａｒａですか。「来たら」ということですね。Ｋｉｔａｒａではどのような共同受注の仕組みになっているのか。やはり共同受注の仕組みも、発注者が発注しやすいものがないと、なかなか共同受注というものは難しいかと思うのですけれども、どのような受注の仕組みになっているのか教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"各事業者とも、通常どおり受注は受け、納入はしているのですが、大口注文が入ってきたときに、１か所の事業所では対応できないために、区内の事業所にＫｉｔａｒａのコーディネーターが声をかけて、手挙げしたところに参入していただいて納入したという実績について。","id":"exchange-066"},{"speaker":"吉田委員","kind":"提案","question":"ということはあれですね。分かりました。もちろん事業所が増えないことには、それらの人たちを全部包摂することは難しいかもしれないのですけれども、その辺についての状況の把握や今後の対策など、それは障害者支援課なのか、それとも自立支援協議会での議論を待つべきなのか、ちょっと私には判断がつかないのですが、その辺についての見解を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"それから３つ目が、就労継続支援Ｂ型が就労継続支援Ａ型に、または生活介護の方が就労継続支援Ｂ型にというようなご希望については、今後、午前中お話ししました就労選択支援のサービス事業所がおりますので、まずはご希望をお伺いして、就労についてのアドバイス等。","id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。それが何か、本当に作業のための作業のようなものもあったりして、ちょっとここは具体的には省きますけれども、作業もあったりするので、その辺についての状況把握や、生活介護での作業というか、そのようなことについての今後の見解があれば伺いたいと思います。","respondent":"松山障害者支援課長","answer":"委員がお尋ねの生活介護での作業についてですけれども、生産活動として取り組んでいるところもありますし、ご本人のご希望がまず第一で、そのご本人のご希望に沿ってどのようなプログラムを提供するかですので、またそれは事業者とともに研究してまいります。","id":"exchange-068"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはあまりに私も、その障害者支援というものについてどう考えているのかなというような作業が現に行われていて、それはそこへ支援に行っている方から、「ちょっとこんな作業が行われているのよ」と、「これは本当に何かばかにしているのではないかと思わない」というご意見がいただいたことがあります。これは強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、今交通費がかかっている方がどれくらいいるのかということを私も質問したときに、区のほうとしては、交通費がかかっている方は区では把握していませんということだったのですけれども、ちょっと就労継続支援Ｂ型に通われている方に、どれくらい交通費がかかっている人がいて、どれくらい額がかかっているのかということを、区のほうでまず把握していただけないかと思うのですが。","respondent":"松山障害者支援課長","answer":"交通費の把握についてのご質問です。自立支援協議会の就労支援部会の中でも、課題としては上がってきておりませんので、また委員のご提案も含めまして、就労支援部会のほうで検討してまいりたいと考えております。","id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここの陳情の中でも、就労継続支援Ｂ型の人口当たりの定員数というものは２３区で最低だというようなことで書かれているのですけれども、これからもいろいろと開設の相談も受けているし、増える見込みだというようなことでも、前のときもご答弁いただいているのですが、区としては、就労継続支援Ｂ型に対して必要量というものはどれぐらい必要だと今の時点で考えているというものがあるのか。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"２３区の状況についてですが、特に交通費に対して課題であるという認識をしていないので、把握しておりません。就労継続支援Ｂ型の必要量というところのご質問ですが、具体的な数値として把握しているものではございませんけれども、様々な障害福祉計画に載せております実績、それから見込み量であったり。","id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから就労支援部会というものは、多分就労継続支援Ｂ型だけではなくて、ほかの就労支援なども含まれているのかと思うのですけれども、私は就労継続支援Ｂ型は就労継続支援Ｂ型で全事業者が集まるような、そのような連絡会でいろいろな、どのようなことをやっているのかだったり、交流だったり、そして区のほうからもいろいろと把握していくだったりなど。","respondent":"松山障害者支援課長","answer":"連絡会についてのお尋ねです。就労支援部会の中で、就労継続支援を主に検討するグループと就労移行支援、それ以外の就労、企業向けの就労を検討するグループと分かれて検討をしています。年に３回以上顔を合わせる機会がありますので、そちらのほうでやっていきたいと思います。","id":"exchange-072"},{"speaker":"やなぎさわ委員","kind":"質問","question":"多分新規開設でｅスポーツを前面に押し出しているようなところというものは初めて私見かけたので、何だろう、今後増えるのかなと思ったり、とはいえ、こういったガイドラインなどでも、やはりあまり適切ではないというようなことでも例示がされているというところで、一体どのようなことをして、どれぐらいの、何ですか、質の高い訓練が提供されるのかということを含めてなのですが。","respondent":"松山障害者支援課長","answer":"ガイドラインの生産活動の適切性の部分ですけれども、ｅスポーツや植物の水やりを１日数回行うだけの活動と例示されている中で、先ほどもご説明しましたように、その後が以下の観点、根拠条項等を踏まえて詳細に確認することということです。","id":"exchange-073"},{"speaker":"やなぎさわ委員","kind":"質問","question":"すみません。そうですね。私もちょっと今表現が悪くて訂正します。恐らく求人募集で、要はうちはｅスポーツをやるよということで前面に押している、要は利用者向けの宣伝ではなくて、求人として、恐らくｅスポーツという、何ですか、新しいというか、取組をやっている事業所ですということを１つうたい文句にして求人をかけている。分かりました。把握はしていないということでよろしいですね。分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただければと思いますが、先ほどちょっと質疑の中で、就労継続支援Ｂ型に空きがなくて生活介護から行けないのではないかというようなお話が委員からあったのですけれども、実際何かこう就労継続支援Ｂ型が、今必要量の見込みなども決まっていないという中で、そこはこれからぜひ必要量については考えていくということなのだろうなと思っているのですが。","respondent":"松山障害者支援課長","answer":"就労継続支援Ｂ型については、空きがない状況ではありません。ただし、実際のご希望する作業とマッチするかどうかということ、全ての方のご希望にかなえられない状況があることは事実です。","id":"exchange-075"},{"speaker":"大倉委員","kind":"質問・要望","question":"生活介護の生産活動もあるということだったのですけれども、どのくらいあるのか教えていただきたいということと、あと、例えば希望があれば、希望しているものと空きがマッチしないというか、希望が多いところには当然人が集まるということなのだと思うのですが、そうすると、先ほど言っていた新たなメニューなどを増やしながらというところにつながるのかなというところであるのですけれども。","respondent":"松山障害者支援課長","answer":"例えばぐるっぽのカフェレストランは、最初定員２０名で設定していましたが、令和６年度末で８人です。そういったカフェレストランで働きたいというご希望の方は少ないように感じますけれども、そことのマッチングです。","id":"exchange-076"},{"speaker":"えのした副委員長","kind":"質問","question":"本日結論を出すで、不採択です。設置数も利用者数も増えているということで、私も実際地元の地域に先日、まだ運営はこれからだと思うのですが、就労継続支援Ｂ型の事業所ということで、入り口に、もう既に、何というのですか、看板というものが出ていて、ああ、増えているなということを実感しているところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"大倉委員","kind":"質問・要望","question":"交通費や事業所の送迎の部分があまりあれだったのですが、他区で交通費出しているところなどはまだ把握されていないなどというお話だったので、このようなことも含めて、あと実情が、まだ把握ができていないところでは、就労継続支援Ｂ型の必要量など、この辺ぜひ区としても進めていっていただきたいなと思うものの、今できることをしっかりとやっていっていただいているということで、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと４４９人のうち１５３人が区外、３分の２は区内というところで、例えばどう見るかというところはあると思うのですけれども、区内でもしっかり取り組まれているということで、共同受注の仕組み、これも始まったばかりですが、Ｋｉｔａｒａで、私も開設してからすぐ、ここへ拝見しに行きましたけれども、うまく稼働し始めているというところ、質の高い就労継続支援Ｂ型事業所というところでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いしたいと思います。やはり私は１５３人も区外の事業所に通わざるを得ないということは、やはりもっともっと区内に必要だと思います。必要量をしっかりと把握して、施設整備に向かっていっていただきたいと思っています。そのようなことなので、ぜひこのような趣旨で取組を進めていただきたいということで、採択をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうか、就労継続支援Ｂ型、でも助成しても大丈夫なのか、就労継続支援Ａ型は収入、本人の手元に渡るものは、やはり事業の中から出さなければいけないという制約がたしかできたので、その辺の言い方はちょっと不適切だったら修正していただきたいと思うのですけれども、やはり就労の場であるというように言っている以上、交通費というものは最低限ではないかなと思いますし、直接ご意見を伺うのでも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。こういったことが制度のはざまといいますか、抜け落ちていてるところだと思うので、ぜひこういった課題を提示され、陳情者が提示していただいて、これ区でも議論を深めて、部会という話もありましたけれども、区でもしっかり、委員会含めて様々議論を深めて、ぜひ実現に向けて動いていただきたいなと、そういった思いで採択をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"}]},{"id":"topic-10","title":"令和８年陳情第４号、２３区最低の障害者福祉から脱却するために、小山７丁目障害者グループホームの公平公正な入居選考を区に求める陳情","agenda":"令和８年陳情第４号、２３区最低の障害者福祉から脱却するために、小山７丁目障害者グループホームの公平公正な入居選考を区に求める陳情","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ求めていただきたいと思いますし、その選考基準を見れば、区の重度を受け入れてほしいというような要望を施設側がきちんと受け入れているかどうかの判定にもなりますので、その点についてまず伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"こちらの施設の入居の選考の基準ですが、先ほどご説明させていただいたとおり、区のほうでも公平公正なというような形で、様々な状況に配慮した選考を行うようにということで求めておりまして、事業者のほうで、基準の作成、入居選考の方法について、準備。","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問・要望","question":"選考は事業者に任せているとしても、やはり区がそれ、その事業については区も関わっていることですから、それを求めることは当然ですし、不都合は何もないような気がするのですけれども、その点について、これ随分、私が厚生委員会などに参加するようになるずっと前から、これについては議論があったように思うのですが、なぜ選考基準を事業者に公表を求めないのか、その辺について伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"前提としまして、申し上げたとおり、入居選考基準、事業者が作成して入居選考を行うという形で、区としましては、その選考方法について協議、それから様々な申入れをするという形ですので、入居の基準自体を最終的に公表するという形については。","id":"exchange-084"},{"speaker":"吉田委員","kind":"質問・要望","question":"ああ、そう。無償で。事業者の立場から見て。そのとおりの選考基準になっているかどうかが客観的に事業者としては証明できるわけですから、それを区としても、命令が無理であれば、このようなメリット、事業上のメリットもありますよ、事業者としての公平性を示すことになりますよということで求めることはなぜできないのか、ぜひそれをやっていただきたい。","respondent":"佐藤障害者施策推進課長","answer":"一方、事業者が作成した基準を公開につきましては、基本的には事業者において公開等は考慮していただく部分になるかと思いますが、区としましては、内容についてはきちんと確認してまいりますし、当然この事業者、先ほど区が土地無償貸付けというところでありましたけれども。","id":"exchange-085"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのような、きちんと公平公正な選考しているのであれば。それからスプリンクラーの設置のことを書いてありますけれども、スプリンクラーは設置していると思われますがとなっているのですけれども、本当に事業者の言うとおり支援区分５・６の人たちを入居させるということであれば、スプリンクラーの設置は必要だと思うのですが、その点についていかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"今の２つ目、グループホームとしてそもそも開設する場合に、今委員おっしゃるとおり、区分の重い方、障害の重い方、火災等のときにすぐに避難することが難しいというような状況もありまして、消防の関係で。","id":"exchange-086"},{"speaker":"吉田委員","kind":"質問・要望","question":"通院等介助はできませんよというように言われて、そのときに不満そうな顔をしたということはすごい主観的な価値判断で全然客観的な理由にはならないかなと思うのですけれども、体験入居もさせなかったということであれば、これはもう不誠実なやり方としか言いようがないかなと思うのですが、この事実については、どのようにお考えでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"それから陳情のほうに記載のあります、入居の不可についての経過といいますか、事例ですけれども、このとおりの事例というところでは、こちらで確認できているものではございませんので、今回小山七丁目グループホームに関しましては、改めまして、先ほど申し上げたように。","id":"exchange-087"},{"speaker":"吉田委員","kind":"質問・要望","question":"これ以上やり取りしても繰り返しになると思いますので、ここでやめますけれども、やはり選考基準、区が関わっている以上、選考基準というものを区の責任として明確にしていくことが、品川区の障害者福祉に対する区民からの信頼にもつながると思いますし、使用貸借である以上、絶対それは、区の資産といっても結局は区民の資産なわけですから、そこは強く求めていっていただきたいと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"鈴木委員","kind":"質問","question":"１つ、陳情の３ページの一番上にある東京都の整備補助の加算を受けていれば、支援区分４以上を８割以上にすることが必須ということで書かれていて、本当にそのような制度になっていると思うのですけれども、ということは、ここの施設は区分４以上が８割以上になる、そのような施設ということで考えていいのでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"陳情のところに記載の東京都の整備補助の加算、それから支援区分４以上が８割というようなことですけれども、基本的には記載のとおりというようなところにはなりますが、どの時点でというようなところの確認、これから入居、応募等受けてまいりますので。","id":"exchange-089"},{"speaker":"鈴木委員","kind":"質問","question":"医療的ケアの方も入れるグループホームになるのか、そうした場合の職員配置というものもどうなっていくのか、それから、施設の対応というものも、医療的ケアの方を受け入れられるような、そのような施設の仕様になっているのか、その点についても教えてください。","respondent":"佐藤障害者施策推進課長","answer":"状態や医療的ケアの種類等によって、場合によってはお受けできる場合もあるかもしれませんが、基本的には難しいというようなところでの施設、そのような意味では、職員の体制もまだ専門職等の具体的な配置等については、こちらのほうも確定のところは伺っておりませんけれども。","id":"exchange-090"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その辺のところもしっかりと区が絡んでやっていただきたいと思います。そのような形で障害のグループホームの入居者も決めたほうが、皆さんが納得いくのではないかなと思うのですけれども、その辺のところは、何かそのようなものに、何というのですか、支障があるのかどうなのか、その考え方についても伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"開設時期と説明会の関係ですけれども、こちら順を追いますと、４月に説明会をさせていただいて、それから見学等も行っていただき、５月に面談で６月から入居、もしくは体験等が開始するというようなところで設定しているというようになっております。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それが４月に初めてということだと、すごくぎりぎりという感じではないかなと思うのですけれども、最終の説明会がいつなのかも教えていただきたいと思います。それに応えて、公開はぜひするようにということを区が求めるべき、本来であれば区がつくってこのような基準でやってくださいというものであるべきなのではないかなと私は思うのですけれども、その辺の考え方についても改めて伺います。","respondent":"佐藤障害者施策推進課長","answer":"それで、改めて４月に、建物ができたというような状況もありますので、そちらをご覧いただいた上で、見学等も含めまして、申込み等を検討いただいてというところで、繰り返しになりますが、４月に説明会、５月に見学や面談というような形で、開設が６月というところで。","id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もっと利用者の側から、この説明会や、もっと考えられる時間をしっかりと検討できるぐらいの、そのような説明会というものを、やはり無償で土地を提供している区からも言っていただきたいと思いますし、これから戸越四丁目のグループホームもそのような方向で流れていくと思いますので、戸越四丁目のところにはこのような形でぜひ進めていただきたいと思うのですけれども、最後いかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"おっしゃったように４月説明会というところですが、３月にもうすぐ入るところですけれども、相談支援事業所などや連絡会等について、周知というようなところは考えているところがあります。","id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"民設民営とはいえ、区が無償で土地を貸与している以上、やはり入居者選考基準の公表が一番シンプルだと思うのですけれども、それは求めるという前提でお伺いしますが、今回、東京都の整備助成の加算が入っていて、支援区分４以上の方が８割以上が必須だということになっていますし、当然８割以上入らないと法令違反ということになるわけで、これはもちろん区としても、一応確認ですけれども。","respondent":"佐藤障害者施策推進課長","answer":"最初に冒頭でもありましたけれども、今回、この運営事業者を選定するに当たっても、事業者のほうからの提案で、支援区分の目安としての入居の人数等も聞いているところありますので、そういったところも踏まえて、入居の結果、それから応募状況が。","id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"確認できました。これ令和６年９月ということなのですが、現在の見込み、今設置要求された、開設予定で見込みなども含めて、もし数字で分かれば、今この１.２という数字がどれぐらいなのかということが、大体でもいいのですけれども、どれぐらいのところに上がりそうなのかということを、少し分かればお教えていただきたいのですが、いかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"直近の数字というものを、申し訳ありません、持っていないのですけれども、この後、それから今回の案件も含めまして、中重度の方の入居を進めていくというようなところありますので、支援区分６というものはなかなか、かなり重度の方になりますので。","id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問","question":"出石つばさの家が開設されたというところで、恐らく数字は上がってくるとは思うのですけれども、それほど物すごい数字が跳ね上がるほど、恐らく７名や８名ぐらいの入居だったと記憶しておりますので、そう考えると、やはり全体的にまだまだ不足感があるなというような認識は、区のほうでされているということでよろしいでしょうか。グループホームについて。","respondent":"佐藤障害者施策推進課長","answer":"とはいえ、今の形のところですと、重度の方はなかなかすぐに進まないというようなところもあるかと思いますので、今、ほかの区等でもありますけれども、日中サービス支援型や新たな類型のところも含めて、開設等につきましては、民間の誘致も含めまして。","id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"確認","question":"課題を持っていただけるというところは確認できました。ぜひ積極的に進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは１点だけ、皆様のお話を伺っていて、今回の陳情の趣旨である公平公正な入居選考を行うよう求めてくださいというところについては、区のほうで十分に求めているという認識を受けましたが、この方のご心配というものは、今までの例であったように、思ってもいないような結果になってしまう。ただ、区がこれだけ求めていて、運営事業者の側もこれだけ言っていて、先ほど東京都の縛りもある。","respondent":"佐藤障害者施策推進課長","answer":"応募状況も含めて今後どうなっていくかというところはありますが、最大限障害の重い方等には配慮して進めていくですので、ここについて申込み、応募があったのに多数の方が万が一入れないというような状況があるというようなところで、そうなった場合については。","id":"exchange-098"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"本日結論を出す。ひとまず民設民営ですので、運営業者が選考する。とはいえ、区は事業者に対して、公平公正に利用者との面談や、もちろん中重度の方も入れるように求めております。この開設時期が遅れるということも、利用者に対しても地域でも、住民説明会をこれからもしていくということですし、支援区分も考慮に入れて選考を求めていくということです。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"大倉委員","kind":"質問・要望","question":"今のこの陳情の中でもありますが、課長の答弁では、支援区分５・６が３名から４名程度ということや、あと東京都のほうの支援区分４以上が８割になるようというところで、今東京都の加算を受けてやっていくというところでいうと、区としても、重度の方がしっかり受け入れられるようにということで進めているのだということであると思いますし、今お話を様々、委員間でしているものを伺った中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"あくつ委員","kind":"確認","question":"内容については先ほど確認させていただきましたが、区が入居選考基準の作成はしませんというところで、民設民営であって、それは運営主体者がしっかりやるものですというご説明で、先ほども、繰り返しになってしまいますけれども、幾つかもう区としてもやるべきことはやっているのですというご説明があって、このような縛りもあって、運営事業者からのお話もあって、その上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いしたいと思います。４月に説明会ということですけれども、４月ということで決まってしまっているのであれば、４月すぐにやっていただきたいということで、お願いをしておきたいと思います。そして重度の方がしっかりと入れるような、そのようなグループホームにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"吉田委員","kind":"質問・要望","question":"それをきちんと今後も、区としてもきちんと見守っていただきたいと思いますし、もし事業者のほうでそれがかなわないというか、できないようなことであれば、強力に、指導という言い方が適切なのかどうか分かりませんけれども、支援になるのか分かりませんが、区としてもしっかり見ていっていただきたいということは要望して、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。開設後はしっかり支援区分４以上の方が８割いる等も含めて、区が関与していただけるということは確認できましたけれども、そもそもその入居の前の選考基準の時点で、やはり基準を公表するということが一番シンプルだと私も思います。民設民営という形式は今後も増えてくるのではないのかなと、区内の様々な施設において。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/145423?Template=document&Id=7317#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2026-01-01&TermEnd=2026-12-31"}],"sourceMeta":{"pages":0,"characters":85660,"voices":360}}]);
